INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C1','sci',5,1,'u4',1,'뼈와 골격 — 팔이나 다리, 가슴과 등을 만져 보면 몸속에 단단한 뼈가 있음 · 여러 개의 뼈가 모여 몸의 골격을 만듦 · 뼈가 이어진 곳이 접혔다 펴지며 다양한 몸동작이 나옴 · 뼈는 커다란 하나가 아니고 몸의 겉을 껍데기처럼 감싸지도 않음',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C2','sci',5,1,'u4',1,'골격 모형 — 뼈 도안(『과학』 123·125쪽)을 같은 기호끼리 구멍을 맞대고 똑딱단추(13개)로 연결 → 모형으로 다양한 몸동작 표현 → 친구가 표현한 몸동작 따라 하기 → 친구와 함께 다양한 상황 표현 → 몸속 기관을 상상해 모형에 그리기 · 똑딱단추로 이은 곳이 접혔다 펴짐 · 친구 모형을 함부로 잡아당기지 않음',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C3','sci',5,1,'u4',1,'상상하기 — 몸속에는 두근두근 뛰는 곳·숨이 드나드는 곳·먹은 음식이 지나가는 곳 등 여러 가지 기관이 있음 · 무엇이 어디쯤 있을지 상상해 모형에 그려 봄 · 모형과 내 몸이 어떤 점이 같고 다른지 견주어 봄 · 모형은 손으로 움직여야만 자세가 바뀜',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C4','sci',5,1,'u4',2,'기관 — 우리가 살아가는 데 필요한 일을 하는 몸속 부분 · 심장·폐·뇌 등',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C5','sci',5,1,'u4',2,'뼈의 종류 — 우리 몸에는 생김새와 크기가 다양한 뼈가 있음 · 머리뼈(머리를 감쌈), 목뼈, 갈비뼈(가슴을 둘러쌈), 척추뼈(등 한가운데), 팔뼈(위팔뼈·아래팔뼈), 다리뼈',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C6','sci',5,1,'u4',2,'뼈의 기능 — 몸의 형태를 만들고 몸을 지탱함 · 심장·폐·뇌 등 몸속 기관을 보호함 · 뼈 스스로는 움직이지 못함',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C7','sci',5,1,'u4',2,'근육 — 뼈에 연결되어 있음 · 근육이 줄어들거나 늘어나면서 뼈를 움직여 몸이 움직임 · 근육은 줄어들며 당길 뿐 뼈를 밀어내지 않음 · 뼈는 스스로 구부러지거나 늘어나지 않음',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C8','sci',5,1,'u4',2,'팔의 근육 — 팔을 구부릴 때: 팔 안쪽 근육이 줄어들고 바깥쪽 근육이 늘어나 아래팔뼈가 따라 올라감 · 팔을 펼 때: 바깥쪽 근육이 줄어들고 안쪽 근육이 늘어나 아래팔뼈가 따라 내려감 · 펴는 일도 반대쪽 근육이 줄어들며 함',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C9','sci',5,1,'u4',2,'뼈와 근육 모형 — 팔을 구부렸다 펴며 다른 손으로 만져 관찰 → 뼈와 근육 도안(『실험관찰』 79·81쪽)을 똑딱단추 6개로 차례대로 연결(아래팔뼈 도안을 위팔뼈 도안 사이에 끼움) → 손잡이를 잡아당겼다 밀며 안쪽·바깥쪽 근육 도안과 아래팔뼈 도안의 변화 관찰 → 팔 근육의 변화 이야기 · 풀로 붙여 움직이지 않게 하지 않음 · 끝나면 모형을 올바르게 처리',ARRAY['뼈와 근육의 생김새와 기능을 이해하고, 뼈와 근육 모형으로 몸이 움직이는 원리를 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C10','sci',5,1,'u4',3,'소화 — 음식물 속의 영양소를 몸에서 흡수할 수 있도록 음식물을 잘게 쪼개는 과정 · 이를 담당하는 기관이 소화기관 · 우리는 음식물에서 몸에 필요한 영양소를 얻음 · 음식물은 소화기관을 지나며 점점 잘게 쪼개짐(커지지 않음)',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C11','sci',5,1,'u4',3,'소화 경로 — 입 → 식도 → 위 → 작은창자 → 큰창자를 거치며 소화됨 · 영양소와 수분은 몸속으로 흡수되고 나머지(음식물 찌꺼기)는 항문을 통해 몸 밖으로 배출됨 · 찌꺼기가 몸속에 쌓이지 않음',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C12','sci',5,1,'u4',3,'기관별 일 — 입: 이로 잘게 부수고 혀로 침과 섞어 물러지게 함 · 식도: 음식물이 위로 이동하는 통로 · 위: 소화를 돕는 액체를 분비해 음식물을 잘게 쪼갬 · 작은창자: 더 잘게 쪼개고 영양소와 대부분의 수분을 흡수 · 큰창자: 음식물 찌꺼기에서 수분을 흡수 · 항문: 찌꺼기를 몸 밖으로 내보냄 · 흡수는 위에서 다 끝나지 않음',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C13','sci',5,1,'u4',3,'간·쓸개·이자 — 음식물이 직접 지나가지는 않지만 소화를 도와주는 소화기관 · 소화와 관계없는 기관이 아님',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C14','sci',5,1,'u4',3,'소화 과정 모형 — 소화기관 도안의 그림과 이름을 색연필로 연결하고 기능 조사 → 음식물이 지나가는 자리에 구멍을 내고 도안을 반으로 접음 → 소화 과정 막대를 넣고 위아래로 움직이게 붙임 → 막대를 천천히 내리며 음식물의 모습 관찰 → 경로 이야기 → 정리 · 음식물을 꼭꼭 씹어야 잘게 쪼개지고 물러져 소화가 잘됨',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C15','sci',5,1,'u4',4,'순환 — 우리가 살아가려면 혈액이 끊임없이 온몸을 돌아야 함 · 혈액의 이동 = 혈액 순환 · 이를 담당하는 기관 = 순환기관(심장과 혈관)',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C16','sci',5,1,'u4',4,'심장 — 가슴 중앙에서 왼쪽으로 약간 치우쳐 있음 · 끊임없이 펌프 작용을 하여 혈액을 온몸으로 보냄 · 혈액을 새로 만들어 내는 곳이 아님',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C17','sci',5,1,'u4',4,'혈관 — 혈액이 이동하는 통로 · 머리끝부터 발끝까지 온몸에 퍼져 있음(심장 가까이에만 있지 않음)',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C18','sci',5,1,'u4',4,'혈액 — 심장에서 나온 혈액은 혈관을 따라 이동하며 영양소와 산소를 온몸에 운반하고 다시 심장으로 돌아옴 · 이 순환 과정을 끊임없이 반복함 · 소화기관이 흡수한 영양소도 혈액이 온몸으로 나름',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C19','sci',5,1,'u4',4,'모형실험 — 식용 색소를 녹인 물에 한쪽 호스를 넣고 펌프를 쥐었다 폈다 하며 붉은 색소 물의 이동 관찰 · 펌프 = 심장, 호스 = 혈관, 붉은 색소 물 = 혈액 · 펌프를 멈추면 물도 멈춤 · 눈에 튀지 않게 조심, 맛보지 않음, 정리 · 심장박동이 멈추면 혈액이 순환하지 못해 영양소와 산소를 운반할 수 없으므로 빠른 시간 안에 심폐 소생술을 해야 함',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C20','sci',5,1,'u4',5,'호흡 — 숨을 들이마시고 내쉬는 활동 · 담당 = 호흡기관 · 코: 공기가 드나드는 곳 · 숨관: 공기가 이동하는 통로 · 숨관가지: 숨관과 폐를 연결하며 공기가 이동하는 통로 · 폐: 산소를 받아들이고 이산화 탄소를 몸 밖으로 내보냄 · 공기의 길과 음식물의 길은 다름',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C21','sci',5,1,'u4',5,'들이마시기 — 공기가 코 → 숨관 → 숨관가지 → 폐로 들어감 · 폐는 우리 몸에 필요한 산소를 받아들임 · 산소는 몸을 움직이거나 몸속 기관이 일하는 데 쓰임 · 수영할 때 얼굴을 물 위로 내미는 것도 공기를 들이마셔 산소를 받아들이려는 것',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C22','sci',5,1,'u4',5,'내쉬기 — 몸속에서 생긴 이산화 탄소를 포함한 공기가 폐 → 숨관가지 → 숨관 → 코를 거쳐 몸 밖으로 나감 · 들이마실 때의 길을 거꾸로 되짚음(방향이 반대)',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C23','sci',5,1,'u4',5,'호흡기관 모형 — 가슴에 양손을 얹고 천천히 호흡하며 몸의 변화를 느낌 → 주름 빨대 두 개의 긴 쪽을 셀로판테이프로 감고 짧은 쪽을 각각 종이봉투 안쪽에 넣어 감음(공기가 새지 않게) → 호흡기관 붙임딱지를 위치에 맞게 붙임 → 공기를 불어 넣으며 변화 관찰 · 무리하지 않고, 어지럼증을 느끼면 중단 · 정리',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C24','sci',5,1,'u4',6,'배설 — 몸에서 영양소가 쓰이면서 몸에 필요 없는 노폐물이 만들어짐 · 혈액 속의 노폐물을 걸러 내어 몸 밖으로 내보내는 과정이 배설 · 담당 = 배설기관',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C25','sci',5,1,'u4',6,'배설기관 — 콩팥: 혈액 속의 노폐물을 걸러 내어 오줌을 만듦 · 오줌관: 오줌이 이동하는 통로 · 방광: 오줌을 모아 두었다가 몸 밖으로 내보냄 · 오줌은 콩팥 → 오줌관 → 방광 → 몸 밖 · 노폐물이 걸러진 혈액은 다시 혈관을 통해 온몸을 순환함 · 콩팥이 제대로 걸러 내지 못하면 노폐물이 쌓여 건강에 문제가 생김',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C26','sci',5,1,'u4',6,'배설과 배출 — 배설: 혈액 속 노폐물을 콩팥이 걸러 오줌으로 내보내는 것 · 배출: 소화되고 남은 음식물 찌꺼기가 큰창자를 지나 항문으로 나가는 것 · 똥을 내보내는 것은 배설이 아님',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C27','sci',5,1,'u4',6,'생각 그물·체험 — 배설기관의 이름과 하는 일을 가지 쳐 정리해 발표 · 지능형 과학실 ON에서 여러 상황의 기관을 3D로 관찰 · 식사할 때 팔뼈·팔 근육으로 음식을 넣고 얼굴 근육으로 씹음 · 잠을 잘 때도 (활동할 때보다 천천히) 호흡함 · 화장실에 가는 동안에도 소화기관은 먹은 음식물을 소화함 · 한 상황에서도 여러 기관이 함께 일함',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C28','sci',5,1,'u4',7,'측정 — 체온: 몸의 따뜻한 정도(체온계로 잼) · 맥박: 심장의 박동이 목이나 팔목 등에서 느껴지는 것(맥박 수 측정 애플리케이션) · 준비 운동 → 운동 전 측정 → 제자리 뛰기 등 가벼운 운동 → 운동 직후 바로 측정 → 5분 정도 휴식 후 한 번 더 측정 → 그래프로 나타내기 · 친구와 부딪히지 않게 조심 · 결과를 정확하게 기록',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C29','sci',5,1,'u4',7,'변화 — 운동 직후에는 체온과 맥박 수가 운동 전보다 높아지고 땀이 나기도 함 · 휴식을 하면 체온과 맥박 수가 차츰 운동 전으로 돌아감 · 실제 값은 사람마다 다름',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C30','sci',5,1,'u4',7,'까닭 — 뼈와 근육이 움직일 때는 산소와 영양소가 필요함 · 산소를 많이 흡수하려고 호흡이 빨라짐 · 산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빠르게 뜀 · 순환기관은 이산화 탄소를 호흡기관으로, 노폐물을 배설기관으로 운반함 · 심장이 빨리 뛰는 것은 단지 힘들어서가 아님',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C31','sci',5,1,'u4',7,'관련 — 소화기관은 영양소를 흡수, 호흡기관은 산소를 받아들임, 순환기관은 운반, 배설기관은 노폐물을 걸러 냄, 뼈와 근육은 산소와 영양소로 몸을 움직임 · 각 기관은 따로따로가 아니라 서로 영향을 주고받으며 작용함 · 운동하는 동안에도 소화·배설기관은 하던 일을 멈추지 않음',ARRAY['소화·순환·호흡·배설 기관의 구조와 기능을 조사하고, 운동할 때 몸의 변화를 통해 여러 기관이 서로 관련되어 있음을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C32','sci',5,1,'u4',8,'질병 — 감기·장염 등 다양한 질병은 우리 몸의 기관과 관련이 있음 · 감기는 호흡기관, 변비·장염은 소화기관과 관련 · 『실험관찰』은 빈혈을 예로 듦 · 질병은 운이 나빠서가 아님',ARRAY['우리 몸의 여러 기관과 관련된 질병을 조사하고, 건강을 유지하기 위한 생활 방식을 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C33','sci',5,1,'u4',8,'증상·예방 — 변비: 똥이 잘 나오지 않음·배가 아픔 / 채소 많이 먹기·물 충분히 마시기·운동하기 · 감기: 기침·콧물·코 막힘 / 손 씻기 · 평소의 생활 습관으로 질병 예방에 도움을 줄 수 있음 · 어린이도 날마다 할 수 있음 · 약으로만 막는 것이 아님',ARRAY['우리 몸의 여러 기관과 관련된 질병을 조사하고, 건강을 유지하기 위한 생활 방식을 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C34','sci',5,1,'u4',8,'조사·공유 — 모둠별로 소화·순환·호흡·배설기관 중 하나를 고름 → 국가건강정보포털 등에서 질병의 종류·증상·예방법 조사(자료가 너무 많으면 검색어가 포함된 자료 활용) → 발표 자료나 책 계획·제작(모둠원마다 만들어 합치거나 하나를 함께) → 공유 플랫폼에 올림 → 다른 모둠 자료에 알게 된 점을 댓글로 · 스마트 기기에서 냄새나 열이 나면 즉시 중지하고 선생님께 알림',ARRAY['우리 몸의 여러 기관과 관련된 질병을 조사하고, 건강을 유지하기 위한 생활 방식을 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C35','sci',5,1,'u4',9,'점검표 — 질병 예방을 위해 건강한 생활 방식을 실천해야 함 · 계획하기(질병 하나 골라 예방 방법 이야기, 넣을 내용 정하기) → 해 보기(점검표 만들기·소개·일정한 기간 실천) → 나누기(느낀 점 발표, 잘한 점 칭찬) · 실천이 가능한 내용으로 · 그림으로 그리면 한눈에 · 자기 전에 하루를 되돌아보며 점검 · 필요한 정보만 검색 · 활동이 끝난 뒤에도 꾸준히 실천',ARRAY['우리 몸의 여러 기관과 관련된 질병을 조사하고, 건강을 유지하기 위한 생활 방식을 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u4-C36','sci',5,1,'u4',9,'착용형 장치 — 생명공학기술의 발달로 몸에 착용하는 장치로 병원에 가지 않고도 건강 상태를 실시간으로 확인 · 손목시계·반지·목걸이·패치 모양이라 착용이 쉽고 편리 · 체온·심장박동 수·혈액에 들어 있는 산소의 양 등을 측정, 수치를 건강 관리 자료로 활용 · 기관에 문제가 발견되면 경고 신호 · 장치가 알려 주어도 실천하는 것은 나 자신',ARRAY['우리 몸의 여러 기관과 관련된 질병을 조사하고, 건강을 유지하기 위한 생활 방식을 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X01','sci',5,'u4',ARRAY['SC5-1-u4-C1']::text[],'몸속의 뼈는 커다란 하나로 되어 있거나, 몸의 겉을 껍데기처럼 감싸고 있다고 여긴다','여러 뼈가 모여 골격을 만들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X02','sci',5,'u4',ARRAY['SC5-1-u4-C2','SC5-1-u4-C9']::text[],'골격 모형이나 뼈와 근육 모형을 만드는 방법을 잘못 안다(풀로 단단히 붙이기, 기호를 보지 않고 잇기, 똑딱단추 개수 혼동 등)','같은 기호끼리 똑딱단추로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X03','sci',5,'u4',ARRAY['SC5-1-u4-C1','SC5-1-u4-C7']::text[],'뼈는 스스로 구부러지거나 늘어났다 줄어들며 움직인다고 여긴다','뼈를 움직이는 것이 따로 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X04','sci',5,'u4',ARRAY['SC5-1-u4-C3','SC5-1-u4-C4']::text[],'기관의 뜻이나 몸속 모습을 잘못 안다(몸 겉의 부분만 기관, 몸속은 비어 있음 등)','살아가는 데 필요한 일을 하는 몸속 부분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X05','sci',5,'u4',ARRAY['SC5-1-u4-C5']::text[],'뼈의 이름과 위치를 잘못 짝짓는다','머리 · 가슴 · 등 한가운데') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X06','sci',5,'u4',ARRAY['SC5-1-u4-C6']::text[],'뼈가 하는 일을 잘못 안다(몸속 기관을 보호하지 않음, 형태와 관계없음 등)','형태 · 지탱 · 보호') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X07','sci',5,'u4',ARRAY['SC5-1-u4-C7','SC5-1-u4-C8']::text[],'근육이 뼈를 밀어서 팔을 편다고 여긴다','근육은 줄어들며 당겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X08','sci',5,'u4',ARRAY['SC5-1-u4-C8']::text[],'팔을 구부릴 때와 펼 때 줄어드는 근육(안쪽·바깥쪽)이나 아래팔뼈의 움직임을 뒤바꾼다','구부릴 때 안쪽이 줄어들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X09','sci',5,'u4',ARRAY['SC5-1-u4-C10']::text[],'소화의 뜻을 잘못 안다(음식물을 크게 만드는 것, 음식물이 점점 커짐 등)','잘게 쪼개 흡수할 수 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X10','sci',5,'u4',ARRAY['SC5-1-u4-C11']::text[],'음식물이 지나가는 기관의 차례를 잘못 안다(작은창자와 큰창자를 뒤바꿈 등)','입 → 식도 → 위 → 작은창자 → 큰창자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X11','sci',5,'u4',ARRAY['SC5-1-u4-C12']::text[],'영양소와 수분의 흡수가 위에서 다 끝난다고 여긴다','작은창자 · 큰창자에서 흡수해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X12','sci',5,'u4',ARRAY['SC5-1-u4-C12']::text[],'소화기관과 하는 일을 잘못 짝짓는다','통로 · 쪼개기 · 흡수 · 내보내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X13','sci',5,'u4',ARRAY['SC5-1-u4-C13']::text[],'간·쓸개·이자는 소화와 관계없다고 여기거나, 음식물이 그곳을 지나간다고 여긴다','지나가지 않고 도와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X14','sci',5,'u4',ARRAY['SC5-1-u4-C11']::text[],'음식물은 모두 흡수되어 남는 것이 없거나, 찌꺼기가 몸 밖으로 나가지 못하고 쌓인다고 여긴다','찌꺼기는 항문으로 나가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X15','sci',5,'u4',ARRAY['SC5-1-u4-C14']::text[],'음식물을 꼭꼭 씹지 않고 빨리 삼켜도 소화와 관계없다고 여긴다','잘게 쪼개고 물러지게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X16','sci',5,'u4',ARRAY['SC5-1-u4-C14']::text[],'소화 과정 모형을 만들거나 관찰하는 방법을 잘못 안다(아무 데나 구멍, 막대를 움직이지 않게 고정, 빨리 내리기 등)','지나가는 자리 · 천천히 내리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X17','sci',5,'u4',ARRAY['SC5-1-u4-C16']::text[],'심장이 혈액을 새로 만들어 낸다고 여긴다','심장은 펌프 작용을 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X18','sci',5,'u4',ARRAY['SC5-1-u4-C17']::text[],'혈관은 심장 가까이에만 있다고 여긴다','온몸에 퍼져 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X19','sci',5,'u4',ARRAY['SC5-1-u4-C18']::text[],'혈액은 온몸을 한 번만 돌고 멈추거나, 심장에서 나가기만 하고 돌아오지 않는다고 여긴다','돌아와서 다시 돌아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X20','sci',5,'u4',ARRAY['SC5-1-u4-C16']::text[],'심장의 위치를 잘못 안다(배 아래, 머리 안, 손목 안 등)','가슴 중앙에서 왼쪽으로 약간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X21','sci',5,'u4',ARRAY['SC5-1-u4-C19']::text[],'순환기관 모형과 우리 몸을 잘못 짝짓거나 실험 방법을 잘못 안다(호스 = 심장, 펌프를 멈추어도 계속 이동, 맛보기 등)','펌프 = 심장, 호스 = 혈관') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X22','sci',5,'u4',ARRAY['SC5-1-u4-C15','SC5-1-u4-C18']::text[],'혈액이 하는 일이나 혈액 순환의 뜻을 잘못 안다(음식물을 쪼갬, 공기를 들이마심 등)','영양소와 산소를 운반해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X23','sci',5,'u4',ARRAY['SC5-1-u4-C19']::text[],'심장박동이 멈추었을 때 서둘러야 하는 까닭을 잘못 안다','혈액이 순환하지 못해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X24','sci',5,'u4',ARRAY['SC5-1-u4-C20']::text[],'호흡기관과 하는 일을 잘못 짝짓는다(코가 산소를 받아들임, 숨관가지가 공기가 드나드는 곳 등)','드나드는 곳 · 통로 · 받아들이는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X25','sci',5,'u4',ARRAY['SC5-1-u4-C22']::text[],'숨을 내쉴 때도 공기가 코에서 폐 쪽으로 들어가거나, 내쉬는 길이 들이마시는 길과 다르다고 여긴다','같은 길을 거꾸로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X26','sci',5,'u4',ARRAY['SC5-1-u4-C20','SC5-1-u4-C11']::text[],'음식물과 공기가 같은 길로 간다고 여긴다(음식물이 숨관을 지나 폐로, 공기가 식도로 등)','공기의 길, 음식물의 길') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X27','sci',5,'u4',ARRAY['SC5-1-u4-C21']::text[],'폐가 하는 일을 잘못 알거나 받아들인 산소가 몸에서 쓰이지 않는다고 여긴다(폐가 영양소를 흡수 등)','산소를 받아 몸이 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X28','sci',5,'u4',ARRAY['SC5-1-u4-C22']::text[],'숨을 내쉴 때 나가는 공기를 잘못 안다(이산화 탄소가 없음, 산소만 내보냄 등)','이산화 탄소를 포함한 공기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X29','sci',5,'u4',ARRAY['SC5-1-u4-C23']::text[],'호흡기관 모형을 만들거나 실험하는 방법·안전을 잘못 안다(숨이 찰 때까지 불기, 테이프로 막지 않기, 어지러워도 계속 등)','무리하지 않고 새지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X30','sci',5,'u4',ARRAY['SC5-1-u4-C26']::text[],'배설을 똥(음식물 찌꺼기)을 내보내는 것이라고 여긴다','배설은 혈액 속 노폐물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X31','sci',5,'u4',ARRAY['SC5-1-u4-C24']::text[],'노폐물이 생기는 까닭이나 뜻을 잘못 안다(먹은 음식물에서만 곧바로 생김, 몸에 필요한 것 등)','영양소가 쓰이면서 생겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X32','sci',5,'u4',ARRAY['SC5-1-u4-C25']::text[],'배설기관과 하는 일을 잘못 짝짓는다(방광이 오줌을 만듦, 오줌관이 노폐물을 거름 등)','거르기 · 통로 · 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X33','sci',5,'u4',ARRAY['SC5-1-u4-C25']::text[],'콩팥에서 걸러진 혈액이 몸 밖으로 나가거나 더 이상 온몸을 돌지 않는다고 여긴다','다시 온몸을 순환해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X34','sci',5,'u4',ARRAY['SC5-1-u4-C25']::text[],'오줌이 나가는 길의 차례를 잘못 안다','콩팥 → 오줌관 → 방광') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X35','sci',5,'u4',ARRAY['SC5-1-u4-C27','SC5-1-u4-C31']::text[],'한 가지 일을 할 때에는 관련 기관 하나만 일하거나, 잠을 자는 동안에는 호흡이 멈춘다고 여긴다','여러 기관이 함께 일해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X36','sci',5,'u4',ARRAY['SC5-1-u4-C28']::text[],'맥박이나 체온의 뜻을 잘못 안다(맥박 = 숨 쉬는 활동, 체온 = 땀의 양 등)','맥박은 심장의 박동이 느껴지는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X37','sci',5,'u4',ARRAY['SC5-1-u4-C29','SC5-1-u4-C30']::text[],'운동하면 호흡과 심장이 느려지거나, 체온이 내려가고 땀이 마른다고 여긴다','빨라지고 올라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X38','sci',5,'u4',ARRAY['SC5-1-u4-C29']::text[],'휴식한 뒤에도 체온과 맥박 수가 운동 직후 그대로이거나 계속 오른다고 여긴다','차츰 운동 전으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X39','sci',5,'u4',ARRAY['SC5-1-u4-C30']::text[],'운동할 때 심장이 빠르게 뛰고 호흡이 빨라지는 것은 단지 몸이 힘들어서라고 여긴다','산소와 영양소를 빠르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X40','sci',5,'u4',ARRAY['SC5-1-u4-C31']::text[],'우리 몸의 기관은 따로따로 일하거나, 운동하는 동안 소화·배설기관은 하던 일을 멈춘다고 여긴다','서로 영향을 주고받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X41','sci',5,'u4',ARRAY['SC5-1-u4-C28']::text[],'체온과 맥박 수를 재는 차례나 방법을 잘못 안다(운동 직후를 건너뜀, 쉬면서 바로 재기, 결과 고쳐 적기 등)','전 · 직후 · 5분 휴식 후') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X42','sci',5,'u4',ARRAY['SC5-1-u4-C32','SC5-1-u4-C33']::text[],'질병은 운이 나빠서 걸리는 것이라 예방할 수 없거나, 몸의 기관과 관계없다고 여긴다','기관과 관련 있고 예방할 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X43','sci',5,'u4',ARRAY['SC5-1-u4-C33']::text[],'질병 예방은 어른이나 약만 할 수 있는 일이라고 여긴다','날마다 할 수 있는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X44','sci',5,'u4',ARRAY['SC5-1-u4-C32','SC5-1-u4-C33']::text[],'질병과 관련 기관, 증상, 예방법을 잘못 짝짓는다','감기 · 변비를 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X45','sci',5,'u4',ARRAY['SC5-1-u4-C34','SC5-1-u4-C35']::text[],'조사하고 나누는 방법·태도를 잘못 안다(가장 위 자료 하나만 옮겨 적기, 우리 모둠만 보기, 필요 없는 것까지 검색하기, 기기에서 열이 나도 계속 쓰기 등)','필요한 것만 · 공유 · 안전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X46','sci',5,'u4',ARRAY['SC5-1-u4-C35']::text[],'점검표에는 어렵고 대단한 목표일수록 좋다고 여긴다(실천할 수 없는 내용 넣기)','실천이 가능한 내용') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X47','sci',5,'u4',ARRAY['SC5-1-u4-C35']::text[],'점검표는 만들기만 하면 되고 실천하지 않거나, 활동이 끝나면 그만두어도 된다고 여긴다','꾸준히 실천해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X48','sci',5,'u4',ARRAY['SC5-1-u4-C36']::text[],'착용형 장치가 있으면 건강한 생활 방식을 실천하지 않아도 된다고 여긴다','실천하는 것은 나 자신') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u4-X49','sci',5,'u4',ARRAY['SC5-1-u4-C36']::text[],'착용형 장치가 재는 것이나 특징을 잘못 안다(뼈의 개수·꿈 내용 측정, 병원에서만, 크고 무거움 등)','체온 · 심장박동 수 · 산소의 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#1','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C2',1,'mc','auto','인체 골격 모형을 만들 때 뼈 도안을 무엇으로 연결하나요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C2","difficulty":1,"kind":"mc","stem":"인체 골격 모형을 만들 때 뼈 도안을 무엇으로 연결하나요?","options":[{"t":"똑딱단추","correct":true},{"t":"물풀","mis":"SC5-1-u4-X02"},{"t":"셀로판테이프","mis":"SC5-1-u4-X02"},{"t":"실과 바늘","mis":"SC5-1-u4-X02"}],"explanation":["준비물을 떠올려요.","눌러서 잇는 것이에요.","똑딱단추예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#2','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C1',1,'ox','auto','팔이나 다리를 만져 보면 몸속에 단단한 뼈가 있다는 것을 알 수 있어요.',ARRAY['SC5-1-u4-X04']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C1","difficulty":1,"kind":"ox","stem":"팔이나 다리를 만져 보면 몸속에 단단한 뼈가 있다는 것을 알 수 있어요.","answer":"O","reason_options":[{"t":"만져 보면 몸속에서 단단한 것이 느껴지기 때문에","correct":true},{"t":"몸속은 텅 비어 있어 아무것도 느껴지지 않기 때문에","mis":"SC5-1-u4-X04"}],"mis":"SC5-1-u4-X04","explanation":["내 팔을 만져 봐요.","단단한 것이 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#3','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C1',1,'sa','auto','「여러 개의 뼈가 모여 몸의 □□을 만듭니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C1","difficulty":1,"kind":"sa","stem":"「여러 개의 뼈가 모여 몸의 □□을 만듭니다.」 □□에 알맞은 말을 쓰세요.","answer":["골격"],"explanation":["모형의 이름을 떠올려요.","인체 ○○ 모형이에요.","골격이에요."],"mis":"SC5-1-u4-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#4','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C3',1,'mc','auto','몸속에 무엇이 있을지 상상해 모형에 그릴 때 떠올릴 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X04']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C3","difficulty":1,"kind":"mc","stem":"몸속에 무엇이 있을지 상상해 모형에 그릴 때 떠올릴 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"숨이 드나드는 곳","correct":true},{"t":"몸속은 텅 비어 있다","mis":"SC5-1-u4-X04"},{"t":"몸속에는 물만 가득 차 있다","mis":"SC5-1-u4-X04"},{"t":"몸속에는 똑딱단추가 들어 있다","mis":"SC5-1-u4-X04"}],"explanation":["몸속에서 일어나는 일을 떠올려요.","숨을 쉬어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#5','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C2',2,'match','auto','인체 골격 모형 활동의 준비물과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C2","difficulty":2,"kind":"match","stem":"인체 골격 모형 활동의 준비물과 쓰임을 알맞게 이으세요.","pairs":[{"l":"뼈 도안","r":"몸의 뼈 모양을 본떠 만든 종이이다"},{"l":"똑딱단추","r":"뼈와 뼈를 이어 준다"},{"l":"그림 도구","r":"몸속을 상상해 모형 위에 그린다"}],"mis":"SC5-1-u4-X02","explanation":["하나씩 떠올려요.","본뜨고, 잇고, 그려요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#6','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C2',2,'mc','auto','인체 골격 모형을 만들 때 알맞은 행동은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C2","difficulty":2,"kind":"mc","stem":"인체 골격 모형을 만들 때 알맞은 행동은 어느 것인가요?","options":[{"t":"같은 기호끼리 구멍을 맞대고 연결한다","correct":true},{"t":"기호를 보지 않고 아무 구멍이나 잇는다","mis":"SC5-1-u4-X02"},{"t":"이은 곳을 풀로 단단히 붙인다","mis":"SC5-1-u4-X02"},{"t":"친구의 모형을 함부로 잡아당긴다","mis":"SC5-1-u4-X02"}],"explanation":["도안에 기호가 있어요.","같은 기호끼리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#7','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C1',2,'error','auto','뼈에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C1","difficulty":2,"kind":"error","stem":"뼈에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「뼈는 몸의 겉을 껍데기처럼 감싸고 있어.」","correct":true,"mis_target":"SC5-1-u4-X01"},{"t":"소율 — 「가슴과 등을 만져도 단단한 뼈가 느껴져.」","mis":"SC5-1-u4-X01"},{"t":"태민 — 「뼈가 이어진 곳이 접혔다 펴져.」","mis":"SC5-1-u4-X03"}],"explanation":["뼈는 어디에 있나요?","몸속에 있어요.","하준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#8','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C2',2,'blank','auto','「인체 골격 모형으로 다양한 (    )을 표현합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C2","difficulty":2,"kind":"blank","stem":"「인체 골격 모형으로 다양한 (    )을 표현합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"몸동작","correct":true},{"t":"색깔","mis":"SC5-1-u4-X02"},{"t":"무게","mis":"SC5-1-u4-X02"},{"t":"소리","mis":"SC5-1-u4-X02"}],"explanation":["모형을 움직여 봐요.","자세가 바뀌어요.","몸동작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#9','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C3',2,'ox','auto','인체 골격 모형은 내가 손으로 움직여야만 자세가 바뀌어요.',ARRAY['SC5-1-u4-X03']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C3","difficulty":2,"kind":"ox","stem":"인체 골격 모형은 내가 손으로 움직여야만 자세가 바뀌어요.","answer":"O","reason_options":[{"t":"모형에는 스스로 뼈를 움직이게 하는 것이 없기 때문에","correct":true},{"t":"모형의 뼈가 스스로 구부러졌다 펴지기 때문에","mis":"SC5-1-u4-X03"}],"mis":"SC5-1-u4-X03","explanation":["모형을 가만히 두면 어떤가요?","그대로예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_basic#10','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C1',3,'mc','auto','인체 골격 모형으로 다양한 몸동작을 표현할 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C1","difficulty":3,"kind":"mc","stem":"인체 골격 모형으로 다양한 몸동작을 표현할 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"뼈와 뼈를 이은 곳이 접혔다 펴지기 때문에","correct":true},{"t":"뼈가 커다란 하나로 되어 있기 때문에","mis":"SC5-1-u4-X01"},{"t":"뼈가 스스로 늘어났다 줄어들기 때문에","mis":"SC5-1-u4-X03"},{"t":"뼈가 몸의 겉을 감싸고 있기 때문에","mis":"SC5-1-u4-X01"}],"explanation":["이은 곳을 봐요.","접혔다 펴져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#1','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C2',2,'mc','auto','인체 골격 모형 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C2","difficulty":2,"kind":"mc","stem":"인체 골격 모형 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉠ → ㉤ → ㉣ → ㉢","correct":true},{"t":"㉠ → ㉡ → ㉤ → ㉣ → ㉢","mis":"SC5-1-u4-X02"},{"t":"㉡ → ㉢ → ㉠ → ㉤ → ㉣","mis":"SC5-1-u4-X02"},{"t":"㉢ → ㉡ → ㉠ → ㉣ → ㉤","mis":"SC5-1-u4-X02"}],"explanation":["먼저 만들어요.","표현하고 따라 하고 함께 해요.","상상해 그리기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 인체 골격 모형으로 다양한 몸동작을 표현한다.","㉡ 뼈 도안을 같은 기호끼리 맞대어 똑딱단추로 연결한다.","㉢ 몸속에 있는 여러 가지 기관을 상상해 모형에 그린다.","㉣ 친구와 함께 모형으로 다양한 상황을 표현한다.","㉤ 친구가 표현한 모형의 몸동작을 따라 한다."],"title":"인체 골격 모형 활동(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#2','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C2',2,'sa','auto','인체 골격 모형을 만들 때 필요한 똑딱단추는 모두 몇 개인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C2","difficulty":2,"kind":"sa","stem":"인체 골격 모형을 만들 때 필요한 똑딱단추는 모두 몇 개인지 쓰세요.","answer":["13","13개","열세 개","열세"],"explanation":["준비물을 떠올려요.","열 개보다 많아요.","13개예요."],"mis":"SC5-1-u4-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#3','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C2',3,'mc','auto','뼈 도안을 똑딱단추로 잇는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C2","difficulty":3,"kind":"mc","stem":"뼈 도안을 똑딱단추로 잇는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이은 곳이 접혔다 펴져 다양한 몸동작을 표현할 수 있게 하려고","correct":true},{"t":"모형을 더 무겁게 만들려고","mis":"SC5-1-u4-X02"},{"t":"모형을 예쁘게 꾸미려고","mis":"SC5-1-u4-X02"},{"t":"모형이 움직이지 않게 고정하려고","mis":"SC5-1-u4-X02"}],"explanation":["이은 곳을 접어 봐요.","자세가 바뀌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#4','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C2',3,'error','auto','활동을 하며 친구들이 한 일을 말했어요. 알맞지 않은 행동을 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C2","difficulty":3,"kind":"error","stem":"활동을 하며 친구들이 한 일을 말했어요. 알맞지 않은 행동을 한 친구는 누구인가요?","options":[{"t":"도윤 — 「친구 모형이 궁금해서 함부로 잡아당겨 봤어.」","correct":true,"mis_target":"SC5-1-u4-X02"},{"t":"예린 — 「친구가 만든 몸동작을 내 몸으로 따라 해 봤어.」","mis":"SC5-1-u4-X02"},{"t":"시우 — 「친구와 모형 두 개로 춤추는 장면을 만들었어.」","mis":"SC5-1-u4-X02"}],"explanation":["친구의 모형이에요.","함부로 다루지 않아요.","도윤이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#5','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C3',3,'mc','auto','인체 골격 모형과 내 몸을 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X04','SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C3","difficulty":3,"kind":"mc","stem":"인체 골격 모형과 내 몸을 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 몸은 스스로 움직이지만 모형은 손으로 움직여야 자세가 바뀐다","correct":true},{"t":"모형과 내 몸 모두 몸속이 텅 비어 있다","mis":"SC5-1-u4-X04"},{"t":"내 몸에는 뼈가 없고 모형에만 뼈가 있다","mis":"SC5-1-u4-X01"},{"t":"모형의 뼈는 스스로 구부러졌다 펴진다","mis":"SC5-1-u4-X03"}],"explanation":["무엇이 같고 다른가요?","모형은 손으로 움직여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#6','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C1',3,'mc','auto','인체 골격 모형 활동으로 알게 된 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C1","difficulty":3,"kind":"mc","stem":"인체 골격 모형 활동으로 알게 된 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 개의 뼈가 모여 몸의 골격을 만든다","correct":true},{"t":"몸속의 뼈는 커다란 하나로 되어 있다","mis":"SC5-1-u4-X01"},{"t":"뼈는 팔과 다리에만 있고 가슴과 등에는 없다","mis":"SC5-1-u4-X01"},{"t":"뼈는 스스로 늘어났다 줄어든다","mis":"SC5-1-u4-X03"}],"explanation":["도안이 몇 개였나요?","여러 개를 이었어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#7','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C3',3,'mc','auto','몸속에 있는 여러 가지 기관을 상상해 모형에 그리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X04','SC5-1-u4-X02']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C3","difficulty":3,"kind":"mc","stem":"몸속에 있는 여러 가지 기관을 상상해 모형에 그리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸속에 무엇이 어디쯤 있을지 생각해 보려고","correct":true},{"t":"정답 그림을 그대로 외우려고","mis":"SC5-1-u4-X04"},{"t":"몸속이 비어 있다는 것을 보이려고","mis":"SC5-1-u4-X04"},{"t":"모형을 더 무겁게 만들려고","mis":"SC5-1-u4-X02"}],"explanation":["상상하는 활동이에요.","어디쯤 있을까요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#8','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C3',4,'mc','auto','오늘 활동을 마치고 「다음에 알아보고 싶은 것」으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X03','SC5-1-u4-X04','SC5-1-u4-X01']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C3","difficulty":4,"kind":"mc","stem":"오늘 활동을 마치고 「다음에 알아보고 싶은 것」으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모형과 달리 내 몸은 무엇이 뼈를 움직이게 하는지","correct":true},{"t":"뼈가 스스로 구부러지는 방법","mis":"SC5-1-u4-X03"},{"t":"몸속이 정말 텅 비어 있는지","mis":"SC5-1-u4-X04"},{"t":"뼈를 하나로 붙이는 방법","mis":"SC5-1-u4-X01"}],"explanation":["모형은 손으로 움직였어요.","내 몸은 스스로 움직여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#9','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C1',4,'ox','auto','인체 골격 모형에서 이은 곳을 모두 풀로 붙이면 더 다양한 몸동작을 표현할 수 있어요.',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C1","difficulty":4,"kind":"ox","stem":"인체 골격 모형에서 이은 곳을 모두 풀로 붙이면 더 다양한 몸동작을 표현할 수 있어요.","answer":"X","reason_options":[{"t":"이은 곳이 접혔다 펴질 수 없어 자세를 바꾸기 어렵기 때문에","correct":true},{"t":"단단히 붙일수록 모형이 잘 움직이기 때문에","mis":"SC5-1-u4-X02"}],"mis":"SC5-1-u4-X02","explanation":["이은 곳을 붙이면 어떻게 될까요?","접히지 않아요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L01_challenge#10','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C1',4,'essay','teacher','인체 골격 모형 활동으로 알게 된 점 두 가지와 활동할 때 지켜야 할 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C1","difficulty":4,"kind":"essay","stem":"인체 골격 모형 활동으로 알게 된 점 두 가지와 활동할 때 지켜야 할 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 팔이나 다리를 만져 보면 몸속에 단단한 뼈가 있고, 여러 개의 뼈가 모여 몸의 골격을 만든다. 뼈가 이어진 곳이 접혔다 펴져서 다양한 몸동작을 표현할 수 있다. 활동할 때에는 같은 기호끼리 구멍을 맞대어 연결하고, 친구의 모형을 함부로 잡아당기지 않는다.","scoring_points":["몸속에 단단한 뼈가 있다고 썼는가","여러 뼈가 모여 골격을 만들거나 이은 곳이 접혔다 펴진다고 썼는가","지킬 점을 바르게 썼는가"]},"explanation":["만져 본 것을 떠올려요.","이은 곳을 떠올려요.","지킬 점도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#1','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C6',1,'mc','auto','뼈가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X03','SC5-1-u4-X06']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C6","difficulty":1,"kind":"mc","stem":"뼈가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"몸의 형태를 만들고 몸을 지탱한다","correct":true},{"t":"스스로 줄어들거나 늘어난다","mis":"SC5-1-u4-X03"},{"t":"몸을 따뜻하게 데운다","mis":"SC5-1-u4-X06"},{"t":"몸 밖의 소리를 모은다","mis":"SC5-1-u4-X06"}],"explanation":["몸의 뼈대를 떠올려요.","몸을 받쳐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#2','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C5',1,'sa','auto','「머리를 감싸고 있는 뼈를 □□뼈라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C5","difficulty":1,"kind":"sa","stem":"「머리를 감싸고 있는 뼈를 □□뼈라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["머리","머리뼈"],"explanation":["감싸는 곳이에요.","두 글자예요.","머리뼈예요."],"mis":"SC5-1-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#3','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C7',1,'ox','auto','근육은 뼈에 연결되어 있어요.',ARRAY['SC5-1-u4-X07']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C7","difficulty":1,"kind":"ox","stem":"근육은 뼈에 연결되어 있어요.","answer":"O","reason_options":[{"t":"근육이 줄어들거나 늘어나면서 연결된 뼈를 움직이기 때문에","correct":true},{"t":"근육은 뼈와 떨어져 몸의 겉에만 있기 때문에","mis":"SC5-1-u4-X07"}],"mis":"SC5-1-u4-X07","explanation":["뼈와 근육 모형을 떠올려요.","이어져 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
