INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#6','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C8',2,'mc','auto','팔을 구부릴 때 팔 근육은 어떻게 되나요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C8","difficulty":2,"kind":"mc","stem":"팔을 구부릴 때 팔 근육은 어떻게 되나요?","options":[{"t":"안쪽 근육은 줄어들고 바깥쪽 근육은 늘어난다","correct":true},{"t":"바깥쪽 근육은 줄어들고 안쪽 근육은 늘어난다","mis":"SC5-1-u4-X08"},{"t":"안쪽과 바깥쪽 근육이 모두 늘어난다","mis":"SC5-1-u4-X08"},{"t":"근육은 그대로이고 뼈만 구부러진다","mis":"SC5-1-u4-X03"}],"explanation":["팔을 구부려 만져 봐요.","안쪽이 줄어들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
