INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#8','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C7',2,'error','auto','근육에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X07','SC5-1-u4-X03']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C7","difficulty":2,"kind":"error","stem":"근육에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「근육이 뼈를 밀어서 팔을 펴 줘.」","correct":true,"mis_target":"SC5-1-u4-X07"},{"t":"라온 — 「근육은 뼈에 연결되어 있어.」","mis":"SC5-1-u4-X07"},{"t":"윤호 — 「근육이 줄어들거나 늘어나면서 뼈를 움직여.」","mis":"SC5-1-u4-X03"}],"explanation":["근육은 밀 수 있나요?","줄어들며 당겨요.","지안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#9','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C9',2,'mc','auto','뼈와 근육 모형을 만들 때 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C9","difficulty":2,"kind":"mc","stem":"뼈와 근육 모형을 만들 때 알맞은 것은 어느 것인가요?","options":[{"t":"뼈와 근육 도안을 똑딱단추 6개로 차례대로 연결한다","correct":true},{"t":"똑딱단추 13개로 연결한다","mis":"SC5-1-u4-X02"},{"t":"도안을 풀로 붙여 움직이지 않게 한다","mis":"SC5-1-u4-X02"},{"t":"손잡이를 떼어 내고 만든다","mis":"SC5-1-u4-X02"}],"explanation":["이번 모형은 팔이에요.","여섯 개예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_basic#10','sci',5,1,'u4','L02','g5_1_sci_u4_L02_basic','lesson_basic','SC5-1-u4-C7',3,'mc','auto','우리 몸이 움직이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X07','SC5-1-u4-X03']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C7","difficulty":3,"kind":"mc","stem":"우리 몸이 움직이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"근육이 줄어들거나 늘어나면서 뼈를 움직이기 때문에","correct":true},{"t":"근육이 뼈를 밀어내기 때문에","mis":"SC5-1-u4-X07"},{"t":"뼈가 스스로 구부러졌다 펴지기 때문에","mis":"SC5-1-u4-X03"},{"t":"뼈가 늘어났다 줄어들기 때문에","mis":"SC5-1-u4-X03"}],"explanation":["뼈만으로는 움직이지 않아요.","근육이 뼈를 움직여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#1','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C9',2,'mc','auto','뼈와 근육 모형 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C9","difficulty":2,"kind":"mc","stem":"뼈와 근육 모형 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉢ → ㉠","mis":"SC5-1-u4-X02"},{"t":"㉡ → ㉠ → ㉣ → ㉢","mis":"SC5-1-u4-X02"},{"t":"㉢ → ㉣ → ㉠ → ㉡","mis":"SC5-1-u4-X02"}],"explanation":["내 팔부터 관찰해요.","만들고 나서 손잡이를 움직여요.","이야기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 손잡이를 잡아당겼다 밀면서 모형의 변화를 관찰한다.","㉡ 팔을 구부렸다 펴며 다른 손으로 만져 관찰한다.","㉢ 모형의 변화를 생각하며 팔 근육의 변화를 이야기한다.","㉣ 뼈와 근육 도안을 똑딱단추로 차례대로 연결한다."],"title":"뼈와 근육 모형 활동(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#2','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C9',2,'sa','auto','뼈와 근육 모형을 만들 때 필요한 똑딱단추는 몇 개인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C9","difficulty":2,"kind":"sa","stem":"뼈와 근육 모형을 만들 때 필요한 똑딱단추는 몇 개인지 쓰세요.","answer":["6","6개","여섯 개","여섯"],"explanation":["골격 모형보다 적어요.","팔 하나예요.","6개예요."],"mis":"SC5-1-u4-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
