INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#4','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C8',3,'mc','auto','팔을 펼 때 아래팔뼈는 어떻게 되나요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C8","difficulty":3,"kind":"mc","stem":"팔을 펼 때 아래팔뼈는 어떻게 되나요?","options":[{"t":"바깥쪽 근육이 줄어들면서 따라 내려간다","correct":true},{"t":"안쪽 근육이 줄어들면서 따라 올라간다","mis":"SC5-1-u4-X08"},{"t":"근육과 관계없이 스스로 내려간다","mis":"SC5-1-u4-X03"},{"t":"스스로 길게 늘어난다","mis":"SC5-1-u4-X03"}],"explanation":["팔을 펴 봐요.","아래팔뼈가 내려가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#5','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C7',3,'ox','auto','팔을 펼 때는 바깥쪽 근육이 아래팔뼈를 밀어내요.',ARRAY['SC5-1-u4-X07']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C7","difficulty":3,"kind":"ox","stem":"팔을 펼 때는 바깥쪽 근육이 아래팔뼈를 밀어내요.","answer":"X","reason_options":[{"t":"근육은 밀지 못하고 바깥쪽 근육이 줄어들며 아래팔뼈가 따라 내려가기 때문에","correct":true},{"t":"근육은 늘어날 때 뼈를 밀어내기 때문에","mis":"SC5-1-u4-X07"}],"mis":"SC5-1-u4-X07","explanation":["근육이 하는 일을 떠올려요.","줄어들거나 늘어나요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#6','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C6',3,'mc','auto','갈비뼈가 가슴을 둘러싸고 있어서 보호하는 기관으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X05','SC5-1-u4-X06']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C6","difficulty":3,"kind":"mc","stem":"갈비뼈가 가슴을 둘러싸고 있어서 보호하는 기관으로 알맞은 것은 어느 것인가요?","options":[{"t":"심장과 폐","correct":true},{"t":"뇌","mis":"SC5-1-u4-X05"},{"t":"아래팔뼈","mis":"SC5-1-u4-X05"},{"t":"갈비뼈는 아무것도 보호하지 않는다","mis":"SC5-1-u4-X06"}],"explanation":["가슴 안에 무엇이 있나요?","두근두근, 숨을 쉬어요.","심장과 폐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#7','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C4',3,'mc','auto','기관끼리 묶은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X04']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C4","difficulty":3,"kind":"mc","stem":"기관끼리 묶은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"심장, 폐, 뇌","correct":true},{"t":"똑딱단추, 뼈 도안","mis":"SC5-1-u4-X04"},{"t":"옷, 신발","mis":"SC5-1-u4-X04"},{"t":"손잡이, 근육 도안","mis":"SC5-1-u4-X04"}],"explanation":["몸속에서 일을 하는 부분이에요.","도안이나 물건은 아니에요.","심장, 폐, 뇌예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#8','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C8',4,'mc','auto','컵을 입 쪽으로 가져오려고 팔을 구부릴 때 일어나는 일을 차례대로 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03','SC5-1-u4-X07']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C8","difficulty":4,"kind":"mc","stem":"컵을 입 쪽으로 가져오려고 팔을 구부릴 때 일어나는 일을 차례대로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"안쪽 근육이 줄어든다 → 아래팔뼈가 따라 올라간다 → 팔이 구부러진다","correct":true},{"t":"바깥쪽 근육이 줄어든다 → 아래팔뼈가 따라 올라간다 → 팔이 구부러진다","mis":"SC5-1-u4-X08"},{"t":"아래팔뼈가 스스로 올라간다 → 근육이 따라 줄어든다 → 팔이 구부러진다","mis":"SC5-1-u4-X03"},{"t":"안쪽 근육이 아래팔뼈를 민다 → 아래팔뼈가 올라간다 → 팔이 구부러진다","mis":"SC5-1-u4-X07"}],"explanation":["근육이 먼저 움직여요.","안쪽이 줄어들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#9','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C8',4,'error','auto','뼈와 근육 모형을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X07']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C8","difficulty":4,"kind":"error","stem":"뼈와 근육 모형을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「손잡이를 잡아당기면 바깥쪽 근육 도안이 줄어들어.」","correct":true,"mis_target":"SC5-1-u4-X08"},{"t":"서진 — 「손잡이를 밀면 아래팔뼈 도안이 내려가.」","mis":"SC5-1-u4-X08"},{"t":"은우 — 「근육 도안이 줄어들거나 늘어나며 아래팔뼈 도안이 움직여.」","mis":"SC5-1-u4-X07"}],"explanation":["잡아당길 때를 떠올려요.","안쪽이 줄어들었어요.","하람이 잘못 말했어요."],"asset":{"type":"passage","lines":["손잡이를 잡아당길 때 — 안쪽 근육 도안이 줄어들고 바깥쪽 근육 도안이 늘어났다.","손잡이를 잡아당길 때 — 아래팔뼈 도안이 따라 올라갔다.","손잡이를 밀 때 — ( ? )"],"title":"우리 모둠 뼈와 근육 모형 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#10','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C7',4,'essay','teacher','팔을 구부릴 때와 펼 때 근육과 아래팔뼈가 어떻게 되는지 쓰고, 「근육이 뼈를 밀어서 팔을 편다」는 친구의 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C7","difficulty":4,"kind":"essay","stem":"팔을 구부릴 때와 펼 때 근육과 아래팔뼈가 어떻게 되는지 쓰고, 「근육이 뼈를 밀어서 팔을 편다」는 친구의 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: 팔을 구부릴 때에는 안쪽 근육이 줄어들고 바깥쪽 근육이 늘어나면서 아래팔뼈가 따라 올라간다. 팔을 펼 때에는 바깥쪽 근육이 줄어들고 안쪽 근육이 늘어나면서 아래팔뼈가 따라 내려간다. 근육은 뼈를 밀어내지 않는다. 팔을 펴는 일도 바깥쪽 근육이 줄어들면서 하는 것이다.","scoring_points":["구부릴 때 안쪽 근육이 줄어든다고 썼는가","펼 때 바깥쪽 근육이 줄어든다고 썼는가","근육은 밀지 않고 줄어들며 움직인다고 바로잡았는가"]},"explanation":["구부릴 때부터 써요.","펼 때는 반대예요.","친구에게 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#1','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C10',1,'blank','auto','「음식물 속의 영양소를 흡수할 수 있도록 음식물을 잘게 쪼개는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X09']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C10","difficulty":1,"kind":"blank","stem":"「음식물 속의 영양소를 흡수할 수 있도록 음식물을 잘게 쪼개는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"소화","correct":true},{"t":"흡수","mis":"SC5-1-u4-X09"},{"t":"배출","mis":"SC5-1-u4-X09"},{"t":"골격","mis":"SC5-1-u4-X09"}],"explanation":["잘게 쪼개는 과정이에요.","두 글자예요.","소화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#2','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C12',1,'mc','auto','입에서 삼킨 음식물이 위로 이동하는 통로는 어느 것인가요?',ARRAY['SC5-1-u4-X12']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C12","difficulty":1,"kind":"mc","stem":"입에서 삼킨 음식물이 위로 이동하는 통로는 어느 것인가요?","options":[{"t":"식도","correct":true},{"t":"큰창자","mis":"SC5-1-u4-X12"},{"t":"작은창자","mis":"SC5-1-u4-X12"},{"t":"항문","mis":"SC5-1-u4-X12"}],"explanation":["입과 위 사이예요.","통로예요.","식도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#3','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C13',1,'ox','auto','간, 쓸개, 이자도 소화기관이에요.',ARRAY['SC5-1-u4-X13']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C13","difficulty":1,"kind":"ox","stem":"간, 쓸개, 이자도 소화기관이에요.","answer":"O","reason_options":[{"t":"음식물이 지나가지는 않지만 소화를 도와주기 때문에","correct":true},{"t":"음식물이 간, 쓸개, 이자를 차례로 지나가기 때문에","mis":"SC5-1-u4-X13"}],"mis":"SC5-1-u4-X13","explanation":["소화를 돕는 기관이에요.","지나가지는 않아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#4','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C11',1,'sa','auto','「음식물 찌꺼기는 □□을 통해 몸 밖으로 배출됩니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u4-C11","difficulty":1,"kind":"sa","stem":"「음식물 찌꺼기는 □□을 통해 몸 밖으로 배출됩니다.」 □□에 알맞은 말을 쓰세요.","answer":["항문"],"explanation":["소화 경로의 끝이에요.","두 글자예요.","항문이에요."],"mis":"SC5-1-u4-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#5','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C12',2,'match','auto','소화기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"match","stem":"소화기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"입","r":"이로 잘게 부수고 침과 섞어 물러지게 한다"},{"l":"식도","r":"음식물이 위로 이동하는 통로이다"},{"l":"작은창자","r":"영양소와 대부분의 수분을 흡수한다"},{"l":"큰창자","r":"음식물 찌꺼기에서 수분을 흡수한다"}],"mis":"SC5-1-u4-X12","explanation":["하나씩 떠올려요.","부수고, 지나고, 흡수해요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#6','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C11',2,'mc','auto','음식물이 지나가는 소화기관의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X10']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C11","difficulty":2,"kind":"mc","stem":"음식물이 지나가는 소화기관의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"입 → 식도 → 위 → 작은창자 → 큰창자","correct":true},{"t":"입 → 위 → 식도 → 작은창자 → 큰창자","mis":"SC5-1-u4-X10"},{"t":"입 → 식도 → 위 → 큰창자 → 작은창자","mis":"SC5-1-u4-X10"},{"t":"입 → 식도 → 작은창자 → 위 → 큰창자","mis":"SC5-1-u4-X10"}],"explanation":["입에서 출발해요.","위 다음은 작은창자예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#7','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C12',2,'mc','auto','영양소와 대부분의 수분을 흡수하는 소화기관은 어느 것인가요?',ARRAY['SC5-1-u4-X11','SC5-1-u4-X12']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"mc","stem":"영양소와 대부분의 수분을 흡수하는 소화기관은 어느 것인가요?","options":[{"t":"작은창자","correct":true},{"t":"위","mis":"SC5-1-u4-X11"},{"t":"식도","mis":"SC5-1-u4-X12"},{"t":"입","mis":"SC5-1-u4-X12"}],"explanation":["흡수는 위에서 끝나지 않아요.","더 잘게 쪼개고 흡수해요.","작은창자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#8','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C10',2,'error','auto','소화에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X09']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C10","difficulty":2,"kind":"error","stem":"소화에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「음식물은 소화기관을 지나면서 점점 커져.」","correct":true,"mis_target":"SC5-1-u4-X09"},{"t":"주원 — 「음식물은 소화기관을 지나면서 잘게 쪼개져.」","mis":"SC5-1-u4-X09"},{"t":"가온 — 「우리는 음식물에서 몸에 필요한 영양소를 얻어.」","mis":"SC5-1-u4-X09"}],"explanation":["소화의 뜻을 떠올려요.","잘게 쪼개요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#9','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C14',2,'mc','auto','음식물을 꼭꼭 씹어 먹어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X15','SC5-1-u4-X11']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C14","difficulty":2,"kind":"mc","stem":"음식물을 꼭꼭 씹어 먹어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 잘게 쪼개지고 물러져야 소화가 잘되기 때문에","correct":true},{"t":"음식물을 더 빨리 먹을 수 있기 때문에","mis":"SC5-1-u4-X15"},{"t":"음식물이 커야 영양소가 많아지기 때문에","mis":"SC5-1-u4-X15"},{"t":"씹으면 영양소가 입에서 모두 없어지기 때문에","mis":"SC5-1-u4-X11"}],"explanation":["입이 하는 일을 떠올려요.","잘게 부수고 물러지게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#10','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C13',3,'mc','auto','음식물이 지나가지는 않지만 소화를 돕는 기관끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X13']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C13","difficulty":3,"kind":"mc","stem":"음식물이 지나가지는 않지만 소화를 돕는 기관끼리 묶은 것은 어느 것인가요?","options":[{"t":"간, 쓸개, 이자","correct":true},{"t":"위, 작은창자","mis":"SC5-1-u4-X13"},{"t":"식도, 큰창자","mis":"SC5-1-u4-X13"},{"t":"입, 항문","mis":"SC5-1-u4-X13"}],"explanation":["음식물이 지나가는 곳은 빼요.","세 기관이에요.","간, 쓸개, 이자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#1','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C14',2,'mc','auto','소화 과정 모형을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X16']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C14","difficulty":2,"kind":"mc","stem":"소화 과정 모형을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉢ → ㉠","mis":"SC5-1-u4-X16"},{"t":"㉡ → ㉠ → ㉣ → ㉢","mis":"SC5-1-u4-X16"},{"t":"㉠ → ㉣ → ㉡ → ㉢","mis":"SC5-1-u4-X16"}],"explanation":["도안부터 살펴요.","구멍을 내고 막대를 넣어요.","관찰은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 소화 과정 막대를 도안 안에 넣고 위아래로 움직이게 붙인다.","㉡ 도안의 그림과 이름을 색연필로 연결하고 기능을 조사한다.","㉢ 막대를 천천히 내리며 음식물의 모습을 관찰한다.","㉣ 음식물이 지나가는 자리에 구멍을 내고 도안을 반으로 접는다."],"title":"소화 과정 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#2','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C12',2,'sa','auto','「음식물 찌꺼기에서 수분을 흡수하는 기관은 □□□□입니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"sa","stem":"「음식물 찌꺼기에서 수분을 흡수하는 기관은 □□□□입니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["큰창자"],"explanation":["작은창자 다음이에요.","네 글자예요.","큰창자예요."],"mis":"SC5-1-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#3','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C14',3,'mc','auto','소화기관 도안에 구멍을 내는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X13','SC5-1-u4-X16']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C14","difficulty":3,"kind":"mc","stem":"소화기관 도안에 구멍을 내는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 지나가는 자리","correct":true},{"t":"간, 쓸개, 이자가 있는 자리","mis":"SC5-1-u4-X13"},{"t":"아무 데나 마음에 드는 자리","mis":"SC5-1-u4-X16"},{"t":"구멍을 내지 않고 도안을 그대로 둔다","mis":"SC5-1-u4-X16"}],"explanation":["구멍으로 무엇을 보나요?","음식물의 모습이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#4','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C12',3,'mc','auto','막대를 내리며 본 것의 ㉰는 어느 소화기관에서 일어난 일인가요?',ARRAY['SC5-1-u4-X10','SC5-1-u4-X11']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C12","difficulty":3,"kind":"mc","stem":"막대를 내리며 본 것의 ㉰는 어느 소화기관에서 일어난 일인가요?","options":[{"t":"위","correct":true},{"t":"식도","mis":"SC5-1-u4-X10"},{"t":"작은창자","mis":"SC5-1-u4-X11"},{"t":"큰창자","mis":"SC5-1-u4-X10"}],"explanation":["식도 다음이에요.","소화를 돕는 액체를 분비해요.","위예요."],"asset":{"type":"passage","lines":["㉮ 큰 덩어리가 이로 부서지고 침과 섞여 물러졌다.","㉯ 물러진 덩어리가 아래로 내려가는 통로를 지났다.","㉰ 소화를 돕는 액체와 섞여 잘게 쪼개졌다.","㉱ 더 잘게 쪼개지고 영양소와 대부분의 수분이 흡수되었다.","㉲ 남은 찌꺼기에서 수분이 흡수되었다."],"title":"소화 과정 막대를 내리며 본 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#5','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C12',3,'ox','auto','음식물의 영양소와 수분은 위에서 모두 흡수돼요.',ARRAY['SC5-1-u4-X11']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C12","difficulty":3,"kind":"ox","stem":"음식물의 영양소와 수분은 위에서 모두 흡수돼요.","answer":"X","reason_options":[{"t":"영양소와 대부분의 수분은 작은창자에서, 찌꺼기의 수분은 큰창자에서 흡수되기 때문에","correct":true},{"t":"위가 모든 영양소와 수분을 흡수하기 때문에","mis":"SC5-1-u4-X11"}],"mis":"SC5-1-u4-X11","explanation":["흡수하는 곳을 떠올려요.","창자에서 흡수해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#6','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C11',3,'mc','auto','음식물 찌꺼기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X14','SC5-1-u4-X10']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C11","difficulty":3,"kind":"mc","stem":"음식물 찌꺼기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰창자를 지나 항문을 통해 몸 밖으로 배출된다","correct":true},{"t":"몸 밖으로 나가지 못하고 몸속에 그대로 쌓인다","mis":"SC5-1-u4-X14"},{"t":"모두 흡수되어 남는 것이 하나도 없다","mis":"SC5-1-u4-X14"},{"t":"식도를 거쳐 입으로 다시 나온다","mis":"SC5-1-u4-X10"}],"explanation":["소화 경로의 끝이에요.","항문으로 나가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#7','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C14',3,'mc','auto','소화 과정 모형을 관찰하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X16']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C14","difficulty":3,"kind":"mc","stem":"소화 과정 모형을 관찰하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"막대를 천천히 내리며 구멍으로 보이는 음식물의 모습을 관찰한다","correct":true},{"t":"막대를 풀로 붙여 움직이지 않게 한다","mis":"SC5-1-u4-X16"},{"t":"막대를 한 번에 빠르게 끝까지 내린다","mis":"SC5-1-u4-X16"},{"t":"도안을 펴서 막대 없이 그림만 본다","mis":"SC5-1-u4-X16"}],"explanation":["막대가 움직여야 해요.","천천히 내려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#8','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C10',4,'mc','auto','점심에 먹은 밥이 큰창자에 이르렀을 때의 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X09','SC5-1-u4-X11','SC5-1-u4-X14']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C10","difficulty":4,"kind":"mc","stem":"점심에 먹은 밥이 큰창자에 이르렀을 때의 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잘게 쪼개져 영양소와 대부분의 수분이 흡수되고 남은 찌꺼기","correct":true},{"t":"입에 넣었을 때와 같은 큰 덩어리","mis":"SC5-1-u4-X09"},{"t":"아직 영양소가 하나도 흡수되지 않은 상태","mis":"SC5-1-u4-X11"},{"t":"모두 흡수되어 아무것도 남지 않은 상태","mis":"SC5-1-u4-X14"}],"explanation":["작은창자를 지나왔어요.","흡수하고 남은 것이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#9','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C13',4,'error','auto','소화 과정 모형을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X13','SC5-1-u4-X12','SC5-1-u4-X11']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C13","difficulty":4,"kind":"error","stem":"소화 과정 모형을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「간 자리에도 구멍을 내자. 음식물이 간을 지나가니까.」","correct":true,"mis_target":"SC5-1-u4-X13"},{"t":"나래 — 「식도는 음식물이 위로 가는 통로야.」","mis":"SC5-1-u4-X12"},{"t":"지후 — 「작은창자에서 영양소를 흡수해.」","mis":"SC5-1-u4-X11"}],"explanation":["간은 무슨 일을 하나요?","지나가지 않고 도와요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#10','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C11',4,'essay','teacher','음식물이 지나가는 소화기관을 차례대로 쓰고, 영양소와 수분이 흡수되는 곳과 음식물 찌꺼기가 나가는 곳을 쓰세요. 그리고 꼭꼭 씹어 먹어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C11","difficulty":4,"kind":"essay","stem":"음식물이 지나가는 소화기관을 차례대로 쓰고, 영양소와 수분이 흡수되는 곳과 음식물 찌꺼기가 나가는 곳을 쓰세요. 그리고 꼭꼭 씹어 먹어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 음식물은 입 → 식도 → 위 → 작은창자 → 큰창자를 거치며 소화된다. 영양소와 대부분의 수분은 작은창자에서, 찌꺼기에 남은 수분은 큰창자에서 흡수되고, 나머지 찌꺼기는 항문을 통해 몸 밖으로 배출된다. 음식물을 꼭꼭 씹으면 잘게 쪼개지고 물러져 소화가 잘된다.","scoring_points":["소화기관의 차례를 바르게 썼는가","흡수하는 곳과 배출되는 곳을 썼는가","꼭꼭 씹는 까닭을 썼는가"]},"explanation":["입에서 출발해요.","흡수하는 곳을 나눠요.","씹는 까닭도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#1','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C15',1,'blank','auto','「혈액이 끊임없이 온몸을 이동하는 것을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C15","difficulty":1,"kind":"blank","stem":"「혈액이 끊임없이 온몸을 이동하는 것을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"혈액 순환","correct":true},{"t":"소화","mis":"SC5-1-u4-X22"},{"t":"흡수","mis":"SC5-1-u4-X22"},{"t":"골격","mis":"SC5-1-u4-X22"}],"explanation":["혈액이 온몸을 돌아요.","돌고 도는 것이에요.","혈액 순환이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#2','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C16',1,'mc','auto','심장은 우리 몸의 어디에 있나요?',ARRAY['SC5-1-u4-X20']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C16","difficulty":1,"kind":"mc","stem":"심장은 우리 몸의 어디에 있나요?","options":[{"t":"가슴 중앙에서 왼쪽으로 약간 치우친 곳","correct":true},{"t":"배 아래쪽 한가운데","mis":"SC5-1-u4-X20"},{"t":"머리 안쪽","mis":"SC5-1-u4-X20"},{"t":"양쪽 손목 안","mis":"SC5-1-u4-X20"}],"explanation":["가슴에 손을 대 봐요.","두근두근 뛰어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#3','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C17',1,'ox','auto','혈관은 온몸에 퍼져 있어요.',ARRAY['SC5-1-u4-X18']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C17","difficulty":1,"kind":"ox","stem":"혈관은 온몸에 퍼져 있어요.","answer":"O","reason_options":[{"t":"혈액이 머리끝부터 발끝까지 이동하는 통로이기 때문에","correct":true},{"t":"혈관은 심장 가까이에만 있기 때문에","mis":"SC5-1-u4-X18"}],"mis":"SC5-1-u4-X18","explanation":["혈액이 어디까지 가나요?","온몸이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#4','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C16',1,'sa','auto','「심장은 끊임없이 □□ 작용을 하여 혈액을 온몸으로 보냅니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u4-C16","difficulty":1,"kind":"sa","stem":"「심장은 끊임없이 □□ 작용을 하여 혈액을 온몸으로 보냅니다.」 □□에 알맞은 말을 쓰세요.","answer":["펌프"],"explanation":["모형실험 도구를 떠올려요.","쥐었다 폈다 해요.","펌프예요."],"mis":"SC5-1-u4-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#5','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C19',2,'match','auto','순환기관 모형의 재료와 같은 역할을 하는 우리 몸의 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C19","difficulty":2,"kind":"match","stem":"순환기관 모형의 재료와 같은 역할을 하는 우리 몸의 부분을 알맞게 이으세요.","pairs":[{"l":"펌프","r":"심장"},{"l":"호스","r":"혈관"},{"l":"붉은 색소 물","r":"혈액"}],"mis":"SC5-1-u4-X21","explanation":["하는 일을 견줘요.","보내고, 지나가고, 이동해요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#6','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C18',2,'mc','auto','혈액이 온몸에 운반하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C18","difficulty":2,"kind":"mc","stem":"혈액이 온몸에 운반하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"영양소와 산소","correct":true},{"t":"씹지 않은 음식물 덩어리","mis":"SC5-1-u4-X22"},{"t":"뼈와 근육","mis":"SC5-1-u4-X22"},{"t":"아무것도 나르지 않는다","mis":"SC5-1-u4-X22"}],"explanation":["혈액이 하는 일이에요.","두 가지를 날라요.","영양소와 산소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#7','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C15',2,'mc','auto','순환기관끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C15","difficulty":2,"kind":"mc","stem":"순환기관끼리 묶은 것은 어느 것인가요?","options":[{"t":"심장과 혈관","correct":true},{"t":"위와 작은창자","mis":"SC5-1-u4-X22"},{"t":"머리뼈와 갈비뼈","mis":"SC5-1-u4-X22"},{"t":"식도와 큰창자","mis":"SC5-1-u4-X22"}],"explanation":["혈액을 돌게 하는 기관이에요.","보내는 곳과 통로예요.","심장과 혈관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#8','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C16',2,'error','auto','순환기관에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X18']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C16","difficulty":2,"kind":"error","stem":"순환기관에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「심장은 혈액을 새로 만들어 내는 곳이야.」","correct":true,"mis_target":"SC5-1-u4-X17"},{"t":"보람 — 「심장은 펌프 작용을 해.」","mis":"SC5-1-u4-X17"},{"t":"다은 — 「혈관은 혈액이 이동하는 통로야.」","mis":"SC5-1-u4-X18"}],"explanation":["심장이 하는 일을 떠올려요.","혈액을 보내요.","수호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#9','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C18',2,'mc','auto','심장에서 나간 혈액은 어떻게 되나요?',ARRAY['SC5-1-u4-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C18","difficulty":2,"kind":"mc","stem":"심장에서 나간 혈액은 어떻게 되나요?","options":[{"t":"온몸을 돌고 다시 심장으로 돌아온다","correct":true},{"t":"온몸을 한 번 돌고 멈춘다","mis":"SC5-1-u4-X19"},{"t":"나가기만 하고 돌아오지 않는다","mis":"SC5-1-u4-X19"},{"t":"혈관을 지나 몸 밖으로 나간다","mis":"SC5-1-u4-X19"}],"explanation":["순환의 뜻을 떠올려요.","돌아와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#10','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C19',3,'mc','auto','심장박동이 멈추었을 때 빠른 시간 안에 심폐 소생술을 해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X23']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"심장박동이 멈추었을 때 빠른 시간 안에 심폐 소생술을 해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 순환하지 못해 영양소와 산소를 온몸에 운반할 수 없기 때문에","correct":true},{"t":"혈액이 몸 밖으로 모두 흘러나오기 때문에","mis":"SC5-1-u4-X23"},{"t":"혈관의 길이가 짧아지기 때문에","mis":"SC5-1-u4-X23"},{"t":"뼈가 곧바로 굳어 버리기 때문에","mis":"SC5-1-u4-X23"}],"explanation":["심장이 멈추면 혈액은요?","돌지 못해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#1','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',2,'mc','auto','순환기관 모형실험의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X21']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C19","difficulty":2,"kind":"mc","stem":"순환기관 모형실험의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉠ → ㉡ → ㉢","mis":"SC5-1-u4-X21"},{"t":"㉡ → ㉠ → ㉣ → ㉢","mis":"SC5-1-u4-X21"},{"t":"㉢ → ㉡ → ㉣ → ㉠","mis":"SC5-1-u4-X21"}],"explanation":["모형부터 살펴요.","호스를 넣고 펌프를 움직여요.","이야기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 펌프를 손으로 쥐었다 폈다 하며 붉은 색소 물의 이동을 관찰한다.","㉡ 순환기관 모형을 관찰해 그림과 이름을 연결하고 기능을 조사한다.","㉢ 모형의 세 가지가 우리 몸의 어떤 부분과 같은지 이야기한다.","㉣ 식용 색소를 녹인 물에 한쪽 호스를 넣고 펌프를 잡는다."],"title":"순환기관 모형실험(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#2','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C16',2,'sa','auto','「펌프 작용으로 혈액을 온몸으로 보내는 순환기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C16","difficulty":2,"kind":"sa","stem":"「펌프 작용으로 혈액을 온몸으로 보내는 순환기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["심장"],"explanation":["가슴에 있어요.","두근두근 뛰어요.","심장이에요."],"mis":"SC5-1-u4-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#3','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',3,'mc','auto','모형실험에서 펌프를 쥐었다 폈다 하다가 멈추면 붉은 색소 물은 어떻게 될까요?',ARRAY['SC5-1-u4-X21','SC5-1-u4-X17']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"모형실험에서 펌프를 쥐었다 폈다 하다가 멈추면 붉은 색소 물은 어떻게 될까요?","options":[{"t":"이동을 멈춘다","correct":true},{"t":"전보다 더 빠르게 이동한다","mis":"SC5-1-u4-X21"},{"t":"펌프와 관계없이 계속 이동한다","mis":"SC5-1-u4-X21"},{"t":"호스 안에서 새로 만들어진다","mis":"SC5-1-u4-X17"}],"explanation":["펌프가 보내 주어요.","멈추면 보내지 못해요.","이동을 멈춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#4','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C18',3,'ox','auto','혈액은 온몸을 한 번 돌고 나면 멈춰요.',ARRAY['SC5-1-u4-X19']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C18","difficulty":3,"kind":"ox","stem":"혈액은 온몸을 한 번 돌고 나면 멈춰요.","answer":"X","reason_options":[{"t":"다시 심장으로 돌아와 순환 과정을 끊임없이 반복하기 때문에","correct":true},{"t":"한 번 운반하고 나면 할 일이 끝나기 때문에","mis":"SC5-1-u4-X19"}],"mis":"SC5-1-u4-X19","explanation":["순환은 끝이 있나요?","반복해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#5','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C18',3,'mc','auto','작은창자에서 흡수한 영양소가 발끝까지 가는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X17']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C18","difficulty":3,"kind":"mc","stem":"작은창자에서 흡수한 영양소가 발끝까지 가는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 혈관을 따라 발끝까지 운반한다","correct":true},{"t":"음식물이 발끝까지 내려간다","mis":"SC5-1-u4-X22"},{"t":"영양소가 다리뼈를 타고 이동한다","mis":"SC5-1-u4-X22"},{"t":"심장이 발끝에서 영양소를 새로 만든다","mis":"SC5-1-u4-X17"}],"explanation":["운반하는 것을 떠올려요.","혈액이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#6','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',3,'error','auto','모형실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X21']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"error","stem":"모형실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「호스는 우리 몸의 심장과 같은 역할을 해.」","correct":true,"mis_target":"SC5-1-u4-X21"},{"t":"정민 — 「붉은 색소 물은 우리 몸의 혈액과 같아.」","mis":"SC5-1-u4-X21"},{"t":"로운 — 「펌프를 쥐었다 펴면 붉은 색소 물이 이동해.」","mis":"SC5-1-u4-X21"}],"explanation":["호스는 무엇이 지나가나요?","통로예요.","하은이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#7','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',3,'mc','auto','순환기관 모형실험에서 지켜야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X21']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"순환기관 모형실험에서 지켜야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"붉은 색소 물이 눈에 튀지 않게 조심하고 맛보지 않는다","correct":true},{"t":"붉은 색소 물을 맛보아 무엇인지 확인한다","mis":"SC5-1-u4-X21"},{"t":"펌프를 친구 얼굴 쪽으로 향해 누른다","mis":"SC5-1-u4-X21"},{"t":"남은 물을 아무 데나 쏟아 버린다","mis":"SC5-1-u4-X21"}],"explanation":["실험 약속이에요.","눈과 입을 조심해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#8','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C17',4,'mc','auto','손끝을 살짝 다쳤더니 피가 났어요. 이것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X18','SC5-1-u4-X17','SC5-1-u4-X19']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C17","difficulty":4,"kind":"mc","stem":"손끝을 살짝 다쳤더니 피가 났어요. 이것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손끝에도 혈관이 퍼져 있어 혈액이 이동한다","correct":true},{"t":"혈관은 심장 가까이에만 있다","mis":"SC5-1-u4-X18"},{"t":"손끝에서 혈액이 새로 만들어진다","mis":"SC5-1-u4-X17"},{"t":"손끝의 혈액은 심장으로 돌아가지 않는다","mis":"SC5-1-u4-X19"}],"explanation":["피는 혈액이에요.","손끝까지 왔어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#9','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C16',4,'mc','auto','심장이 쉬지 않고 펌프 작용을 해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X18','SC5-1-u4-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C16","difficulty":4,"kind":"mc","stem":"심장이 쉬지 않고 펌프 작용을 해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 계속 온몸을 돌며 영양소와 산소를 운반해야 하기 때문에","correct":true},{"t":"혈액을 계속 새로 만들어야 하기 때문에","mis":"SC5-1-u4-X17"},{"t":"혈관을 심장 가까이로 모아야 하기 때문에","mis":"SC5-1-u4-X18"},{"t":"혈액을 몸 밖으로 내보내야 하기 때문에","mis":"SC5-1-u4-X19"}],"explanation":["혈액이 하는 일을 떠올려요.","계속 운반해야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#10','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C18',4,'essay','teacher','순환기관 모형의 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 혈액이 온몸을 돌며 하는 일을 쓰세요. 그리고 「심장이 혈액을 만든다」는 친구의 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C18","difficulty":4,"kind":"essay","stem":"순환기관 모형의 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 혈액이 온몸을 돌며 하는 일을 쓰세요. 그리고 「심장이 혈액을 만든다」는 친구의 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: 펌프는 심장, 호스는 혈관, 붉은 색소 물은 혈액과 같은 역할을 한다. 심장에서 나온 혈액은 혈관을 따라 이동하며 영양소와 산소를 온몸에 운반하고 다시 심장으로 돌아오는 순환을 반복한다. 심장은 혈액을 만드는 곳이 아니라 펌프 작용으로 혈액을 온몸으로 보내는 곳이다.","scoring_points":["세 가지를 몸의 부분과 바르게 짝지었는가","영양소와 산소를 운반하고 돌아온다고 썼는가","심장은 펌프 작용을 한다고 바로잡았는가"]},"explanation":["모형부터 짝지어요.","혈액이 하는 일을 써요.","친구에게 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#1','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',1,'mc','auto','숨을 들이마시고 내쉬는 활동을 무엇이라고 하나요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X22']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"mc","stem":"숨을 들이마시고 내쉬는 활동을 무엇이라고 하나요?","options":[{"t":"호흡","correct":true},{"t":"소화","mis":"SC5-1-u4-X24"},{"t":"순환","mis":"SC5-1-u4-X22"},{"t":"흡수","mis":"SC5-1-u4-X24"}],"explanation":["숨을 쉬는 일이에요.","두 글자예요.","호흡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#2','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C21',1,'sa','auto','「숨을 들이마시면 폐는 우리 몸에 필요한 □□를 받아들입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C21","difficulty":1,"kind":"sa","stem":"「숨을 들이마시면 폐는 우리 몸에 필요한 □□를 받아들입니다.」 □□에 알맞은 말을 쓰세요.","answer":["산소"],"explanation":["혈액이 나르는 것 가운데 하나예요.","두 글자예요.","산소예요."],"mis":"SC5-1-u4-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#3','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',1,'ox','auto','숨관가지는 숨관과 폐를 연결해요.',ARRAY['SC5-1-u4-X24']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"ox","stem":"숨관가지는 숨관과 폐를 연결해요.","answer":"O","reason_options":[{"t":"공기가 숨관에서 폐로 이동하는 통로이기 때문에","correct":true},{"t":"숨관가지는 공기가 처음 드나드는 곳이기 때문에","mis":"SC5-1-u4-X24"}],"mis":"SC5-1-u4-X24","explanation":["이름을 살펴봐요.","숨관에서 갈라진 가지예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#4','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',1,'blank','auto','「(    )은/는 공기가 드나드는 곳입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X26']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"blank","stem":"「(    )은/는 공기가 드나드는 곳입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"코","correct":true},{"t":"폐","mis":"SC5-1-u4-X24"},{"t":"식도","mis":"SC5-1-u4-X26"},{"t":"심장","mis":"SC5-1-u4-X24"}],"explanation":["얼굴에 있어요.","공기가 들어가고 나와요.","코예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#5','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',2,'match','auto','호흡기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C20","difficulty":2,"kind":"match","stem":"호흡기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"코","r":"공기가 드나드는 곳이다"},{"l":"숨관","r":"공기가 이동하는 통로이다"},{"l":"숨관가지","r":"숨관과 폐를 연결하는 통로이다"},{"l":"폐","r":"산소를 받아들이고 이산화 탄소를 내보낸다"}],"mis":"SC5-1-u4-X24","explanation":["공기의 길을 따라가요.","드나들고, 지나고, 받아들여요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#6','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C21',2,'mc','auto','숨을 들이마실 때 공기가 이동하는 길로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X25','SC5-1-u4-X26']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C21","difficulty":2,"kind":"mc","stem":"숨을 들이마실 때 공기가 이동하는 길로 알맞은 것은 어느 것인가요?","options":[{"t":"코 → 숨관 → 숨관가지 → 폐","correct":true},{"t":"코 → 숨관가지 → 숨관 → 폐","mis":"SC5-1-u4-X24"},{"t":"폐 → 숨관가지 → 숨관 → 코","mis":"SC5-1-u4-X25"},{"t":"코 → 식도 → 위","mis":"SC5-1-u4-X26"}],"explanation":["코에서 출발해요.","숨관이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#7','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C22',2,'mc','auto','숨을 내쉴 때 몸 밖으로 나가는 공기로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X28','SC5-1-u4-X27']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C22","difficulty":2,"kind":"mc","stem":"숨을 내쉴 때 몸 밖으로 나가는 공기로 알맞은 것은 어느 것인가요?","options":[{"t":"이산화 탄소를 포함한 공기","correct":true},{"t":"산소만 들어 있는 공기","mis":"SC5-1-u4-X28"},{"t":"이산화 탄소가 하나도 없는 공기","mis":"SC5-1-u4-X28"},{"t":"영양소가 가득한 공기","mis":"SC5-1-u4-X27"}],"explanation":["몸속에서 생긴 것이에요.","내보내는 기체예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#8','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C26',2,'error','auto','공기와 음식물이 가는 길에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X26']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"error","stem":"공기와 음식물이 가는 길에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「먹은 음식물도 숨관을 지나 폐로 들어가.」","correct":true,"mis_target":"SC5-1-u4-X26"},{"t":"준혁 — 「들이마신 공기는 숨관을 지나 폐로 가.」","mis":"SC5-1-u4-X26"},{"t":"채원 — 「삼킨 음식물은 식도를 지나 위로 가.」","mis":"SC5-1-u4-X26"}],"explanation":["공기의 길과 음식물의 길이에요.","서로 달라요.","세아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#9','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C23',2,'mc','auto','호흡기관 모형을 만들 때 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C23","difficulty":2,"kind":"mc","stem":"호흡기관 모형을 만들 때 알맞은 것은 어느 것인가요?","options":[{"t":"주름 빨대와 종이봉투 사이를 셀로판테이프로 잘 막는다","correct":true},{"t":"종이봉투가 크게 부풀도록 숨이 찰 때까지 분다","mis":"SC5-1-u4-X29"},{"t":"어지러워도 끝까지 공기를 불어 넣는다","mis":"SC5-1-u4-X29"},{"t":"공기가 새도 그대로 실험한다","mis":"SC5-1-u4-X29"}],"explanation":["공기가 새면 어떨까요?","잘 막아야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#10','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C21',3,'mc','auto','수영할 때 얼굴을 물 위로 내미는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X27']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"mc","stem":"수영할 때 얼굴을 물 위로 내미는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"코로 공기를 들이마셔 폐가 산소를 받아들여야 하기 때문에","correct":true},{"t":"물속을 더 잘 보기 위해서","mis":"SC5-1-u4-X27"},{"t":"물에서 더 빨리 나아가기 위해서","mis":"SC5-1-u4-X27"},{"t":"몸이 차가워지지 않게 하기 위해서","mis":"SC5-1-u4-X27"}],"explanation":["물속에서는 숨을 못 쉬어요.","공기가 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#1','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C23',2,'mc','auto','호흡기관 모형 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C23","difficulty":2,"kind":"mc","stem":"호흡기관 모형 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉢ → ㉠","mis":"SC5-1-u4-X29"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SC5-1-u4-X29"},{"t":"㉢ → ㉣ → ㉠ → ㉡","mis":"SC5-1-u4-X29"}],"explanation":["내 몸부터 느껴요.","감고, 붙이고, 불어요.","관찰은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 호흡기관 붙임딱지를 각 기관의 위치에 맞게 붙인다.","㉡ 가슴에 양손을 얹고 천천히 호흡하며 몸의 변화를 느낀다.","㉢ 모형에 공기를 불어 넣으며 변화를 관찰한다.","㉣ 주름 빨대와 종이봉투를 셀로판테이프로 공기가 새지 않게 감는다."],"title":"호흡기관 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#2','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',2,'sa','auto','「숨을 내쉬면 공기가 폐 → 숨관가지 → □□ → 코를 거쳐 몸 밖으로 나갑니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C22","difficulty":2,"kind":"sa","stem":"「숨을 내쉬면 공기가 폐 → 숨관가지 → □□ → 코를 거쳐 몸 밖으로 나갑니다.」 □□에 알맞은 말을 쓰세요.","answer":["숨관"],"explanation":["들이마실 때를 거꾸로 해요.","코 바로 안쪽 통로예요.","숨관이에요."],"mis":"SC5-1-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#3','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',3,'mc','auto','숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X25','SC5-1-u4-X26']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C22","difficulty":3,"kind":"mc","stem":"숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 바르게 말한 것은 어느 것인가요?","options":[{"t":"같은 길을 서로 반대 방향으로 지난다","correct":true},{"t":"들이마실 때와 내쉴 때 서로 다른 길로 지난다","mis":"SC5-1-u4-X25"},{"t":"내쉴 때에도 코에서 폐 쪽으로 들어간다","mis":"SC5-1-u4-X25"},{"t":"내쉴 때에는 식도를 지나 나간다","mis":"SC5-1-u4-X26"}],"explanation":["정리 공책을 떠올려요.","거꾸로 되짚어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#4','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C21',3,'ox','auto','폐가 받아들인 산소는 몸에서 아무 일에도 쓰이지 않아요.',ARRAY['SC5-1-u4-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"ox","stem":"폐가 받아들인 산소는 몸에서 아무 일에도 쓰이지 않아요.","answer":"X","reason_options":[{"t":"산소는 몸을 움직이거나 몸속 기관이 일하는 데 쓰이기 때문에","correct":true},{"t":"산소는 들어왔다가 그대로 다시 나가기만 하기 때문에","mis":"SC5-1-u4-X27"}],"mis":"SC5-1-u4-X27","explanation":["산소가 하는 일을 떠올려요.","몸이 써요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#5','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C21',3,'mc','auto','혈액이 온몸에 나르는 산소는 어디에서 오나요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X27','SC5-1-u4-X26']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"mc","stem":"혈액이 온몸에 나르는 산소는 어디에서 오나요?","options":[{"t":"숨을 들이마실 때 폐가 받아들인 산소","correct":true},{"t":"심장이 새로 만든 산소","mis":"SC5-1-u4-X17"},{"t":"작은창자가 음식물에서 흡수한 산소","mis":"SC5-1-u4-X27"},{"t":"식도로 삼켜서 들어온 산소","mis":"SC5-1-u4-X26"}],"explanation":["지난 시간과 이어요.","폐가 받아들여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#6','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C23',3,'error','auto','호흡기관 모형 실험을 하며 친구들이 한 일을 말했어요. 알맞지 않은 행동을 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C23","difficulty":3,"kind":"error","stem":"호흡기관 모형 실험을 하며 친구들이 한 일을 말했어요. 알맞지 않은 행동을 한 친구는 누구인가요?","options":[{"t":"은재 — 「종이봉투를 크게 부풀리려고 숨이 차도 계속 불었어.」","correct":true,"mis_target":"SC5-1-u4-X29"},{"t":"하율 — 「붙임딱지를 각 기관의 위치에 맞게 붙였어.」","mis":"SC5-1-u4-X29"},{"t":"민규 — 「어지러워서 잠깐 활동을 멈췄어.」","mis":"SC5-1-u4-X29"}],"explanation":["안전 약속을 떠올려요.","무리하지 않아요.","은재가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#7','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C20',3,'mc','auto','폐가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X27','SC5-1-u4-X24']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C20","difficulty":3,"kind":"mc","stem":"폐가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"산소를 받아들이고 이산화 탄소를 몸 밖으로 내보낸다","correct":true},{"t":"음식물 속의 영양소를 흡수한다","mis":"SC5-1-u4-X27"},{"t":"펌프 작용으로 혈액을 온몸으로 보낸다","mis":"SC5-1-u4-X24"},{"t":"공기가 처음 드나드는 곳이다","mis":"SC5-1-u4-X24"}],"explanation":["공기의 길 끝이에요.","기체를 주고받아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#8','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',4,'mc','auto','친구의 정리 공책에서 잘못 쓴 것은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X27','SC5-1-u4-X28']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"mc","stem":"친구의 정리 공책에서 잘못 쓴 것은 어느 것인가요?","options":[{"t":"③","correct":true},{"t":"①","mis":"SC5-1-u4-X24"},{"t":"②","mis":"SC5-1-u4-X27"},{"t":"④","mis":"SC5-1-u4-X28"}],"explanation":["들이마실 때와 내쉴 때를 견줘요.","내쉴 때는 반대예요.","③이 잘못되었어요."],"asset":{"type":"passage","lines":["① 들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","② 폐는 우리 몸에 필요한 산소를 받아들인다.","③ 내쉴 때 — 코 → 숨관 → 숨관가지 → 폐","④ 내쉬는 공기에는 이산화 탄소가 들어 있다."],"title":"친구의 호흡 정리 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#9','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C21',4,'mc','auto','숨을 들이마셔 들어온 산소가 다리 근육까지 가는 과정으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X26','SC5-1-u4-X24','SC5-1-u4-X27']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C21","difficulty":4,"kind":"mc","stem":"숨을 들이마셔 들어온 산소가 다리 근육까지 가는 과정으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"폐가 받아들인 산소를 혈액이 혈관을 따라 다리까지 운반한다","correct":true},{"t":"산소가 숨관을 따라 다리까지 내려간다","mis":"SC5-1-u4-X26"},{"t":"다리 근육이 직접 공기를 들이마신다","mis":"SC5-1-u4-X24"},{"t":"산소는 폐에만 머물고 다리로 가지 않는다","mis":"SC5-1-u4-X27"}],"explanation":["폐와 혈액을 이어요.","혈액이 운반해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#10','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',4,'essay','teacher','숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 각각 쓰고, 폐가 하는 일을 쓰세요. 그리고 친구의 정리 공책에서 잘못된 줄을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"essay","stem":"숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 각각 쓰고, 폐가 하는 일을 쓰세요. 그리고 친구의 정리 공책에서 잘못된 줄을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 숨을 들이마시면 공기가 코 → 숨관 → 숨관가지 → 폐로 들어가고, 내쉬면 폐 → 숨관가지 → 숨관 → 코를 거쳐 몸 밖으로 나간다. 폐는 우리 몸에 필요한 산소를 받아들이고, 몸속에서 생긴 이산화 탄소를 몸 밖으로 내보낸다. ③은 「내쉴 때 — 폐 → 숨관가지 → 숨관 → 코」로 고쳐야 한다.","scoring_points":["들이마실 때의 길을 바르게 썼는가","내쉴 때 길이 반대라고 썼는가","폐가 하는 일과 ③ 고치기를 바르게 썼는가"]},"explanation":["들이마실 때부터 써요.","내쉴 때는 거꾸로예요.","③을 고쳐요."],"asset":{"type":"passage","lines":["① 들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","② 폐는 우리 몸에 필요한 산소를 받아들인다.","③ 내쉴 때 — 코 → 숨관 → 숨관가지 → 폐","④ 내쉬는 공기에는 이산화 탄소가 들어 있다."],"title":"친구의 호흡 정리 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#1','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C24',1,'blank','auto','「혈액 속의 노폐물을 걸러 내어 몸 밖으로 내보내는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X31']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"blank","stem":"「혈액 속의 노폐물을 걸러 내어 몸 밖으로 내보내는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"배설","correct":true},{"t":"배출","mis":"SC5-1-u4-X30"},{"t":"소화","mis":"SC5-1-u4-X31"},{"t":"순환","mis":"SC5-1-u4-X31"}],"explanation":["노폐물을 내보내요.","배출과 헷갈리지 않아요.","배설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#2','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',1,'mc','auto','혈액 속의 노폐물을 걸러 내어 오줌을 만드는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C25","difficulty":1,"kind":"mc","stem":"혈액 속의 노폐물을 걸러 내어 오줌을 만드는 기관은 어느 것인가요?","options":[{"t":"콩팥","correct":true},{"t":"방광","mis":"SC5-1-u4-X32"},{"t":"오줌관","mis":"SC5-1-u4-X32"},{"t":"폐","mis":"SC5-1-u4-X32"}],"explanation":["강낭콩처럼 생겼어요.","걸러 내요.","콩팥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#3','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',1,'sa','auto','「오줌을 모아 두었다가 몸 밖으로 내보내는 기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C25","difficulty":1,"kind":"sa","stem":"「오줌을 모아 두었다가 몸 밖으로 내보내는 기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["방광"],"explanation":["오줌관 다음이에요.","두 글자예요.","방광이에요."],"mis":"SC5-1-u4-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#4','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C24',1,'ox','auto','노폐물은 몸에서 영양소가 쓰이면서 만들어져요.',ARRAY['SC5-1-u4-X31']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"ox","stem":"노폐물은 몸에서 영양소가 쓰이면서 만들어져요.","answer":"O","reason_options":[{"t":"영양소가 쓰이면 몸에 필요 없는 것이 생기기 때문에","correct":true},{"t":"노폐물은 먹은 음식물에서만 곧바로 생기기 때문에","mis":"SC5-1-u4-X31"}],"mis":"SC5-1-u4-X31","explanation":["노폐물이 생기는 때를 떠올려요.","영양소가 쓰일 때예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#5','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',2,'match','auto','배설기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"match","stem":"배설기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"콩팥","r":"혈액 속의 노폐물을 걸러 내어 오줌을 만든다"},{"l":"오줌관","r":"오줌이 이동하는 통로이다"},{"l":"방광","r":"오줌을 모아 두었다가 몸 밖으로 내보낸다"}],"mis":"SC5-1-u4-X32","explanation":["오줌을 따라가요.","만들고, 지나고, 모아요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#6','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C26',2,'mc','auto','다음 가운데 배설에 해당하는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"mc","stem":"다음 가운데 배설에 해당하는 것은 어느 것인가요?","options":[{"t":"콩팥이 걸러 만든 오줌이 몸 밖으로 나가는 것","correct":true},{"t":"큰창자를 지난 음식물 찌꺼기가 항문으로 나가는 것","mis":"SC5-1-u4-X30"},{"t":"똥을 누는 것","mis":"SC5-1-u4-X30"},{"t":"소화되고 남은 것을 내보내는 것","mis":"SC5-1-u4-X30"}],"explanation":["배설은 혈액 속 노폐물이에요.","오줌이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#7','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',2,'mc','auto','오줌이 몸 밖으로 나가는 길로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X34']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"mc","stem":"오줌이 몸 밖으로 나가는 길로 알맞은 것은 어느 것인가요?","options":[{"t":"콩팥 → 오줌관 → 방광 → 몸 밖","correct":true},{"t":"방광 → 오줌관 → 콩팥 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"콩팥 → 방광 → 오줌관 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"오줌관 → 콩팥 → 방광 → 몸 밖","mis":"SC5-1-u4-X34"}],"explanation":["만드는 곳부터예요.","통로를 지나 모여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#8','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C26',2,'error','auto','배설에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X32','SC5-1-u4-X34']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"error","stem":"배설에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「똥을 누는 것이 배설이야.」","correct":true,"mis_target":"SC5-1-u4-X30"},{"t":"도준 — 「콩팥은 혈액 속의 노폐물을 걸러 내.」","mis":"SC5-1-u4-X32"},{"t":"서윤 — 「오줌은 방광에 모였다가 나가.」","mis":"SC5-1-u4-X34"}],"explanation":["배설과 배출을 견줘요.","똥은 배출이에요.","하린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#9','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C27',2,'mc','auto','잠을 잘 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C27","difficulty":2,"kind":"mc","stem":"잠을 잘 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"활동할 때보다 천천히 호흡한다","correct":true},{"t":"호흡이 완전히 멈춘다","mis":"SC5-1-u4-X35"},{"t":"모든 기관이 하던 일을 멈추고 쉰다","mis":"SC5-1-u4-X35"},{"t":"호흡 말고는 아무 기관도 일하지 않는다","mis":"SC5-1-u4-X35"}],"explanation":["자는 동안에도 숨을 쉬어요.","천천히요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#10','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',3,'mc','auto','콩팥에서 노폐물이 걸러진 혈액은 어떻게 되나요?',ARRAY['SC5-1-u4-X33']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"mc","stem":"콩팥에서 노폐물이 걸러진 혈액은 어떻게 되나요?","options":[{"t":"다시 혈관을 통해 온몸을 순환한다","correct":true},{"t":"오줌과 함께 몸 밖으로 나간다","mis":"SC5-1-u4-X33"},{"t":"콩팥에 쌓여 더 이상 움직이지 않는다","mis":"SC5-1-u4-X33"},{"t":"방광에 모였다가 몸 밖으로 나간다","mis":"SC5-1-u4-X33"}],"explanation":["두 갈래를 떠올려요.","혈액은 돌아가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#1','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C27',2,'mc','auto','생각 그물 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C27","difficulty":2,"kind":"mc","stem":"생각 그물 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉠ → ㉣","correct":true},{"t":"㉢ → ㉡ → ㉣ → ㉠","mis":"SC5-1-u4-X35"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SC5-1-u4-X35"},{"t":"㉠ → ㉢ → ㉡ → ㉣","mis":"SC5-1-u4-X35"}],"explanation":["먼저 조사해요.","그물로 만들고 발표해요.","경로 이야기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 완성한 생각 그물을 발표한다.","㉡ 배설기관 모형을 관찰해 그림과 이름을 연결하고 기능을 조사한다.","㉢ 배설기관의 이름과 하는 일을 생각 그물로 표현한다.","㉣ 노폐물이 몸 밖으로 나가는 경로를 이야기한다."],"title":"생각 그물 활동(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#2','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',2,'sa','auto','「오줌이 콩팥에서 방광으로 이동하는 통로는 □□□입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"sa","stem":"「오줌이 콩팥에서 방광으로 이동하는 통로는 □□□입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["오줌관"],"explanation":["콩팥과 방광 사이예요.","세 글자예요.","오줌관이에요."],"mis":"SC5-1-u4-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#3','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C26',3,'mc','auto','몸 밖으로 내보내는 일 네 가지 가운데 배설에 해당하는 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C26","difficulty":3,"kind":"mc","stem":"몸 밖으로 내보내는 일 네 가지 가운데 배설에 해당하는 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉡, ㉣","mis":"SC5-1-u4-X30"},{"t":"㉠, ㉡","mis":"SC5-1-u4-X30"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"SC5-1-u4-X30"}],"explanation":["혈액 속 노폐물을 찾아요.","콩팥과 방광이에요.","㉠, ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 콩팥이 혈액 속의 노폐물을 걸러 낸다.","㉡ 큰창자를 지난 음식물 찌꺼기가 항문으로 나간다.","㉢ 오줌이 방광에 모였다가 몸 밖으로 나간다.","㉣ 소화되고 남은 것이 몸 밖으로 나간다."],"title":"몸 밖으로 내보내는 일 네 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#4','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',3,'mc','auto','콩팥이 노폐물을 제대로 걸러 내지 못하면 어떤 일이 일어날까요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"mc","stem":"콩팥이 노폐물을 제대로 걸러 내지 못하면 어떤 일이 일어날까요?","options":[{"t":"노폐물이 몸속에 쌓여 건강에 문제가 생긴다","correct":true},{"t":"먹은 음식물이 소화되지 않는다","mis":"SC5-1-u4-X32"},{"t":"뼈가 더 이상 자라지 않는다","mis":"SC5-1-u4-X32"},{"t":"숨을 쉬지 못하게 된다","mis":"SC5-1-u4-X32"}],"explanation":["콩팥이 하는 일을 떠올려요.","걸러 내지 못하면 남아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#5','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C27',3,'ox','auto','한 가지 일을 할 때에는 그 일과 관련된 기관 하나만 일해요.',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C27","difficulty":3,"kind":"ox","stem":"한 가지 일을 할 때에는 그 일과 관련된 기관 하나만 일해요.","answer":"X","reason_options":[{"t":"식사할 때도 뼈와 근육, 소화기관 등 여러 기관이 함께 일하기 때문에","correct":true},{"t":"기관은 한 번에 하나씩만 일하기 때문에","mis":"SC5-1-u4-X35"}],"mis":"SC5-1-u4-X35","explanation":["식사할 때를 떠올려요.","여러 기관이 일해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#6','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C27',3,'mc','auto','여러 상황 기록의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C27","difficulty":3,"kind":"mc","stem":"여러 상황 기록의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"화장실에 가는 동안에도 소화기관은 먹은 음식물을 소화한다","correct":true},{"t":"화장실에 가는 동안에는 모든 기관이 쉰다","mis":"SC5-1-u4-X35"},{"t":"화장실에 가는 동안에는 호흡이 멈춘다","mis":"SC5-1-u4-X35"},{"t":"배설기관 하나만 일하고 나머지는 멈춘다","mis":"SC5-1-u4-X35"}],"explanation":["여러 기관이 함께 일해요.","소화기관도 일해요.","첫 번째예요."],"asset":{"type":"passage","lines":["식사할 때 — 팔뼈와 팔 근육으로 음식을 입에 넣고, 얼굴 근육으로 씹는다.","잠을 잘 때 — 활동할 때보다 천천히 호흡한다.","화장실에 갈 때 — ( ? )"],"title":"지능형 과학실 ON으로 본 여러 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#7','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',3,'error','auto','배설기관 생각 그물을 보고 친구들이 말했어요. 잘못 붙인 친구는 누구인가요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"error","stem":"배설기관 생각 그물을 보고 친구들이 말했어요. 잘못 붙인 친구는 누구인가요?","options":[{"t":"예준 — 「방광 가지에 ‘노폐물을 걸러 내어 오줌을 만든다’를 붙였어.」","correct":true,"mis_target":"SC5-1-u4-X32"},{"t":"소이 — 「콩팥 가지에 ‘노폐물을 걸러 내어 오줌을 만든다’를 붙였어.」","mis":"SC5-1-u4-X32"},{"t":"윤재 — 「오줌관 가지에 ‘오줌이 이동하는 통로’를 붙였어.」","mis":"SC5-1-u4-X32"}],"explanation":["방광이 하는 일을 떠올려요.","모아 두었다가 내보내요.","예준이 잘못 붙였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#8','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C24',4,'mc','auto','몸 곳곳에서 생긴 노폐물이 콩팥까지 오는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X34','SC5-1-u4-X31']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C24","difficulty":4,"kind":"mc","stem":"몸 곳곳에서 생긴 노폐물이 콩팥까지 오는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 노폐물을 실어 혈관을 따라 콩팥으로 운반한다","correct":true},{"t":"작은창자의 음식물이 콩팥으로 바로 내려간다","mis":"SC5-1-u4-X30"},{"t":"방광에서 오줌관을 거꾸로 거슬러 온다","mis":"SC5-1-u4-X34"},{"t":"노폐물은 콩팥에서만 생기므로 올 필요가 없다","mis":"SC5-1-u4-X31"}],"explanation":["지난 시간 순환과 이어요.","혈액이 운반해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#9','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C26',4,'mc','auto','배설기관과 소화기관이 몸 밖으로 내보내는 것을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C26","difficulty":4,"kind":"mc","stem":"배설기관과 소화기관이 몸 밖으로 내보내는 것을 바르게 견준 것은 어느 것인가요?","options":[{"t":"배설기관은 혈액 속 노폐물로 만든 오줌을, 소화기관은 음식물 찌꺼기를 내보낸다","correct":true},{"t":"둘 다 음식물 찌꺼기를 내보낸다","mis":"SC5-1-u4-X30"},{"t":"배설기관은 음식물 찌꺼기를, 소화기관은 오줌을 내보낸다","mis":"SC5-1-u4-X30"},{"t":"둘이 내보내는 것은 똑같다","mis":"SC5-1-u4-X30"}],"explanation":["배설과 배출을 견줘요.","내보내는 것이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#10','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',4,'essay','teacher','콩팥에서 오줌이 만들어져 몸 밖으로 나가는 길을 쓰고, 노폐물이 걸러진 혈액이 어떻게 되는지 쓰세요. 그리고 배설과 배출이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C25","difficulty":4,"kind":"essay","stem":"콩팥에서 오줌이 만들어져 몸 밖으로 나가는 길을 쓰고, 노폐물이 걸러진 혈액이 어떻게 되는지 쓰세요. 그리고 배설과 배출이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 콩팥은 혈액 속의 노폐물을 걸러 내어 오줌을 만들고, 오줌은 오줌관을 지나 방광에 모였다가 몸 밖으로 나간다. 노폐물이 걸러진 혈액은 다시 혈관을 통해 온몸을 순환한다. 배설은 혈액 속 노폐물을 걸러 내보내는 것이고, 배출은 소화되고 남은 음식물 찌꺼기가 항문으로 나가는 것이다.","scoring_points":["콩팥 → 오줌관 → 방광의 길을 썼는가","걸러진 혈액이 다시 순환한다고 썼는가","배설과 배출을 바르게 구별했는가"]},"explanation":["콩팥부터 따라가요.","혈액 갈래도 써요.","배설과 배출을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#1','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C28',1,'mc','auto','맥박이란 무엇인가요?',ARRAY['SC5-1-u4-X36']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C28","difficulty":1,"kind":"mc","stem":"맥박이란 무엇인가요?","options":[{"t":"심장의 박동이 목이나 팔목 등에서 느껴지는 것","correct":true},{"t":"몸의 따뜻한 정도","mis":"SC5-1-u4-X36"},{"t":"숨을 들이마시고 내쉬는 활동","mis":"SC5-1-u4-X36"},{"t":"몸에서 땀이 나는 정도","mis":"SC5-1-u4-X36"}],"explanation":["팔목을 짚어 봐요.","콩닥콩닥 느껴져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#2','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C29',1,'ox','auto','운동 직후의 체온은 운동 전보다 높아져요.',ARRAY['SC5-1-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"ox","stem":"운동 직후의 체온은 운동 전보다 높아져요.","answer":"O","reason_options":[{"t":"운동을 하면 체온이 올라가고 땀이 나기도 하기 때문에","correct":true},{"t":"운동을 하면 몸이 식어 체온이 내려가기 때문에","mis":"SC5-1-u4-X37"}],"mis":"SC5-1-u4-X37","explanation":["운동 뒤 몸을 떠올려요.","따뜻해지고 땀이 나요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#3','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C28',1,'sa','auto','「몸의 따뜻한 정도를 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C28","difficulty":1,"kind":"sa","stem":"「몸의 따뜻한 정도를 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["체온"],"explanation":["체온계로 재요.","두 글자예요.","체온이에요."],"mis":"SC5-1-u4-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#4','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C29',1,'mc','auto','운동을 하면 호흡과 심장은 어떻게 되나요?',ARRAY['SC5-1-u4-X37']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"mc","stem":"운동을 하면 호흡과 심장은 어떻게 되나요?","options":[{"t":"호흡이 빨라지고 심장이 빠르게 뛴다","correct":true},{"t":"호흡이 느려지고 심장이 느리게 뛴다","mis":"SC5-1-u4-X37"},{"t":"호흡이 빨라지고 심장이 느리게 뛴다","mis":"SC5-1-u4-X37"},{"t":"호흡과 심장 모두 그대로이다","mis":"SC5-1-u4-X37"}],"explanation":["달리기한 뒤를 떠올려요.","숨이 차고 두근거려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#5','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C31',2,'match','auto','몸을 움직일 때 기관이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C31","difficulty":2,"kind":"match","stem":"몸을 움직일 때 기관이 하는 일을 알맞게 이으세요.","pairs":[{"l":"소화기관","r":"음식물을 소화해 영양소를 흡수한다"},{"l":"호흡기관","r":"산소를 받아들이고 이산화 탄소를 내보낸다"},{"l":"순환기관","r":"산소와 영양소를 온몸에 운반한다"},{"l":"배설기관","r":"혈액 속의 노폐물을 걸러 내보낸다"}],"mis":"SC5-1-u4-X40","explanation":["네 기관을 떠올려요.","흡수, 받아들임, 운반, 거르기예요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#6','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C30',2,'mc','auto','운동할 때 호흡이 빨라지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X28','SC5-1-u4-X27']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C30","difficulty":2,"kind":"mc","stem":"운동할 때 호흡이 빨라지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산소를 많이 흡수하기 위해서","correct":true},{"t":"단지 몸이 힘들기 때문에","mis":"SC5-1-u4-X39"},{"t":"이산화 탄소를 더 많이 받아들이기 위해서","mis":"SC5-1-u4-X28"},{"t":"폐에서 영양소를 흡수하기 위해서","mis":"SC5-1-u4-X27"}],"explanation":["근육에 필요한 것을 떠올려요.","산소가 많이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#7','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C28',2,'blank','auto','「운동한 후 측정하고, (    ) 정도 휴식한 후 체온과 맥박 수를 한 번 더 측정합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C28","difficulty":2,"kind":"blank","stem":"「운동한 후 측정하고, (    ) 정도 휴식한 후 체온과 맥박 수를 한 번 더 측정합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"5분","correct":true},{"t":"1초","mis":"SC5-1-u4-X41"},{"t":"하루","mis":"SC5-1-u4-X41"},{"t":"일주일","mis":"SC5-1-u4-X41"}],"explanation":["잠깐 쉬어요.","몇 분이에요.","5분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#8','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C31',2,'error','auto','운동할 때 우리 몸에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X40','SC5-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C31","difficulty":2,"kind":"error","stem":"운동할 때 우리 몸에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「우리 몸의 기관은 저마다 따로따로 일해.」","correct":true,"mis_target":"SC5-1-u4-X40"},{"t":"아린 — 「각 기관은 서로 영향을 주고받아.」","mis":"SC5-1-u4-X40"},{"t":"건우 — 「운동하면 체온이 올라가고 땀이 나기도 해.」","mis":"SC5-1-u4-X37"}],"explanation":["기관끼리 관계가 있나요?","서로 영향을 주고받아요.","지호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#9','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C29',2,'mc','auto','측정 기록에서 맥박 수가 가장 많은 때는 언제인가요?',ARRAY['SC5-1-u4-X37','SC5-1-u4-X38']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C29","difficulty":2,"kind":"mc","stem":"측정 기록에서 맥박 수가 가장 많은 때는 언제인가요?","options":[{"t":"운동 직후","correct":true},{"t":"운동 전","mis":"SC5-1-u4-X37"},{"t":"5분 휴식 후","mis":"SC5-1-u4-X38"},{"t":"세 번 모두 같다","mis":"SC5-1-u4-X37"}],"explanation":["가장 큰 수를 찾아요.","108회예요.","운동 직후예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#10','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C30',3,'mc','auto','운동할 때 순환기관이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X32','SC5-1-u4-X40']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C30","difficulty":3,"kind":"mc","stem":"운동할 때 순환기관이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"산소와 영양소를 온몸에 운반하고, 이산화 탄소는 호흡기관으로, 노폐물은 배설기관으로 운반한다","correct":true},{"t":"음식물을 잘게 쪼개 영양소를 흡수한다","mis":"SC5-1-u4-X22"},{"t":"혈액 속의 노폐물을 걸러 오줌을 만든다","mis":"SC5-1-u4-X32"},{"t":"운동하는 동안에는 하던 일을 멈춘다","mis":"SC5-1-u4-X40"}],"explanation":["순환기관은 운반해요.","세 곳으로 날라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#1','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C28',2,'mc','auto','체온과 맥박 수를 측정하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C28","difficulty":2,"kind":"mc","stem":"체온과 맥박 수를 측정하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉤ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉤ → ㉢ → ㉠","mis":"SC5-1-u4-X41"},{"t":"㉡ → ㉤ → ㉣ → ㉠ → ㉢","mis":"SC5-1-u4-X41"},{"t":"㉤ → ㉠ → ㉡ → ㉣ → ㉢","mis":"SC5-1-u4-X41"}],"explanation":["준비 운동이 먼저예요.","운동 전에 재고 운동해요.","그래프는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 운동한 후 측정하고, 5분 정도 휴식한 후 한 번 더 측정한다.","㉡ 간단한 준비 운동을 한다.","㉢ 측정한 결과를 그래프로 나타내고 이야기한다.","㉣ 운동하기 전에 체온과 맥박 수를 측정한다.","㉤ 제자리 뛰기 같은 가벼운 운동을 한다."],"title":"체온과 맥박 수 측정(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#2','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C29',2,'sa','auto','측정 기록에서 운동 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C29","difficulty":2,"kind":"sa","stem":"측정 기록에서 운동 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.","answer":["108","108회"],"explanation":["운동 직후 줄을 읽어요.","백 회가 넘어요.","108회예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"},"mis":"SC5-1-u4-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#3','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C30',3,'mc','auto','운동할 때 심장이 빠르게 뛰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X17','SC5-1-u4-X37']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C30","difficulty":3,"kind":"mc","stem":"운동할 때 심장이 빠르게 뛰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산소와 영양소를 온몸에 빠르게 운반하기 위해서","correct":true},{"t":"단지 몸이 힘들기 때문에","mis":"SC5-1-u4-X39"},{"t":"혈액을 더 많이 만들어 내기 위해서","mis":"SC5-1-u4-X17"},{"t":"체온을 내리기 위해서","mis":"SC5-1-u4-X37"}],"explanation":["근육에 필요한 것을 떠올려요.","빨리 날라야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#4','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C31',3,'ox','auto','운동하는 동안 소화기관과 배설기관은 하던 일을 멈춰요.',ARRAY['SC5-1-u4-X40']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C31","difficulty":3,"kind":"ox","stem":"운동하는 동안 소화기관과 배설기관은 하던 일을 멈춰요.","answer":"X","reason_options":[{"t":"운동하는 동안에도 영양소를 흡수하고 노폐물을 걸러 내는 일을 계속하기 때문에","correct":true},{"t":"운동할 때는 뼈와 근육만 일하기 때문에","mis":"SC5-1-u4-X40"}],"mis":"SC5-1-u4-X40","explanation":["쉬고 있는 기관이 있었나요?","모두 일해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#5','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C29',3,'mc','auto','측정 기록의 5분 휴식 후 값으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X38']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C29","difficulty":3,"kind":"mc","stem":"측정 기록의 5분 휴식 후 값으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"휴식을 하면 체온과 맥박 수가 차츰 운동 전으로 돌아간다","correct":true},{"t":"휴식을 해도 운동 직후 값이 그대로 이어진다","mis":"SC5-1-u4-X38"},{"t":"휴식을 하면 맥박 수가 계속 많아진다","mis":"SC5-1-u4-X38"},{"t":"휴식을 하면 운동 전보다 훨씬 적어진다","mis":"SC5-1-u4-X38"}],"explanation":["세 값을 견줘요.","108에서 84로 줄었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#6','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C28',3,'error','auto','체온과 맥박 수를 측정하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C28","difficulty":3,"kind":"error","stem":"체온과 맥박 수를 측정하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"태윤 — 「운동 직후에 재는 걸 깜빡해서 5분 쉬고 나서 처음 쟀어.」","correct":true,"mis_target":"SC5-1-u4-X41"},{"t":"나연 — 「체온은 체온계로, 맥박 수는 애플리케이션으로 쟀어.」","mis":"SC5-1-u4-X41"},{"t":"준서 — 「운동하기 전에 준비 운동을 했어.」","mis":"SC5-1-u4-X41"}],"explanation":["세 번 재야 해요.","운동 직후에 바로 재요.","태윤이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#7','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C28',3,'mc','auto','측정한 결과를 기록하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C28","difficulty":3,"kind":"mc","stem":"측정한 결과를 기록하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"예상과 달라도 잰 값을 정확하게 기록한다","correct":true},{"t":"친구가 잰 값을 그대로 베낀다","mis":"SC5-1-u4-X41"},{"t":"예상에 맞도록 값을 고쳐 적는다","mis":"SC5-1-u4-X41"},{"t":"적지 않고 기억해 둔다","mis":"SC5-1-u4-X41"}],"explanation":["기록은 사실대로예요.","정확하게 적어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#8','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C30',4,'mc','auto','운동할 때 콧구멍을 넓혀 주는 밴드를 붙이면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X40','SC5-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"mc","stem":"운동할 때 콧구멍을 넓혀 주는 밴드를 붙이면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"코로 공기가 더 잘 드나들어 산소를 많이 받아들일 수 있다","correct":true},{"t":"심장이 덜 힘들어져 뛰지 않아도 된다","mis":"SC5-1-u4-X39"},{"t":"먹은 음식물이 더 빨리 소화된다","mis":"SC5-1-u4-X40"},{"t":"체온이 오르지 않게 막아 준다","mis":"SC5-1-u4-X37"}],"explanation":["코는 공기가 드나드는 곳이에요.","산소가 많이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#9','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C31',4,'mc','auto','운동할 때 우리 몸에서 일어나는 일을 차례대로 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X37','SC5-1-u4-X40']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"mc","stem":"운동할 때 우리 몸에서 일어나는 일을 차례대로 바르게 이은 것은 어느 것인가요?","options":[{"t":"근육이 산소와 영양소를 많이 쓴다 → 호흡이 빨라지고 심장이 빠르게 뛴다 → 산소와 영양소가 빠르게 운반된다","correct":true},{"t":"몸이 힘들다 → 심장이 그냥 빨라진다 → 아무것도 운반되지 않는다","mis":"SC5-1-u4-X39"},{"t":"호흡이 느려진다 → 심장이 느리게 뛴다 → 체온이 내려간다","mis":"SC5-1-u4-X37"},{"t":"근육만 일한다 → 다른 기관은 멈춘다 → 몸이 움직인다","mis":"SC5-1-u4-X40"}],"explanation":["근육에서 시작해요.","필요한 것을 빨리 날라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#10','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C30',4,'essay','teacher','측정 기록을 보고 운동 직후와 5분 휴식 후 체온과 맥박 수가 어떻게 변했는지 쓰고, 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 까닭을 여러 기관과 관련지어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"essay","stem":"측정 기록을 보고 운동 직후와 5분 휴식 후 체온과 맥박 수가 어떻게 변했는지 쓰고, 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 까닭을 여러 기관과 관련지어 쓰세요.","answer_guide":{"answer":"예: 운동 직후에는 체온이 36.9 °C, 맥박 수가 108회로 운동 전보다 높아졌고, 5분 휴식 후에는 36.7 °C, 84회로 차츰 운동 전으로 돌아갔다. 운동할 때 뼈와 근육이 움직이려면 산소와 영양소가 필요하다. 그래서 산소를 많이 흡수하려고 호흡이 빨라지고, 산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빠르게 뛴다. 이처럼 각 기관은 서로 영향을 주고받으며 작용한다.","scoring_points":["운동 직후에 높아지고 휴식 후 돌아간다고 썼는가","산소와 영양소가 필요하다는 까닭을 썼는가","호흡기관·순환기관을 관련지어 썼는가"]},"explanation":["표를 읽어요.","근육에 필요한 것을 떠올려요.","기관끼리 이어요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#1','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C32',1,'mc','auto','감기, 장염 등 다양한 질병은 무엇과 관련이 있나요?',ARRAY['SC5-1-u4-X42']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C32","difficulty":1,"kind":"mc","stem":"감기, 장염 등 다양한 질병은 무엇과 관련이 있나요?","options":[{"t":"우리 몸의 기관","correct":true},{"t":"그날그날의 운","mis":"SC5-1-u4-X42"},{"t":"태어난 달","mis":"SC5-1-u4-X42"},{"t":"입은 옷의 색깔","mis":"SC5-1-u4-X42"}],"explanation":["몸이 아픈 곳을 떠올려요.","기관이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#2','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',1,'sa','auto','「변비를 예방하려면 □□를 많이 먹고, 물을 충분히 마시며, 운동을 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C33","difficulty":1,"kind":"sa","stem":"「변비를 예방하려면 □□를 많이 먹고, 물을 충분히 마시며, 운동을 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["채소"],"explanation":["반찬을 떠올려요.","두 글자예요.","채소예요."],"mis":"SC5-1-u4-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#3','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',1,'ox','auto','손을 잘 씻으면 감기를 예방하는 데 도움이 돼요.',ARRAY['SC5-1-u4-X42']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C33","difficulty":1,"kind":"ox","stem":"손을 잘 씻으면 감기를 예방하는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"감기의 예방법으로 손 씻기가 있기 때문에","correct":true},{"t":"감기는 운이 나빠서 걸리므로 손 씻기와 관계없기 때문에","mis":"SC5-1-u4-X42"}],"mis":"SC5-1-u4-X42","explanation":["2모둠 자료를 떠올려요.","손 씻기예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#4','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C34',1,'blank','auto','「질병을 조사할 때는 질병의 종류와 (    ), 예방법을 함께 살펴봅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C34","difficulty":1,"kind":"blank","stem":"「질병을 조사할 때는 질병의 종류와 (    ), 예방법을 함께 살펴봅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"증상","correct":true},{"t":"가격","mis":"SC5-1-u4-X45"},{"t":"이름의 글자 수","mis":"SC5-1-u4-X45"},{"t":"유행한 해","mis":"SC5-1-u4-X45"}],"explanation":["아플 때 나타나는 것이에요.","기침, 콧물 같은 것이에요.","증상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#5','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',2,'match','auto','증상과 예방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"match","stem":"증상과 예방법을 알맞게 이으세요.","pairs":[{"l":"변비의 증상","r":"똥이 잘 나오지 않고 배가 아프다"},{"l":"변비의 예방법","r":"채소 많이 먹기, 물 충분히 마시기, 운동하기"},{"l":"감기의 증상","r":"기침, 콧물, 코 막힘"},{"l":"감기의 예방법","r":"손 씻기"}],"mis":"SC5-1-u4-X44","explanation":["모둠별 자료를 떠올려요.","증상과 예방법을 나눠요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#6','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C32',2,'mc','auto','감기와 관련 있는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C32","difficulty":2,"kind":"mc","stem":"감기와 관련 있는 기관은 어느 것인가요?","options":[{"t":"호흡기관","correct":true},{"t":"소화기관","mis":"SC5-1-u4-X44"},{"t":"배설기관","mis":"SC5-1-u4-X44"},{"t":"어느 기관과도 관련이 없다","mis":"SC5-1-u4-X42"}],"explanation":["기침과 콧물을 떠올려요.","코와 숨관이에요.","호흡기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#7','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C34',2,'mc','auto','질병을 조사할 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"mc","stem":"질병을 조사할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"검색 자료가 너무 많으면 검색어가 포함된 자료를 활용한다","correct":true},{"t":"가장 위에 있는 자료 하나만 그대로 옮겨 적는다","mis":"SC5-1-u4-X45"},{"t":"조사한 자료는 우리 모둠만 보고 나누지 않는다","mis":"SC5-1-u4-X45"},{"t":"스마트 기기가 뜨거워져도 다 만들 때까지 쓴다","mis":"SC5-1-u4-X45"}],"explanation":["자료가 많을 때예요.","검색어로 골라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#8','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',2,'error','auto','질병 예방에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X43','SC5-1-u4-X42','SC5-1-u4-X44']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"error","stem":"질병 예방에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「질병 예방은 어른이 해 주는 거라 우리는 할 게 없어.」","correct":true,"mis_target":"SC5-1-u4-X43"},{"t":"태하 — 「손 씻기는 감기 예방에 도움이 돼.」","mis":"SC5-1-u4-X42"},{"t":"미소 — 「채소를 많이 먹으면 변비 예방에 도움이 돼.」","mis":"SC5-1-u4-X44"}],"explanation":["어린이도 할 수 있나요?","날마다 할 수 있어요.","유진이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#9','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C32',2,'mc','auto','변비와 관련 있는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C32","difficulty":2,"kind":"mc","stem":"변비와 관련 있는 기관은 어느 것인가요?","options":[{"t":"소화기관","correct":true},{"t":"호흡기관","mis":"SC5-1-u4-X44"},{"t":"순환기관","mis":"SC5-1-u4-X44"},{"t":"어느 기관과도 관련이 없다","mis":"SC5-1-u4-X42"}],"explanation":["똥이 잘 나오지 않아요.","큰창자와 항문이에요.","소화기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#10','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',3,'mc','auto','감기와 변비의 예방법을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X43','SC5-1-u4-X42']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C33","difficulty":3,"kind":"mc","stem":"감기와 변비의 예방법을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"평소의 생활 습관으로 질병을 예방하는 데 도움을 줄 수 있다","correct":true},{"t":"질병은 약으로만 막을 수 있다","mis":"SC5-1-u4-X43"},{"t":"질병 예방은 어른만 할 수 있다","mis":"SC5-1-u4-X43"},{"t":"질병은 운에 달려 있어 어떻게 할 수 없다","mis":"SC5-1-u4-X42"}],"explanation":["손 씻기, 채소 먹기예요.","날마다 하는 일이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#1','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',2,'mc','auto','질병 조사와 공유 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"mc","stem":"질병 조사와 공유 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉣ → ㉠ → ㉤","correct":true},{"t":"㉢ → ㉡ → ㉣ → ㉤ → ㉠","mis":"SC5-1-u4-X45"},{"t":"㉡ → ㉣ → ㉢ → ㉠ → ㉤","mis":"SC5-1-u4-X45"},{"t":"㉠ → ㉡ → ㉢ → ㉣ → ㉤","mis":"SC5-1-u4-X45"}],"explanation":["기관부터 골라요.","조사하고 만들어요.","올린 뒤 댓글을 달아요."],"asset":{"type":"passage","lines":["㉠ 만든 자료나 책을 공유 플랫폼에 올린다.","㉡ 소화, 순환, 호흡, 배설기관 가운데 한 가지를 고른다.","㉢ 고른 기관과 관련 있는 질병의 종류와 증상, 예방법을 조사한다.","㉣ 발표 자료나 책을 계획하고 만든다.","㉤ 다른 모둠 자료를 보고 알게 된 점을 댓글로 단다."],"title":"질병 조사와 공유(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#2','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',2,'sa','auto','「질병의 종류와 증상, 예방법은 국가건강정보□□에서 찾을 수 있습니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"sa","stem":"「질병의 종류와 증상, 예방법은 국가건강정보□□에서 찾을 수 있습니다.」 □□에 알맞은 말을 쓰세요.","answer":["포털"],"explanation":["누리집 이름이에요.","두 글자예요.","포털이에요."],"mis":"SC5-1-u4-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#3','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C33',3,'mc','auto','2모둠 자료를 보고 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C33","difficulty":3,"kind":"mc","stem":"2모둠 자료를 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"감기는 호흡기관과 관련이 있고, 손 씻기로 예방하는 데 도움을 줄 수 있다","correct":true},{"t":"감기는 소화기관과 관련이 있다","mis":"SC5-1-u4-X44"},{"t":"감기는 예방할 수 있는 방법이 없다","mis":"SC5-1-u4-X42"},{"t":"감기의 증상은 똥이 잘 나오지 않는 것이다","mis":"SC5-1-u4-X44"}],"explanation":["2모둠 줄을 읽어요.","호흡기관이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비","증상: 똥이 잘 나오지 않음, 배가 아픔","예방법: 채소 많이 먹기, 물 충분히 마시기, 운동하기","2모둠 호흡기관 — 감기","증상: 기침, 콧물, 코 막힘","예방법: 손 씻기"],"title":"모둠별 질병 조사 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#4','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C32',3,'ox','auto','질병은 운이 나빠서 걸리는 것이라 예방할 수 없어요.',ARRAY['SC5-1-u4-X42']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"ox","stem":"질병은 운이 나빠서 걸리는 것이라 예방할 수 없어요.","answer":"X","reason_options":[{"t":"질병은 몸의 기관과 관련이 있고, 생활 습관으로 예방에 도움을 줄 수 있기 때문에","correct":true},{"t":"질병에 걸리는 것은 모두 운에 달려 있기 때문에","mis":"SC5-1-u4-X42"}],"mis":"SC5-1-u4-X42","explanation":["예방법을 떠올려요.","할 수 있는 일이 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#5','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',3,'mc','auto','모둠에서 발표 자료를 만드는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C34","difficulty":3,"kind":"mc","stem":"모둠에서 발표 자료를 만드는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠원마다 한 개씩 만들어 합치거나, 모둠에서 한 개를 함께 만든다","correct":true},{"t":"한 사람이 모든 것을 혼자 만든다","mis":"SC5-1-u4-X45"},{"t":"다른 모둠의 자료를 그대로 가져와 쓴다","mis":"SC5-1-u4-X45"},{"t":"만들지 않고 말로만 발표한다","mis":"SC5-1-u4-X45"}],"explanation":["함께 만드는 방법이에요.","두 가지가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#6','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',3,'error','auto','자료를 공유하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C34","difficulty":3,"kind":"error","stem":"자료를 공유하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"우진 — 「다른 모둠 자료는 보지 않고 우리 자료만 봤어.」","correct":true,"mis_target":"SC5-1-u4-X45"},{"t":"소윤 — 「다른 모둠 자료를 보고 알게 된 점을 댓글로 달았어.」","mis":"SC5-1-u4-X45"},{"t":"지율 — 「기기에서 열이 나서 바로 멈추고 선생님께 알렸어.」","mis":"SC5-1-u4-X45"}],"explanation":["공유하는 까닭을 떠올려요.","서로 나누어요.","우진이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#7','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C32',3,'mc','auto','질병에 걸리면 어떤 일이 생길 수 있나요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X40']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"mc","stem":"질병에 걸리면 어떤 일이 생길 수 있나요?","options":[{"t":"몸이 아프고 일상생활을 하는 데 어려움이 생긴다","correct":true},{"t":"몸에 아무런 변화가 없다","mis":"SC5-1-u4-X42"},{"t":"아픈 기관 하나만 멈추고 다른 기관은 전과 같이 일한다","mis":"SC5-1-u4-X40"},{"t":"운이 좋아져 더 튼튼해진다","mis":"SC5-1-u4-X42"}],"explanation":["아플 때를 떠올려요.","생활이 힘들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#8','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C33',4,'mc','auto','감기에 자주 걸리는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C33","difficulty":4,"kind":"mc","stem":"감기에 자주 걸리는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「밖에서 돌아오면 손을 씻는 습관을 들이면 예방에 도움이 될 거야.」","correct":true},{"t":"「운이 나빠서 그런 거니 어쩔 수 없어.」","mis":"SC5-1-u4-X42"},{"t":"「어른이 대신 예방해 줄 테니 너는 할 일이 없어.」","mis":"SC5-1-u4-X43"},{"t":"「약만 먹으면 다른 건 안 해도 돼.」","mis":"SC5-1-u4-X43"}],"explanation":["감기의 예방법이에요.","날마다 할 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#9','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',4,'mc','auto','배설기관을 고른 모둠이 교과서에서 질병의 예를 찾지 못했어요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C34","difficulty":4,"kind":"mc","stem":"배설기관을 고른 모둠이 교과서에서 질병의 예를 찾지 못했어요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"국가건강정보포털에서 직접 찾아 질병의 종류와 증상, 예방법을 조사한다","correct":true},{"t":"그럴듯한 질병을 지어내어 칸을 채운다","mis":"SC5-1-u4-X45"},{"t":"다른 모둠의 자료를 그대로 베낀다","mis":"SC5-1-u4-X45"},{"t":"예가 없으니 조사를 그만둔다","mis":"SC5-1-u4-X45"}],"explanation":["조사하는 활동이에요.","믿을 만한 곳에서 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#10','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C33',4,'essay','teacher','모둠별 질병 조사 자료를 보고 두 질병이 각각 어느 기관과 관련 있는지, 증상과 예방법은 무엇인지 쓰세요. 그리고 이 자료로 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C33","difficulty":4,"kind":"essay","stem":"모둠별 질병 조사 자료를 보고 두 질병이 각각 어느 기관과 관련 있는지, 증상과 예방법은 무엇인지 쓰세요. 그리고 이 자료로 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 변비는 소화기관과 관련이 있고, 똥이 잘 나오지 않고 배가 아픈 증상이 있으며, 채소를 많이 먹고 물을 충분히 마시고 운동하면 예방에 도움이 된다. 감기는 호흡기관과 관련이 있고, 기침·콧물·코 막힘이 나타나며, 손을 잘 씻으면 예방에 도움이 된다. 다양한 질병은 우리 몸의 기관과 관련이 있고, 평소의 생활 습관으로 질병을 예방하는 데 도움을 줄 수 있다.","scoring_points":["두 질병과 관련 기관을 바르게 썼는가","증상과 예방법을 바르게 썼는가","생활 습관으로 예방할 수 있다고 썼는가"]},"explanation":["1모둠부터 읽어요.","증상과 예방법을 나눠요.","알게 된 점을 써요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비","증상: 똥이 잘 나오지 않음, 배가 아픔","예방법: 채소 많이 먹기, 물 충분히 마시기, 운동하기","2모둠 호흡기관 — 감기","증상: 기침, 콧물, 코 막힘","예방법: 손 씻기"],"title":"모둠별 질병 조사 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#1','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',1,'mc','auto','질병을 예방하기 위해 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X48','SC5-1-u4-X42']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C35","difficulty":1,"kind":"mc","stem":"질병을 예방하기 위해 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"건강한 생활 방식을 실천한다","correct":true},{"t":"값비싼 장치를 사서 몸에 차고 다닌다","mis":"SC5-1-u4-X48"},{"t":"아플 때까지 기다렸다가 병원에 간다","mis":"SC5-1-u4-X42"},{"t":"운이 좋기를 바란다","mis":"SC5-1-u4-X42"}],"explanation":["예방은 미리 하는 일이에요.","생활 방식이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#2','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',1,'ox','auto','점검표에는 실천이 가능한 내용을 넣어요.',ARRAY['SC5-1-u4-X46']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C35","difficulty":1,"kind":"ox","stem":"점검표에는 실천이 가능한 내용을 넣어요.","answer":"O","reason_options":[{"t":"실천할 수 있어야 꾸준히 지킬 수 있기 때문에","correct":true},{"t":"어렵고 대단한 목표일수록 좋은 점검표이기 때문에","mis":"SC5-1-u4-X46"}],"mis":"SC5-1-u4-X46","explanation":["점검표를 만드는 까닭이에요.","실천하려고 만들어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#3','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',1,'sa','auto','「몸에 착용하는 장치는 손목시계, 반지, 목걸이, □□ 등의 모양입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C36","difficulty":1,"kind":"sa","stem":"「몸에 착용하는 장치는 손목시계, 반지, 목걸이, □□ 등의 모양입니다.」 □□에 알맞은 말을 쓰세요.","answer":["패치"],"explanation":["피부에 붙이는 것이에요.","두 글자예요.","패치예요."],"mis":"SC5-1-u4-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#4','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',1,'mc','auto','착용형 장치로 측정할 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X49']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C36","difficulty":1,"kind":"mc","stem":"착용형 장치로 측정할 수 있는 것은 어느 것인가요?","options":[{"t":"체온, 심장박동 수, 혈액에 들어 있는 산소의 양","correct":true},{"t":"뼈의 개수와 이름","mis":"SC5-1-u4-X49"},{"t":"오늘 먹은 음식의 맛","mis":"SC5-1-u4-X49"},{"t":"어젯밤에 꾼 꿈의 내용","mis":"SC5-1-u4-X49"}],"explanation":["몸의 수치예요.","7차시에 잰 것과 비슷해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#5','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',2,'match','auto','점검표 활동 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"match","stem":"점검표 활동 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"계획하기","r":"점검표에 넣을 내용을 정하고 만들 방법을 계획한다"},{"l":"해 보기","r":"점검표를 만들어 소개하고 일정한 기간 동안 실천한다"},{"l":"나누기","r":"실천한 결과를 되돌아보며 느낀 점을 발표한다"},{"l":"활동이 끝난 뒤","r":"건강한 생활 방식을 꾸준히 실천한다"}],"mis":"SC5-1-u4-X47","explanation":["단계를 떠올려요.","계획, 실천, 되돌아보기예요.","끝난 뒤에도 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#6','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',2,'mc','auto','친구가 만든 점검표 초안에서 넣기 알맞은 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"mc","stem":"친구가 만든 점검표 초안에서 넣기 알맞은 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"①, ②","correct":true},{"t":"③, ④","mis":"SC5-1-u4-X46"},{"t":"①, ③","mis":"SC5-1-u4-X46"},{"t":"②, ④","mis":"SC5-1-u4-X46"}],"explanation":["날마다 할 수 있나요?","③과 ④는 지키기 어려워요.","①, ②예요."],"asset":{"type":"passage","lines":["① 자기 전에 손을 씻었나요?","② 물을 충분히 마셨나요?","③ 하루에 열 시간씩 운동했나요?","④ 한 달 동안 한 번도 아프지 않았나요?"],"title":"친구가 만든 점검표 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#7','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',2,'mc','auto','착용형 장치의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"mc","stem":"착용형 장치의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"병원에 가지 않고도 건강 상태를 실시간으로 확인할 수 있다","correct":true},{"t":"크고 무거워서 집에서만 쓸 수 있다","mis":"SC5-1-u4-X49"},{"t":"병원에서만 쓸 수 있다","mis":"SC5-1-u4-X49"},{"t":"장치가 나 대신 건강한 생활 방식을 실천해 준다","mis":"SC5-1-u4-X48"}],"explanation":["몸에 차고 다녀요.","언제 어디서나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#8','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',2,'error','auto','착용형 장치에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X48','SC5-1-u4-X49']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"error","stem":"착용형 장치에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「장치가 알려 주니까 이제 손 씻기는 안 해도 돼.」","correct":true,"mis_target":"SC5-1-u4-X48"},{"t":"시아 — 「측정한 수치는 건강을 관리하는 자료로 쓸 수 있어.」","mis":"SC5-1-u4-X49"},{"t":"도하 — 「몸속 기관에 문제가 생기면 경고 신호가 울려.」","mis":"SC5-1-u4-X49"}],"explanation":["실천은 누가 하나요?","나 자신이에요.","은호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#9','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',2,'blank','auto','「자기 전에 하루를 되돌아보며 건강한 생활 방식을 (    )했는지 점검합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"blank","stem":"「자기 전에 하루를 되돌아보며 건강한 생활 방식을 (    )했는지 점검합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"실천","correct":true},{"t":"포기","mis":"SC5-1-u4-X47"},{"t":"계산","mis":"SC5-1-u4-X47"},{"t":"구입","mis":"SC5-1-u4-X48"}],"explanation":["점검표의 목적이에요.","직접 해 보는 것이에요.","실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#10','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',3,'mc','auto','점검표 활동이 끝난 뒤에 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"점검표 활동이 끝난 뒤에 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"건강한 생활 방식을 꾸준히 실천한다","correct":true},{"t":"한 번 만들어 보았으니 실천하지 않는다","mis":"SC5-1-u4-X47"},{"t":"점검표를 버리고 잊는다","mis":"SC5-1-u4-X47"},{"t":"장치를 사서 실천을 맡긴다","mis":"SC5-1-u4-X48"}],"explanation":["활동이 끝나도 건강은 계속이에요.","꾸준히요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#1','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',2,'mc','auto','점검표 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X47']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"mc","stem":"점검표 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉤ → ㉠ → ㉢ → ㉣","correct":true},{"t":"㉤ → ㉡ → ㉢ → ㉠ → ㉣","mis":"SC5-1-u4-X47"},{"t":"㉡ → ㉠ → ㉤ → ㉣ → ㉢","mis":"SC5-1-u4-X47"},{"t":"㉠ → ㉢ → ㉡ → ㉤ → ㉣","mis":"SC5-1-u4-X47"}],"explanation":["질병부터 골라요.","정하고, 만들고, 실천해요.","느낀 점은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 모둠별로 건강한 생활 방식 점검표를 만들어 소개한다.","㉡ 질병 하나를 골라 예방할 수 있는 방법을 이야기한다.","㉢ 점검표를 일정한 기간 동안 실천한다.","㉣ 실천한 결과를 되돌아보며 느낀 점을 발표한다.","㉤ 점검표에 넣을 내용을 정하고 만들 방법을 계획한다."],"title":"점검표 활동(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#2','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',2,'sa','auto','「몸에 착용하는 장치는 □□□□기술의 발달로 쓸 수 있게 되었습니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"sa","stem":"「몸에 착용하는 장치는 □□□□기술의 발달로 쓸 수 있게 되었습니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["생명공학"],"explanation":["생명과 기술을 이어요.","네 글자예요.","생명공학이에요."],"mis":"SC5-1-u4-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#3','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',3,'mc','auto','친구가 만든 점검표 초안의 ③을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"친구가 만든 점검표 초안의 ③을 바르게 고친 것은 어느 것인가요?","options":[{"t":"「하루에 한 번 이상 몸을 움직이는 운동을 했나요?」","correct":true},{"t":"「하루에 스무 시간씩 운동했나요?」","mis":"SC5-1-u4-X46"},{"t":"「운동은 빼고 장치만 차고 다녔나요?」","mis":"SC5-1-u4-X48"},{"t":"「고칠 필요가 없다」","mis":"SC5-1-u4-X46"}],"explanation":["지킬 수 있게 고쳐요.","날마다 할 수 있는 만큼이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 자기 전에 손을 씻었나요?","② 물을 충분히 마셨나요?","③ 하루에 열 시간씩 운동했나요?","④ 한 달 동안 한 번도 아프지 않았나요?"],"title":"친구가 만든 점검표 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#4','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',3,'ox','auto','착용형 장치가 있으면 건강한 생활 방식을 실천하지 않아도 돼요.',ARRAY['SC5-1-u4-X48']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C36","difficulty":3,"kind":"ox","stem":"착용형 장치가 있으면 건강한 생활 방식을 실천하지 않아도 돼요.","answer":"X","reason_options":[{"t":"장치는 몸의 수치를 재어 알려 줄 뿐이고 실천하는 것은 나 자신이기 때문에","correct":true},{"t":"장치가 질병을 모두 막아 주기 때문에","mis":"SC5-1-u4-X48"}],"mis":"SC5-1-u4-X48","explanation":["장치가 하는 일을 떠올려요.","재고 알려 줘요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#5','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',3,'mc','auto','착용형 장치로 측정한 수치를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X49']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C36","difficulty":3,"kind":"mc","stem":"착용형 장치로 측정한 수치를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"건강을 관리하기 위한 자료로 활용한다","correct":true},{"t":"어디에도 활용할 수 없다","mis":"SC5-1-u4-X49"},{"t":"장치를 꾸미는 데에만 쓴다","mis":"SC5-1-u4-X49"},{"t":"병원에 가야만 볼 수 있다","mis":"SC5-1-u4-X49"}],"explanation":["수치가 무엇을 알려 주나요?","건강 상태예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#6','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',3,'error','auto','점검표를 만들며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X45','SC5-1-u4-X47']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"error","stem":"점검표를 만들며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"로아 — 「스마트 기기로 관심 있는 다른 영상까지 마음껏 찾아봤어.」","correct":true,"mis_target":"SC5-1-u4-X45"},{"t":"하진 — 「다른 모둠 점검표와 우리 점검표를 견주어 봤어.」","mis":"SC5-1-u4-X47"},{"t":"서후 — 「다른 모둠 발표를 듣고 잘한 점을 칭찬했어.」","mis":"SC5-1-u4-X47"}],"explanation":["스마트 기기 약속이에요.","필요한 정보만 검색해요.","로아가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#7','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',3,'mc','auto','점검표를 그림으로 그리면 좋은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"점검표를 그림으로 그리면 좋은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"생활 방식이 잘 보여 한눈에 들어오기 때문에","correct":true},{"t":"어려운 목표를 더 많이 넣을 수 있기 때문에","mis":"SC5-1-u4-X46"},{"t":"그림이 있으면 실천하지 않아도 되기 때문에","mis":"SC5-1-u4-X47"},{"t":"그림이 있어야 장치가 알아보기 때문에","mis":"SC5-1-u4-X48"}],"explanation":["보기 좋게 만들어요.","한눈에 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#8','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',4,'mc','auto','건강을 지키는 장치를 새로 만든다면, 배운 좋은 점을 가장 잘 살린 생각은 어느 것인가요?',ARRAY['SC5-1-u4-X49']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C36","difficulty":4,"kind":"mc","stem":"건강을 지키는 장치를 새로 만든다면, 배운 좋은 점을 가장 잘 살린 생각은 어느 것인가요?","options":[{"t":"목에 거는 작은 장치로 숨 쉬는 빠르기를 재어, 갑자기 달라지면 알려 준다","correct":true},{"t":"아주 크고 무거워서 집에 두고만 써야 하는 장치","mis":"SC5-1-u4-X49"},{"t":"몸의 어떤 것도 재지 않고 모양만 예쁜 장치","mis":"SC5-1-u4-X49"},{"t":"문제가 생겨도 아무 신호도 보내지 않는 장치","mis":"SC5-1-u4-X49"}],"explanation":["작고, 재고, 알려 줘요.","세 가지를 모두 갖춰요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#9','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',4,'mc','auto','감기에 자주 걸리는 친구가 점검표에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C35","difficulty":4,"kind":"mc","stem":"감기에 자주 걸리는 친구가 점검표에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「밖에서 돌아오면 손을 씻었나요?」","correct":true},{"t":"「한 달 동안 감기에 한 번도 걸리지 않았나요?」","mis":"SC5-1-u4-X46"},{"t":"「하루에 열 시간씩 운동했나요?」","mis":"SC5-1-u4-X46"},{"t":"「장치를 하루 종일 차고 있었나요?」","mis":"SC5-1-u4-X48"}],"explanation":["감기의 예방법을 떠올려요.","날마다 할 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#10','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',4,'essay','teacher','건강한 생활 방식 점검표에 넣을 내용 세 가지를 실천할 수 있게 쓰고, 활동이 끝난 뒤의 다짐을 쓰세요. 그리고 착용형 장치와 내가 할 일을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C35","difficulty":4,"kind":"essay","stem":"건강한 생활 방식 점검표에 넣을 내용 세 가지를 실천할 수 있게 쓰고, 활동이 끝난 뒤의 다짐을 쓰세요. 그리고 착용형 장치와 내가 할 일을 견주어 쓰세요.","answer_guide":{"answer":"예: 점검표에 「밖에서 돌아오면 손을 씻었나요?」, 「물을 충분히 마셨나요?」, 「채소 반찬을 먹었나요?」를 넣겠다. 자기 전에 하루를 되돌아보며 점검하고, 활동이 끝난 뒤에도 꾸준히 실천하겠다. 착용형 장치는 체온이나 심장박동 수를 재어 알려 주지만, 건강한 생활 방식을 실천하는 것은 나 자신이다.","scoring_points":["실천할 수 있는 내용 세 가지를 썼는가","꾸준히 실천하겠다는 다짐을 썼는가","장치는 알려 주고 실천은 내가 한다고 썼는가"]},"explanation":["날마다 할 수 있는 것이에요.","끝난 뒤에도요.","장치와 나를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#1','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C5',1,'mc','auto','등 한가운데에 있는 뼈는 어느 것인가요?',ARRAY['SC5-1-u4-X05']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C5","difficulty":1,"kind":"mc","stem":"등 한가운데에 있는 뼈는 어느 것인가요?","options":[{"t":"척추뼈","correct":true},{"t":"머리뼈","mis":"SC5-1-u4-X05"},{"t":"갈비뼈","mis":"SC5-1-u4-X05"},{"t":"다리뼈","mis":"SC5-1-u4-X05"}],"explanation":["등을 만져 봐요.","한가운데 길게 이어져요.","척추뼈예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#2','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',1,'ox','auto','근육은 줄어들거나 늘어나면서 뼈를 움직여요.',ARRAY['SC5-1-u4-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C7","difficulty":1,"kind":"ox","stem":"근육은 줄어들거나 늘어나면서 뼈를 움직여요.","answer":"O","reason_options":[{"t":"근육은 뼈에 연결되어 있어 줄어들거나 늘어나며 뼈를 움직이기 때문에","correct":true},{"t":"뼈가 스스로 움직이고 근육은 따라만 가기 때문에","mis":"SC5-1-u4-X03"}],"mis":"SC5-1-u4-X03","explanation":["뼈와 근육 모형을 떠올려요.","근육이 움직여요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#3','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C8',1,'sa','auto','튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C8","difficulty":1,"kind":"sa","stem":"튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰세요.","answer":["올라갔다","올라갔다.","올라간다","올라감","올라가","위로 올라갔다"],"explanation":["팔이 구부러지는 쪽이에요.","아래팔뼈가 위로 가요.","올라갔다예요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"},"mis":"SC5-1-u4-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#4','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C24',1,'mc','auto','노폐물에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X31']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"mc","stem":"노폐물에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에서 영양소가 쓰이면서 생긴, 몸에 필요 없는 것","correct":true},{"t":"몸에 꼭 필요한 영양소","mis":"SC5-1-u4-X31"},{"t":"먹은 음식물에서만 곧바로 생기는 것","mis":"SC5-1-u4-X31"},{"t":"숨을 쉴 때 들이마시는 산소","mis":"SC5-1-u4-X31"}],"explanation":["필요 없는 것이에요.","영양소가 쓰일 때 생겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#5','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C4',1,'blank','auto','「심장, 폐, 뇌처럼 우리가 살아가는 데 필요한 일을 하는 몸속 부분을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X04']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C4","difficulty":1,"kind":"blank","stem":"「심장, 폐, 뇌처럼 우리가 살아가는 데 필요한 일을 하는 몸속 부분을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"기관","correct":true},{"t":"골격","mis":"SC5-1-u4-X04"},{"t":"근육","mis":"SC5-1-u4-X04"},{"t":"도안","mis":"SC5-1-u4-X04"}],"explanation":["몸속에서 일을 해요.","두 글자예요.","기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#6','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C1',1,'mc','auto','튼튼반 일지 ①의 인체 골격 모형으로 달리는 몸동작을 만들 수 있었던 까닭은 어느 것인가요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C1","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ①의 인체 골격 모형으로 달리는 몸동작을 만들 수 있었던 까닭은 어느 것인가요?","options":[{"t":"여러 뼈를 이은 곳이 접혔다 펴지기 때문에","correct":true},{"t":"뼈가 커다란 하나로 되어 있기 때문에","mis":"SC5-1-u4-X01"},{"t":"뼈가 스스로 늘어나기 때문에","mis":"SC5-1-u4-X03"},{"t":"뼈가 몸의 겉을 감싸고 있기 때문에","mis":"SC5-1-u4-X01"}],"explanation":["똑딱단추로 이은 곳이에요.","접혔다 펴져요.","첫 번째예요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#7','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C29',1,'mc','auto','튼튼반 일지 ⑥에서 체온이 가장 높았던 때는 언제인가요?',ARRAY['SC5-1-u4-X37','SC5-1-u4-X38']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ⑥에서 체온이 가장 높았던 때는 언제인가요?","options":[{"t":"제자리 뛰기 직후","correct":true},{"t":"운동 전","mis":"SC5-1-u4-X37"},{"t":"5분 휴식 후","mis":"SC5-1-u4-X38"},{"t":"세 번 모두 같다","mis":"SC5-1-u4-X37"}],"explanation":["세 체온을 견줘요.","36.8 °C예요.","운동 직후예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#8','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C2',1,'mc','auto','인체 골격 모형에서 똑딱단추가 하는 일은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C2","difficulty":1,"kind":"mc","stem":"인체 골격 모형에서 똑딱단추가 하는 일은 어느 것인가요?","options":[{"t":"뼈 도안과 뼈 도안을 이어 준다","correct":true},{"t":"몸속 모습을 그려 준다","mis":"SC5-1-u4-X02"},{"t":"모형을 예쁘게 꾸민다","mis":"SC5-1-u4-X02"},{"t":"뼈 모양을 본떠 준다","mis":"SC5-1-u4-X02"}],"explanation":["잇는 도구예요.","도안과 도안 사이예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#9','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C12',2,'mc','auto','튼튼반 일지 ②에서 영양소와 대부분의 수분을 흡수한 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X11','SC5-1-u4-X12']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ②에서 영양소와 대부분의 수분을 흡수한 기관은 어느 것인가요?","options":[{"t":"작은창자","correct":true},{"t":"위","mis":"SC5-1-u4-X11"},{"t":"큰창자","mis":"SC5-1-u4-X11"},{"t":"식도","mis":"SC5-1-u4-X12"}],"explanation":["㉠ 자리예요.","위와 큰창자 사이예요.","작은창자예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#10','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C29',2,'sa','auto','튼튼반 일지 ⑥에서 제자리 뛰기 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C29","difficulty":2,"kind":"sa","stem":"튼튼반 일지 ⑥에서 제자리 뛰기 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.","answer":["104","104회"],"explanation":["둘째 줄을 읽어요.","백 회가 넘어요.","104회예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"},"mis":"SC5-1-u4-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#11','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C13',2,'ox','auto','간은 음식물이 직접 지나가는 소화기관이에요.',ARRAY['SC5-1-u4-X13']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C13","difficulty":2,"kind":"ox","stem":"간은 음식물이 직접 지나가는 소화기관이에요.","answer":"X","reason_options":[{"t":"간·쓸개·이자는 음식물이 지나가지 않고 소화를 돕기 때문에","correct":true},{"t":"음식물이 위에서 간으로 내려가기 때문에","mis":"SC5-1-u4-X13"}],"mis":"SC5-1-u4-X13","explanation":["튼튼반 일지 ②를 떠올려요.","구멍을 내지 않았어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#12','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C6',2,'mc','auto','머리뼈가 보호하는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X05','SC5-1-u4-X06']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C6","difficulty":2,"kind":"mc","stem":"머리뼈가 보호하는 기관은 어느 것인가요?","options":[{"t":"뇌","correct":true},{"t":"심장","mis":"SC5-1-u4-X05"},{"t":"폐","mis":"SC5-1-u4-X05"},{"t":"머리뼈는 아무것도 보호하지 않는다","mis":"SC5-1-u4-X06"}],"explanation":["머리 안에 있어요.","생각하는 기관이에요.","뇌예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#13','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C31',2,'match','auto','운동할 때 일어나는 일과 그 일을 하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C31","difficulty":2,"kind":"match","stem":"운동할 때 일어나는 일과 그 일을 하는 것을 알맞게 이으세요.","pairs":[{"l":"뼈와 근육","r":"산소와 영양소를 이용해 몸을 움직인다"},{"l":"호흡기관","r":"산소를 많이 받아들이려고 호흡이 빨라진다"},{"l":"순환기관","r":"산소와 영양소를 빠르게 운반하려고 심장이 빨리 뛴다"}],"mis":"SC5-1-u4-X40","explanation":["누가 쓰고 누가 대나요?","받아들이고 운반해요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#14','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C8',2,'mc','auto','튼튼반 일지 ①에서 손잡이를 밀 때 아래팔뼈 도안은 어떻게 되었을까요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03','SC5-1-u4-X07']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C8","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ①에서 손잡이를 밀 때 아래팔뼈 도안은 어떻게 되었을까요?","options":[{"t":"바깥쪽 근육 도안이 줄어들며 따라 내려갔다","correct":true},{"t":"안쪽 근육 도안이 줄어들며 더 올라갔다","mis":"SC5-1-u4-X08"},{"t":"근육과 관계없이 스스로 늘어났다","mis":"SC5-1-u4-X03"},{"t":"안쪽 근육 도안이 밀어 내렸다","mis":"SC5-1-u4-X07"}],"explanation":["마지막 줄을 읽어요.","팔이 펴져요.","첫 번째예요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#15','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C16',2,'error','auto','심장에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X20','SC5-1-u4-X17']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C16","difficulty":2,"kind":"error","stem":"심장에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「심장은 배 아래쪽 한가운데에 있어.」","correct":true,"mis_target":"SC5-1-u4-X20"},{"t":"지원 — 「심장은 가슴 중앙에서 왼쪽으로 약간 치우쳐 있어.」","mis":"SC5-1-u4-X20"},{"t":"태경 — 「심장은 펌프 작용으로 혈액을 보내.」","mis":"SC5-1-u4-X17"}],"explanation":["가슴에 손을 대 봐요.","가슴이에요.","수빈이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#16','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',2,'mc','auto','인체 골격 모형에는 없고 내 몸에는 있어서, 내 몸이 스스로 움직일 수 있게 하는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02','SC5-1-u4-X04']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C7","difficulty":2,"kind":"mc","stem":"인체 골격 모형에는 없고 내 몸에는 있어서, 내 몸이 스스로 움직일 수 있게 하는 것은 어느 것인가요?","options":[{"t":"근육","correct":true},{"t":"똑딱단추","mis":"SC5-1-u4-X02"},{"t":"뼈 도안","mis":"SC5-1-u4-X02"},{"t":"그림 도구","mis":"SC5-1-u4-X04"}],"explanation":["모형은 손으로 움직였어요.","뼈에 연결된 것이에요.","근육이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#17','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',3,'mc','auto','튼튼반 일지 ⑧에서 하람의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X07','SC5-1-u4-X03','SC5-1-u4-X08']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C7","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 하람의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「근육은 밀지 못해. 바깥쪽 근육이 줄어들면서 팔이 펴지는 거야.」","correct":true},{"t":"「맞아, 근육이 뼈를 밀어.」","mis":"SC5-1-u4-X07"},{"t":"「근육과 관계없이 뼈가 스스로 펴져.」","mis":"SC5-1-u4-X03"},{"t":"「안쪽 근육이 줄어들어서 팔이 펴져.」","mis":"SC5-1-u4-X08"}],"explanation":["근육이 하는 일이에요.","줄어들며 당겨요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#18','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C32',3,'mc','auto','튼튼반 일지 ⑧에서 지우의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 지우의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「질병은 우리 몸의 기관과 관련이 있고, 생활 습관으로 예방에 도움을 줄 수 있어.」","correct":true},{"t":"「맞아, 운이 나빠서야.」","mis":"SC5-1-u4-X42"},{"t":"「예방은 어른만 할 수 있어.」","mis":"SC5-1-u4-X43"},{"t":"「질병은 약으로만 막을 수 있어.」","mis":"SC5-1-u4-X43"}],"explanation":["일지 ⑦을 떠올려요.","예방법이 있었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#19','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C22',3,'ox','auto','숨을 들이마실 때와 내쉴 때 공기는 같은 길을 반대 방향으로 지나요.',ARRAY['SC5-1-u4-X26']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C22","difficulty":3,"kind":"ox","stem":"숨을 들이마실 때와 내쉴 때 공기는 같은 길을 반대 방향으로 지나요.","answer":"O","reason_options":[{"t":"들이마실 때는 코에서 폐로 들어가고 내쉴 때는 폐에서 코로 나가기 때문에","correct":true},{"t":"내쉴 때는 식도를 따라 나가기 때문에","mis":"SC5-1-u4-X26"}],"mis":"SC5-1-u4-X26","explanation":["튼튼반 일지 ④를 떠올려요.","거꾸로예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#20','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C25',3,'mc','auto','튼튼반 일지 ⑤를 보고 콩팥을 지난 두 갈래를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X33','SC5-1-u4-X34']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑤를 보고 콩팥을 지난 두 갈래를 바르게 말한 것은 어느 것인가요?","options":[{"t":"노폐물은 오줌이 되어 몸 밖으로 나가고, 걸러진 혈액은 다시 온몸을 순환한다","correct":true},{"t":"걸러진 혈액도 오줌과 함께 몸 밖으로 나간다","mis":"SC5-1-u4-X33"},{"t":"오줌이 혈관을 따라 다시 온몸을 돈다","mis":"SC5-1-u4-X34"},{"t":"걸러진 혈액은 방광에 모였다가 나간다","mis":"SC5-1-u4-X33"}],"explanation":["두 갈래예요.","오줌과 혈액이 갈라져요.","첫 번째예요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#21','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C6',3,'mc','auto','갈비뼈가 없다면 어떤 문제가 생길까요?',ARRAY['SC5-1-u4-X06','SC5-1-u4-X05']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C6","difficulty":3,"kind":"mc","stem":"갈비뼈가 없다면 어떤 문제가 생길까요?","options":[{"t":"가슴 속의 심장과 폐를 보호하기 어려워진다","correct":true},{"t":"아무 문제도 생기지 않는다","mis":"SC5-1-u4-X06"},{"t":"머리 속의 뇌를 보호하기 어려워진다","mis":"SC5-1-u4-X05"},{"t":"음식물이 소화되지 않는다","mis":"SC5-1-u4-X06"}],"explanation":["갈비뼈가 둘러싼 곳이에요.","가슴 속이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#22','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C29',3,'mc','auto','튼튼반 일지 ⑥에서 운동 직후 땀이 난 것과 함께 일어난 변화로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X37','SC5-1-u4-X40']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C29","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑥에서 운동 직후 땀이 난 것과 함께 일어난 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"체온이 올라가고 맥박 수가 많아졌다","correct":true},{"t":"체온이 내려가고 맥박 수가 적어졌다","mis":"SC5-1-u4-X37"},{"t":"소화기관이 하던 일을 멈추었다","mis":"SC5-1-u4-X40"},{"t":"아무 변화가 없었다","mis":"SC5-1-u4-X37"}],"explanation":["운동 전과 견줘요.","모두 높아졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#23','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C30',4,'mc','auto','운동 직후 숨을 크게 몰아쉬는 친구를 보고 가장 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X28','SC5-1-u4-X27']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"mc","stem":"운동 직후 숨을 크게 몰아쉬는 친구를 보고 가장 바르게 설명한 것은 어느 것인가요?","options":[{"t":"근육이 산소를 많이 쓰므로, 산소를 많이 받아들이려고 호흡이 빨라진 것이다","correct":true},{"t":"그냥 몸이 힘들어서 그런 것일 뿐이다","mis":"SC5-1-u4-X39"},{"t":"이산화 탄소를 많이 받아들이려고 그런 것이다","mis":"SC5-1-u4-X28"},{"t":"폐에서 영양소를 흡수하려고 그런 것이다","mis":"SC5-1-u4-X27"}],"explanation":["근육에 필요한 것이에요.","산소를 많이 받아들여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#24','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',4,'essay','teacher','튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰고, 손잡이를 밀 때 아래팔뼈 도안이 어떻게 되는지 쓰세요. 그리고 일지 ⑧의 하람이 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C7","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰고, 손잡이를 밀 때 아래팔뼈 도안이 어떻게 되는지 쓰세요. 그리고 일지 ⑧의 하람이 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: ( ㉠ )에는 「올라갔다」가 들어간다. 손잡이를 밀면 바깥쪽 근육 도안이 줄어들고 안쪽 근육 도안이 늘어나면서 아래팔뼈 도안이 따라 내려간다. 하람아, 근육은 뼈를 밀지 못해. 근육은 뼈에 연결되어 있어서 줄어들거나 늘어나면서 뼈를 움직이고, 팔을 펼 때는 바깥쪽 근육이 줄어드는 거야.","scoring_points":["㉠에 올라갔다를 썼는가","밀 때 바깥쪽 근육이 줄어들어 내려간다고 썼는가","근육은 밀지 않는다고 하람의 생각을 바로잡았는가"]},"explanation":["㉠부터 써요.","밀 때는 반대예요.","하람에게 말해 줘요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#25','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C26',4,'essay','teacher','튼튼반 일지 ⑤의 ( ? )에 들어갈 내용을 쓰고, 오줌이 몸 밖으로 나가는 길을 쓰세요. 그리고 일지 ⑧의 서아에게 배설과 배출의 차이를 설명해 주세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C26","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ⑤의 ( ? )에 들어갈 내용을 쓰고, 오줌이 몸 밖으로 나가는 길을 쓰세요. 그리고 일지 ⑧의 서아에게 배설과 배출의 차이를 설명해 주세요.","answer_guide":{"answer":"예: ( ? )에는 「오줌을 모아 두었다가 몸 밖으로 내보낸다」가 들어간다. 콩팥에서 만든 오줌은 오줌관을 지나 방광에 모였다가 몸 밖으로 나간다. 서아야, 배설은 혈액 속의 노폐물을 콩팥이 걸러 오줌으로 내보내는 것이고, 똥을 누는 것은 소화되고 남은 음식물 찌꺼기를 내보내는 배출이야.","scoring_points":["방광이 하는 일을 썼는가","콩팥 → 오줌관 → 방광의 길을 썼는가","배설과 배출을 구별해 서아에게 설명했는가"]},"explanation":["방광부터 써요.","오줌을 따라가요.","서아에게 말해 줘요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#1','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C13',1,'mc','auto','튼튼반 일지 ②에서 구멍을 내지 않은 간, 쓸개, 이자가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X13','SC5-1-u4-X26']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C13","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ②에서 구멍을 내지 않은 간, 쓸개, 이자가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 지나가지는 않지만 소화를 돕는다","correct":true},{"t":"음식물이 지나가는 통로이다","mis":"SC5-1-u4-X13"},{"t":"소화와 관계없는 일을 한다","mis":"SC5-1-u4-X13"},{"t":"공기가 지나가는 통로이다","mis":"SC5-1-u4-X26"}],"explanation":["구멍을 내지 않은 까닭이에요.","지나가지 않아요.","첫 번째예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#2','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C11',1,'ox','auto','음식물 찌꺼기는 항문을 통해 몸 밖으로 나가요.',ARRAY['SC5-1-u4-X14']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C11","difficulty":1,"kind":"ox","stem":"음식물 찌꺼기는 항문을 통해 몸 밖으로 나가요.","answer":"O","reason_options":[{"t":"큰창자에서 수분이 흡수되고 남은 찌꺼기가 배출되기 때문에","correct":true},{"t":"찌꺼기는 몸속에 그대로 쌓이기 때문에","mis":"SC5-1-u4-X14"}],"mis":"SC5-1-u4-X14","explanation":["소화 경로의 끝이에요.","항문이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#3','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C12',1,'sa','auto','튼튼반 일지 ②의 ( ㉠ )에 알맞은 기관의 이름을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C12","difficulty":1,"kind":"sa","stem":"튼튼반 일지 ②의 ( ㉠ )에 알맞은 기관의 이름을 쓰세요.","answer":["작은창자"],"explanation":["위 다음이에요.","영양소를 흡수해요.","작은창자예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"},"mis":"SC5-1-u4-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#4','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C21',1,'mc','auto','폐가 받아들인 산소가 쓰이는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X27','SC5-1-u4-X09']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C21","difficulty":1,"kind":"mc","stem":"폐가 받아들인 산소가 쓰이는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸을 움직이거나 몸속 기관이 일하는 데","correct":true},{"t":"아무 데도 쓰이지 않는다","mis":"SC5-1-u4-X27"},{"t":"음식물을 크게 뭉치는 데","mis":"SC5-1-u4-X09"},{"t":"오줌을 모아 두는 데","mis":"SC5-1-u4-X27"}],"explanation":["산소는 몸에 필요해요.","움직이고 일하는 데예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#5','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C10',1,'blank','auto','「음식물을 잘게 쪼개 영양소를 흡수할 수 있게 하는 일을 담당하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X24','SC5-1-u4-X30']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C10","difficulty":1,"kind":"blank","stem":"「음식물을 잘게 쪼개 영양소를 흡수할 수 있게 하는 일을 담당하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"소화기관","correct":true},{"t":"순환기관","mis":"SC5-1-u4-X22"},{"t":"호흡기관","mis":"SC5-1-u4-X24"},{"t":"배설기관","mis":"SC5-1-u4-X30"}],"explanation":["잘게 쪼개요.","소화를 담당해요.","소화기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#6','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C14',1,'mc','auto','음식물을 꼭꼭 씹으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X15','SC5-1-u4-X11']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C14","difficulty":1,"kind":"mc","stem":"음식물을 꼭꼭 씹으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘게 쪼개지고 물러져 소화가 잘된다","correct":true},{"t":"더 빨리 먹을 수 있다","mis":"SC5-1-u4-X15"},{"t":"음식물이 더 커진다","mis":"SC5-1-u4-X15"},{"t":"흡수가 입에서 모두 끝난다","mis":"SC5-1-u4-X11"}],"explanation":["입이 하는 일이에요.","잘게 부수어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#7','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C32',1,'mc','auto','튼튼반 일지 ⑦에서 1모둠이 조사한 변비와 관련 있는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C32","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ⑦에서 1모둠이 조사한 변비와 관련 있는 기관은 어느 것인가요?","options":[{"t":"소화기관","correct":true},{"t":"호흡기관","mis":"SC5-1-u4-X44"},{"t":"배설기관","mis":"SC5-1-u4-X44"},{"t":"어느 기관과도 관련이 없다","mis":"SC5-1-u4-X42"}],"explanation":["1모둠 줄을 읽어요.","똥과 관련 있어요.","소화기관이에요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#8','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C9',1,'mc','auto','튼튼반 일지 ①에서 손잡이를 잡아당길 때 줄어든 것은 어느 것인가요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03','SC5-1-u4-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C9","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ①에서 손잡이를 잡아당길 때 줄어든 것은 어느 것인가요?","options":[{"t":"안쪽 근육 도안","correct":true},{"t":"바깥쪽 근육 도안","mis":"SC5-1-u4-X08"},{"t":"아래팔뼈 도안","mis":"SC5-1-u4-X03"},{"t":"똑딱단추","mis":"SC5-1-u4-X02"}],"explanation":["둘째 줄을 읽어요.","안쪽이에요.","안쪽 근육 도안이에요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#9','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C18',2,'mc','auto','튼튼반 일지 ③에서 붉은 색소 물이 호스를 따라 돈 것은 우리 몸의 무엇을 나타내나요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C18","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ③에서 붉은 색소 물이 호스를 따라 돈 것은 우리 몸의 무엇을 나타내나요?","options":[{"t":"혈액이 혈관을 따라 온몸을 도는 혈액 순환","correct":true},{"t":"공기가 숨관을 지나는 호흡","mis":"SC5-1-u4-X22"},{"t":"음식물이 식도를 지나는 소화","mis":"SC5-1-u4-X22"},{"t":"오줌이 오줌관을 지나는 배설","mis":"SC5-1-u4-X22"}],"explanation":["붉은 색소 물은 혈액이에요.","호스는 혈관이에요.","혈액 순환이에요."],"asset":{"type":"passage","lines":["펌프, 호스, 붉은 색소 물로 순환기관 모형실험을 했다.","펌프를 쥐었다 폈다 하자 붉은 색소 물이 호스를 따라 돌았다.","펌프를 멈추자 붉은 색소 물도 멈추었다.","실험이 끝난 뒤 주변을 정리하고 물을 올바르게 처리했다."],"title":"튼튼반 탐구 일지 ③ 순환기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#10','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C22',2,'sa','auto','「숨을 내쉴 때 공기는 폐에서 나와 가장 먼저 □□□□를 지납니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C22","difficulty":2,"kind":"sa","stem":"「숨을 내쉴 때 공기는 폐에서 나와 가장 먼저 □□□□를 지납니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["숨관가지"],"explanation":["폐와 숨관 사이예요.","네 글자예요.","숨관가지예요."],"mis":"SC5-1-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#11','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C17',2,'ox','auto','혈관은 심장 가까이에만 있어요.',ARRAY['SC5-1-u4-X18']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C17","difficulty":2,"kind":"ox","stem":"혈관은 심장 가까이에만 있어요.","answer":"X","reason_options":[{"t":"혈관은 머리끝부터 발끝까지 온몸에 퍼져 있기 때문에","correct":true},{"t":"혈액은 심장 주변에서만 돌기 때문에","mis":"SC5-1-u4-X18"}],"mis":"SC5-1-u4-X18","explanation":["손끝에도 피가 나요.","온몸이에요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#12','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C14',2,'mc','auto','소화 과정 모형에서 막대를 천천히 내리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X16','SC5-1-u4-X13']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C14","difficulty":2,"kind":"mc","stem":"소화 과정 모형에서 막대를 천천히 내리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 거치는 소화기관과 음식물의 모습을 차례대로 관찰하려고","correct":true},{"t":"활동을 빨리 끝내려고","mis":"SC5-1-u4-X16"},{"t":"막대를 도안에 고정하려고","mis":"SC5-1-u4-X16"},{"t":"간 자리의 구멍을 보려고","mis":"SC5-1-u4-X13"}],"explanation":["구멍으로 무엇을 보나요?","차례대로 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#13','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C12',2,'match','auto','음식물의 모습과 그 모습이 나타나는 기관을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"match","stem":"음식물의 모습과 그 모습이 나타나는 기관을 알맞게 이으세요.","pairs":[{"l":"이로 부서지고 침과 섞인다","r":"입"},{"l":"소화를 돕는 액체와 섞여 잘게 쪼개진다","r":"위"},{"l":"영양소와 대부분의 수분이 흡수된다","r":"작은창자"},{"l":"찌꺼기의 수분이 흡수된다","r":"큰창자"}],"mis":"SC5-1-u4-X12","explanation":["막대를 내리며 본 것이에요.","위에서 아래로요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#14','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C11',2,'mc','auto','튼튼반 일지 ②를 보고 음식물이 지나간 길을 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u4-X10','SC5-1-u4-X13','SC5-1-u4-X26']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C11","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ②를 보고 음식물이 지나간 길을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"입 → 식도 → 위 → 작은창자 → 큰창자 → 항문","correct":true},{"t":"입 → 식도 → 위 → 큰창자 → 작은창자 → 항문","mis":"SC5-1-u4-X10"},{"t":"입 → 식도 → 간 → 위 → 작은창자 → 항문","mis":"SC5-1-u4-X13"},{"t":"입 → 숨관 → 위 → 작은창자 → 큰창자 → 항문","mis":"SC5-1-u4-X26"}],"explanation":["일지 첫 줄을 읽어요.","㉠은 작은창자예요.","첫 번째예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#15','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C24',2,'error','auto','노폐물에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X31','SC5-1-u4-X32']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C24","difficulty":2,"kind":"error","stem":"노폐물에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"한결 — 「노폐물은 먹은 음식물에서만 곧바로 생겨.」","correct":true,"mis_target":"SC5-1-u4-X31"},{"t":"보민 — 「영양소가 쓰이면서 노폐물이 생겨.」","mis":"SC5-1-u4-X31"},{"t":"찬희 — 「혈액 속 노폐물은 콩팥이 걸러 내.」","mis":"SC5-1-u4-X32"}],"explanation":["노폐물이 생기는 때예요.","영양소가 쓰일 때예요.","한결이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#16','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C10',2,'mc','auto','소화에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X09','SC5-1-u4-X22','SC5-1-u4-X30']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C10","difficulty":2,"kind":"mc","stem":"소화에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"영양소를 흡수할 수 있도록 음식물을 잘게 쪼개는 과정","correct":true},{"t":"음식물을 크게 뭉치는 과정","mis":"SC5-1-u4-X09"},{"t":"혈액을 온몸으로 보내는 과정","mis":"SC5-1-u4-X22"},{"t":"혈액 속의 노폐물을 걸러 내는 과정","mis":"SC5-1-u4-X30"}],"explanation":["잘게 쪼개요.","흡수하려고요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#17','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C16',3,'mc','auto','튼튼반 일지 ⑧에서 도윤의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X19']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C16","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 도윤의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「심장은 혈액을 만들지 않고, 펌프 작용으로 온몸에 보내.」","correct":true},{"t":"「맞아, 심장이 혈액을 만들어.」","mis":"SC5-1-u4-X17"},{"t":"「혈관이 혈액을 만들어 내.」","mis":"SC5-1-u4-X17"},{"t":"「혈액은 한 번 돌고 없어져.」","mis":"SC5-1-u4-X19"}],"explanation":["모형의 펌프예요.","보내는 일이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#18','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C36',3,'mc','auto','튼튼반 일지 ⑧에서 다온의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X48','SC5-1-u4-X49']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C36","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 다온의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「장치는 몸의 수치를 재어 알려 줄 뿐이고, 실천하는 것은 나 자신이야.」","correct":true},{"t":"「맞아, 장치가 다 해 줘.」","mis":"SC5-1-u4-X48"},{"t":"「장치가 질병을 모두 막아 줘.」","mis":"SC5-1-u4-X48"},{"t":"「장치는 아무것도 재지 못해.」","mis":"SC5-1-u4-X49"}],"explanation":["장치가 하는 일이에요.","재고 알려 줘요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#19','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C33',3,'ox','auto','질병 예방은 어른만 할 수 있는 일이에요.',ARRAY['SC5-1-u4-X43']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C33","difficulty":3,"kind":"ox","stem":"질병 예방은 어른만 할 수 있는 일이에요.","answer":"X","reason_options":[{"t":"손 씻기, 채소 먹기처럼 어린이도 날마다 할 수 있는 일이 예방에 도움이 되기 때문에","correct":true},{"t":"예방은 병원에서 어른이 해 주는 것이기 때문에","mis":"SC5-1-u4-X43"}],"mis":"SC5-1-u4-X43","explanation":["일지 ⑦의 점검표를 떠올려요.","우리도 할 수 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#20','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C21',3,'mc','auto','혈액이 온몸에 운반하는 산소와 영양소는 각각 어느 기관에서 받아들이나요?',ARRAY['SC5-1-u4-X27','SC5-1-u4-X17','SC5-1-u4-X26']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"mc","stem":"혈액이 온몸에 운반하는 산소와 영양소는 각각 어느 기관에서 받아들이나요?","options":[{"t":"산소는 폐, 영양소는 작은창자","correct":true},{"t":"산소는 작은창자, 영양소는 폐","mis":"SC5-1-u4-X27"},{"t":"둘 다 심장이 만들어 낸다","mis":"SC5-1-u4-X17"},{"t":"산소는 식도, 영양소는 숨관","mis":"SC5-1-u4-X26"}],"explanation":["호흡과 소화를 떠올려요.","폐와 작은창자예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#21','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C19',3,'mc','auto','순환기관 모형실험에서 펌프를 쥐었다 폈다 하는 것은 우리 몸의 무엇을 나타내나요?',ARRAY['SC5-1-u4-X21','SC5-1-u4-X17','SC5-1-u4-X22']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"순환기관 모형실험에서 펌프를 쥐었다 폈다 하는 것은 우리 몸의 무엇을 나타내나요?","options":[{"t":"심장의 펌프 작용","correct":true},{"t":"혈관이 늘어났다 줄어드는 것","mis":"SC5-1-u4-X21"},{"t":"혈액이 새로 만들어지는 것","mis":"SC5-1-u4-X17"},{"t":"숨을 들이마시고 내쉬는 것","mis":"SC5-1-u4-X22"}],"explanation":["펌프는 심장이에요.","혈액을 보내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#22','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C35',3,'mc','auto','점검표를 일정한 기간 동안 실천한 뒤 「나누기」에서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"점검표를 일정한 기간 동안 실천한 뒤 「나누기」에서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"실천한 결과를 되돌아보며 느낀 점을 발표하고 잘한 점을 칭찬한다","correct":true},{"t":"점검표를 버리고 실천을 그만둔다","mis":"SC5-1-u4-X47"},{"t":"실천하지 못한 날은 지우고 다 했다고 적는다","mis":"SC5-1-u4-X47"},{"t":"장치가 잰 수치만 발표한다","mis":"SC5-1-u4-X48"}],"explanation":["되돌아보는 단계예요.","느낀 점과 칭찬이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#23','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C25',4,'mc','auto','노폐물이 많은 혈액이 콩팥으로 들어가 오줌이 몸 밖으로 나가기까지를 차례대로 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u4-X34','SC5-1-u4-X30']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C25","difficulty":4,"kind":"mc","stem":"노폐물이 많은 혈액이 콩팥으로 들어가 오줌이 몸 밖으로 나가기까지를 차례대로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"혈관 → 콩팥 → 오줌관 → 방광 → 몸 밖","correct":true},{"t":"혈관 → 방광 → 오줌관 → 콩팥 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"혈관 → 콩팥 → 방광 → 오줌관 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"혈관 → 큰창자 → 항문 → 몸 밖","mis":"SC5-1-u4-X30"}],"explanation":["콩팥에서 오줌이 만들어져요.","통로를 지나 모여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#24','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C11',4,'essay','teacher','튼튼반 일지 ②를 보고 음식물이 지나가는 길을 끝까지 쓰고, 영양소와 수분이 흡수되는 곳을 쓰세요. 그리고 간, 쓸개, 이자 자리에 구멍을 내지 않은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C11","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ②를 보고 음식물이 지나가는 길을 끝까지 쓰고, 영양소와 수분이 흡수되는 곳을 쓰세요. 그리고 간, 쓸개, 이자 자리에 구멍을 내지 않은 까닭을 쓰세요.","answer_guide":{"answer":"예: 음식물은 입 → 식도 → 위 → 작은창자 → 큰창자를 지나 남은 찌꺼기가 항문으로 나간다. 영양소와 대부분의 수분은 작은창자에서, 찌꺼기에 남은 수분은 큰창자에서 흡수된다. 간, 쓸개, 이자는 음식물이 지나가지 않고 소화를 돕는 기관이라서 음식물이 지나가는 자리에 내는 구멍을 내지 않았다.","scoring_points":["소화 경로를 항문까지 썼는가","작은창자·큰창자의 흡수를 썼는가","간·쓸개·이자는 지나가지 않고 돕는다고 썼는가"]},"explanation":["일지 첫 줄부터예요.","흡수하는 곳을 나눠요.","구멍을 내지 않은 까닭이에요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#25','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C30',4,'essay','teacher','튼튼반 일지 ⑥의 세 값이 어떻게 달라졌는지 쓰고, 일지 ⑧의 민호 생각을 여러 기관과 관련지어 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ⑥의 세 값이 어떻게 달라졌는지 쓰고, 일지 ⑧의 민호 생각을 여러 기관과 관련지어 바로잡아 쓰세요.","answer_guide":{"answer":"예: 운동 전 36.4 °C, 74회였던 체온과 맥박 수가 제자리 뛰기 직후에는 36.8 °C, 104회로 높아졌고, 5분 휴식 후에는 36.6 °C, 86회로 차츰 운동 전으로 돌아갔다. 민호야, 심장이 빨리 뛰는 건 그냥 힘들어서가 아니야. 근육이 움직이려면 산소와 영양소가 필요해서, 호흡기관은 산소를 많이 받아들이려고 호흡이 빨라지고 순환기관은 산소와 영양소를 빠르게 운반하려고 심장이 빨리 뛰는 거야.","scoring_points":["직후에 높아지고 휴식 후 돌아간다고 썼는가","산소와 영양소가 필요하다는 까닭을 썼는가","호흡기관과 순환기관을 이어 민호를 바로잡았는가"]},"explanation":["세 줄을 견줘요.","근육에 필요한 것이에요.","민호에게 말해 줘요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#1','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C16',1,'mc','auto','심장이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X22','SC5-1-u4-X32']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C16","difficulty":1,"kind":"mc","stem":"심장이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"펌프 작용으로 혈액을 온몸으로 보낸다","correct":true},{"t":"혈액을 새로 만들어 낸다","mis":"SC5-1-u4-X17"},{"t":"음식물 속의 영양소를 흡수한다","mis":"SC5-1-u4-X22"},{"t":"혈액 속의 노폐물을 걸러 낸다","mis":"SC5-1-u4-X32"}],"explanation":["모형의 펌프예요.","보내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#2','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C25',1,'ox','auto','콩팥은 혈액 속의 노폐물을 걸러 내어 오줌을 만들어요.',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C25","difficulty":1,"kind":"ox","stem":"콩팥은 혈액 속의 노폐물을 걸러 내어 오줌을 만들어요.","answer":"O","reason_options":[{"t":"배설기관 가운데 노폐물을 걸러 내는 기관이기 때문에","correct":true},{"t":"오줌은 방광에서 새로 만들어지기 때문에","mis":"SC5-1-u4-X32"}],"mis":"SC5-1-u4-X32","explanation":["생각 그물을 떠올려요.","콩팥이 만들어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#3','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C19',1,'sa','auto','순환기관 모형실험에서 우리 몸의 혈관과 같은 역할을 하는 것은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C19","difficulty":1,"kind":"sa","stem":"순환기관 모형실험에서 우리 몸의 혈관과 같은 역할을 하는 것은 무엇인지 쓰세요.","answer":["호스"],"explanation":["혈액이 지나가는 통로예요.","길쭉한 관이에요.","호스예요."],"mis":"SC5-1-u4-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#4','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C33',1,'mc','auto','튼튼반 일지 ⑦에서 감기의 예방법으로 적은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C33","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ⑦에서 감기의 예방법으로 적은 것은 어느 것인가요?","options":[{"t":"손 씻기","correct":true},{"t":"채소 많이 먹기","mis":"SC5-1-u4-X44"},{"t":"운이 좋기를 바라기","mis":"SC5-1-u4-X42"},{"t":"약만 먹기","mis":"SC5-1-u4-X43"}],"explanation":["2모둠 줄을 읽어요.","손이에요.","손 씻기예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#5','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C15',1,'blank','auto','「심장과 혈관처럼 혈액이 온몸을 돌게 하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C15","difficulty":1,"kind":"blank","stem":"「심장과 혈관처럼 혈액이 온몸을 돌게 하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"순환기관","correct":true},{"t":"소화기관","mis":"SC5-1-u4-X22"},{"t":"호흡기관","mis":"SC5-1-u4-X22"},{"t":"배설기관","mis":"SC5-1-u4-X22"}],"explanation":["혈액이 돌아요.","순환이에요.","순환기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#6','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C17',1,'mc','auto','혈관에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X18','SC5-1-u4-X24','SC5-1-u4-X17']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C17","difficulty":1,"kind":"mc","stem":"혈관에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 이동하는 통로로 온몸에 퍼져 있다","correct":true},{"t":"심장 가까이에만 있다","mis":"SC5-1-u4-X18"},{"t":"공기가 이동하는 통로이다","mis":"SC5-1-u4-X24"},{"t":"혈액을 새로 만들어 낸다","mis":"SC5-1-u4-X17"}],"explanation":["모형의 호스예요.","온몸에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#7','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C35',1,'mc','auto','건강한 생활 방식 점검표에 넣기 알맞은 내용은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C35","difficulty":1,"kind":"mc","stem":"건강한 생활 방식 점검표에 넣기 알맞은 내용은 어느 것인가요?","options":[{"t":"「물을 충분히 마셨나요?」","correct":true},{"t":"「한 달 동안 한 번도 아프지 않았나요?」","mis":"SC5-1-u4-X46"},{"t":"「하루에 열 시간씩 공부와 운동을 했나요?」","mis":"SC5-1-u4-X46"},{"t":"「건강 장치를 새로 샀나요?」","mis":"SC5-1-u4-X48"}],"explanation":["날마다 할 수 있나요?","실천할 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#8','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C23',1,'mc','auto','튼튼반 일지 ④에서 어지러움을 느낀 친구가 활동을 멈춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C23","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ④에서 어지러움을 느낀 친구가 활동을 멈춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"무리하지 않고 어지럼증을 느끼면 활동을 멈추어야 하기 때문에","correct":true},{"t":"봉투가 다 부풀었기 때문에","mis":"SC5-1-u4-X29"},{"t":"숨이 찰 때까지 불어야 했기 때문에","mis":"SC5-1-u4-X29"},{"t":"셀로판테이프가 떨어졌기 때문에","mis":"SC5-1-u4-X29"}],"explanation":["안전 약속이에요.","어지러우면 멈춰요.","첫 번째예요."],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#9','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C25',2,'mc','auto','튼튼반 일지 ⑤의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑤의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"오줌을 모아 두었다가 몸 밖으로 내보낸다","correct":true},{"t":"혈액 속의 노폐물을 걸러 내어 오줌을 만든다","mis":"SC5-1-u4-X32"},{"t":"오줌이 이동하는 통로이다","mis":"SC5-1-u4-X32"},{"t":"혈액을 온몸으로 보낸다","mis":"SC5-1-u4-X32"}],"explanation":["방광이 하는 일이에요.","모아 두어요.","첫 번째예요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#10','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C5',2,'sa','auto','「가슴을 둘러싸 심장과 폐를 보호하는 뼈는 □□뼈입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C5","difficulty":2,"kind":"sa","stem":"「가슴을 둘러싸 심장과 폐를 보호하는 뼈는 □□뼈입니다.」 □□에 알맞은 말을 쓰세요.","answer":["갈비","갈비뼈"],"explanation":["가슴의 뼈예요.","두 글자예요.","갈비뼈예요."],"mis":"SC5-1-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#11','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C26',2,'ox','auto','똥을 누는 것도 배설이에요.',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"ox","stem":"똥을 누는 것도 배설이에요.","answer":"X","reason_options":[{"t":"배설은 혈액 속 노폐물을 걸러 내보내는 것이고 똥을 누는 것은 배출이기 때문에","correct":true},{"t":"몸 밖으로 내보내는 것은 모두 배설이기 때문에","mis":"SC5-1-u4-X30"}],"mis":"SC5-1-u4-X30","explanation":["배설과 배출을 견줘요.","똥은 배출이에요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#12','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C19',2,'mc','auto','튼튼반 일지 ③에서 펌프를 멈추자 붉은 색소 물도 멈춘 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X21','SC5-1-u4-X23']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C19","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ③에서 펌프를 멈추자 붉은 색소 물도 멈춘 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"심장이 펌프 작용을 해야 혈액이 온몸을 돈다","correct":true},{"t":"혈관이 스스로 혈액을 밀어 보낸다","mis":"SC5-1-u4-X21"},{"t":"혈액은 심장 없이도 계속 돈다","mis":"SC5-1-u4-X21"},{"t":"심장이 멈추면 혈액이 더 빨리 돈다","mis":"SC5-1-u4-X23"}],"explanation":["펌프는 심장이에요.","멈추면 돌지 못해요.","첫 번째예요."],"asset":{"type":"passage","lines":["펌프, 호스, 붉은 색소 물로 순환기관 모형실험을 했다.","펌프를 쥐었다 폈다 하자 붉은 색소 물이 호스를 따라 돌았다.","펌프를 멈추자 붉은 색소 물도 멈추었다.","실험이 끝난 뒤 주변을 정리하고 물을 올바르게 처리했다."],"title":"튼튼반 탐구 일지 ③ 순환기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#13','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C32',2,'match','auto','질병과 관련 있는 기관을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C32","difficulty":2,"kind":"match","stem":"질병과 관련 있는 기관을 알맞게 이으세요.","pairs":[{"l":"감기","r":"호흡기관"},{"l":"변비","r":"소화기관"},{"l":"『실험관찰』이 예로 든 빈혈","r":"순환기관"}],"mis":"SC5-1-u4-X44","explanation":["증상을 떠올려요.","기침, 똥, 혈액이에요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#14','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C21',2,'mc','auto','튼튼반 일지 ④에서 숨을 들이마실 때 공기가 폐에 이르기 바로 전에 지나는 곳은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X26']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C21","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ④에서 숨을 들이마실 때 공기가 폐에 이르기 바로 전에 지나는 곳은 어느 것인가요?","options":[{"t":"숨관가지","correct":true},{"t":"숨관","mis":"SC5-1-u4-X24"},{"t":"코","mis":"SC5-1-u4-X24"},{"t":"식도","mis":"SC5-1-u4-X26"}],"explanation":["폐 바로 앞이에요.","숨관과 폐를 이어요.","숨관가지예요."],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#15','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C34',2,'error','auto','질병을 조사하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"error","stem":"질병을 조사하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"규리 — 「검색 결과 맨 위의 자료 하나만 그대로 옮겨 적었어.」","correct":true,"mis_target":"SC5-1-u4-X45"},{"t":"동하 — 「검색어가 포함된 자료를 골라 썼어.」","mis":"SC5-1-u4-X45"},{"t":"세빈 — 「만든 자료를 공유 플랫폼에 올렸어.」","mis":"SC5-1-u4-X45"}],"explanation":["자료가 많을 때예요.","골라서 써요.","규리가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#16','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C35',2,'mc','auto','튼튼반 일지 ⑦의 하은이 점검표 초안을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑦의 하은이 점검표 초안을 바르게 고친 것은 어느 것인가요?","options":[{"t":"「하루에 한 번 이상 몸을 움직였나요?」","correct":true},{"t":"「하루에 열다섯 시간씩 운동했나요?」","mis":"SC5-1-u4-X46"},{"t":"「운동 대신 장치를 차고 있었나요?」","mis":"SC5-1-u4-X48"},{"t":"「고칠 필요가 없다」","mis":"SC5-1-u4-X46"}],"explanation":["지킬 수 있게 고쳐요.","날마다 할 만큼이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#17','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C26',3,'mc','auto','튼튼반 일지 ⑧에서 서아의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C26","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 서아의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「배설은 콩팥이 혈액 속 노폐물을 걸러 오줌으로 내보내는 거야.」","correct":true},{"t":"「맞아, 똥 누기가 배설이야.」","mis":"SC5-1-u4-X30"},{"t":"「배설은 숨을 내쉬는 거야.」","mis":"SC5-1-u4-X30"},{"t":"「배설과 배출은 같은 말이야.」","mis":"SC5-1-u4-X30"}],"explanation":["일지 ⑤를 떠올려요.","콩팥이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#18','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C31',3,'mc','auto','아침밥을 먹고 학교에서 달리기를 할 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X40','SC5-1-u4-X37']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C31","difficulty":3,"kind":"mc","stem":"아침밥을 먹고 학교에서 달리기를 할 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소화기관은 음식물을 소화하고, 호흡과 심장박동이 빨라지며, 배설기관도 노폐물을 걸러 낸다","correct":true},{"t":"달리기하는 동안 소화기관은 하던 일을 멈춘다","mis":"SC5-1-u4-X40"},{"t":"뼈와 근육만 일하고 다른 기관은 쉰다","mis":"SC5-1-u4-X40"},{"t":"호흡이 느려지고 심장이 느리게 뛴다","mis":"SC5-1-u4-X37"}],"explanation":["쉬는 기관이 있나요?","모두 일해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#19','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C9',3,'ox','auto','뼈와 근육 모형은 도안을 풀로 단단히 붙여 움직이지 않게 만들어요.',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C9","difficulty":3,"kind":"ox","stem":"뼈와 근육 모형은 도안을 풀로 단단히 붙여 움직이지 않게 만들어요.","answer":"X","reason_options":[{"t":"똑딱단추로 이어야 손잡이를 움직일 때 근육 도안과 아래팔뼈 도안이 움직이기 때문에","correct":true},{"t":"단단히 붙일수록 변화가 잘 보이기 때문에","mis":"SC5-1-u4-X02"}],"mis":"SC5-1-u4-X02","explanation":["손잡이를 움직여야 해요.","똑딱단추로 이어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#20','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C12',3,'mc','auto','「흡수는 위에서 다 끝나.」라고 말하는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X11','SC5-1-u4-X14']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C12","difficulty":3,"kind":"mc","stem":"「흡수는 위에서 다 끝나.」라고 말하는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「영양소와 대부분의 수분은 작은창자에서, 찌꺼기의 수분은 큰창자에서 흡수돼.」","correct":true},{"t":"「맞아, 위가 다 흡수해.」","mis":"SC5-1-u4-X11"},{"t":"「흡수는 입에서 다 끝나.」","mis":"SC5-1-u4-X11"},{"t":"「음식물은 흡수되지 않고 모두 나가.」","mis":"SC5-1-u4-X14"}],"explanation":["튼튼반 일지 ②를 떠올려요.","창자에서 흡수해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#21','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C34',3,'mc','auto','튼튼반 일지 ⑦의 조사 자료를 다른 모둠과 나누는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C34","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑦의 조사 자료를 다른 모둠과 나누는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"공유 플랫폼에 올리고 알게 된 점을 댓글로 나눈다","correct":true},{"t":"우리 모둠만 보고 나누지 않는다","mis":"SC5-1-u4-X45"},{"t":"다른 모둠 자료를 베껴 우리 것처럼 올린다","mis":"SC5-1-u4-X45"},{"t":"자료 없이 기억나는 대로만 말한다","mis":"SC5-1-u4-X45"}],"explanation":["함께 나누어요.","올리고 댓글을 달아요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#22','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C20',3,'mc','auto','공기의 길과 음식물의 길을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u4-X26']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C20","difficulty":3,"kind":"mc","stem":"공기의 길과 음식물의 길을 바르게 견준 것은 어느 것인가요?","options":[{"t":"공기는 코 → 숨관 → 숨관가지 → 폐로, 음식물은 입 → 식도 → 위로 간다","correct":true},{"t":"공기와 음식물 모두 숨관을 지난다","mis":"SC5-1-u4-X26"},{"t":"공기와 음식물 모두 식도를 지난다","mis":"SC5-1-u4-X26"},{"t":"공기는 식도를 지나 위로 간다","mis":"SC5-1-u4-X26"}],"explanation":["두 길은 달라요.","숨관과 식도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#23','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C31',4,'mc','auto','먹은 음식물의 영양소가 달리기하는 다리 근육에 쓰이기까지, 기관이 일하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X27','SC5-1-u4-X40']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"mc","stem":"먹은 음식물의 영양소가 달리기하는 다리 근육에 쓰이기까지, 기관이 일하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"소화기관이 흡수한다 → 순환기관이 운반한다 → 근육이 쓴다","correct":true},{"t":"순환기관이 흡수한다 → 소화기관이 운반한다 → 근육이 쓴다","mis":"SC5-1-u4-X22"},{"t":"호흡기관이 흡수한다 → 배설기관이 운반한다 → 근육이 쓴다","mis":"SC5-1-u4-X27"},{"t":"근육이 음식물을 바로 흡수해 쓴다","mis":"SC5-1-u4-X40"}],"explanation":["흡수, 운반, 쓰기예요.","소화기관부터예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#24','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C18',4,'essay','teacher','튼튼반 일지 ③의 모형실험에서 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 펌프를 멈추자 물도 멈춘 것을 우리 몸과 관련지어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C18","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ③의 모형실험에서 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 펌프를 멈추자 물도 멈춘 것을 우리 몸과 관련지어 쓰세요.","answer_guide":{"answer":"예: 펌프는 심장, 호스는 혈관, 붉은 색소 물은 혈액과 같다. 펌프를 멈추자 물이 멈춘 것처럼, 심장이 펌프 작용을 멈추면 혈액이 순환하지 못해 영양소와 산소를 온몸에 운반할 수 없다. 그래서 심장박동이 멈추면 빠른 시간 안에 심폐 소생술을 해야 한다.","scoring_points":["세 가지를 바르게 짝지었는가","심장이 멈추면 혈액이 순환하지 못한다고 썼는가","영양소와 산소를 운반하지 못한다고 이었는가"]},"explanation":["짝부터 지어요.","멈추면 어떻게 될까요?","우리 몸과 이어요."],"asset":{"type":"passage","lines":["펌프, 호스, 붉은 색소 물로 순환기관 모형실험을 했다.","펌프를 쥐었다 폈다 하자 붉은 색소 물이 호스를 따라 돌았다.","펌프를 멈추자 붉은 색소 물도 멈추었다.","실험이 끝난 뒤 주변을 정리하고 물을 올바르게 처리했다."],"title":"튼튼반 탐구 일지 ③ 순환기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#25','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C33',4,'essay','teacher','튼튼반 일지 ⑦을 보고 두 질병과 관련 있는 기관과 예방법을 쓰고, 하은이의 점검표 초안을 실천할 수 있게 고쳐 쓰세요. 그리고 일지 ⑧의 지우에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C33","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ⑦을 보고 두 질병과 관련 있는 기관과 예방법을 쓰고, 하은이의 점검표 초안을 실천할 수 있게 고쳐 쓰세요. 그리고 일지 ⑧의 지우에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 변비는 소화기관과 관련이 있고 채소를 많이 먹고 물을 충분히 마시며 운동하면 예방에 도움이 된다. 감기는 호흡기관과 관련이 있고 손 씻기로 예방에 도움을 줄 수 있다. 하은이의 초안은 「하루에 한 번 이상 몸을 움직였나요?」처럼 날마다 실천할 수 있게 고친다. 지우야, 질병은 운이 나빠서 걸리는 것이 아니라 몸의 기관과 관련이 있고, 우리가 날마다 실천하는 생활 습관으로 예방에 도움을 줄 수 있어.","scoring_points":["두 질병의 기관과 예방법을 썼는가","점검표를 실천할 수 있게 고쳤는가","생활 습관으로 예방할 수 있다고 지우를 바로잡았는가"]},"explanation":["두 모둠을 읽어요.","점검표를 고쳐요.","지우에게 말해 줘요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#1','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C20',1,'mc','auto','숨관이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X26']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"mc","stem":"숨관이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"공기가 이동하는 통로이다","correct":true},{"t":"산소를 받아들인다","mis":"SC5-1-u4-X24"},{"t":"음식물이 위로 이동하는 통로이다","mis":"SC5-1-u4-X26"},{"t":"오줌이 이동하는 통로이다","mis":"SC5-1-u4-X24"}],"explanation":["코와 숨관가지 사이예요.","공기가 지나가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#2','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C29',1,'ox','auto','운동 직후에는 맥박 수가 운동 전보다 적어져요.',ARRAY['SC5-1-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"ox","stem":"운동 직후에는 맥박 수가 운동 전보다 적어져요.","answer":"X","reason_options":[{"t":"산소와 영양소를 빠르게 운반하려고 심장이 빠르게 뛰어 맥박 수가 많아지기 때문에","correct":true},{"t":"운동을 하면 심장이 느리게 뛰기 때문에","mis":"SC5-1-u4-X37"}],"mis":"SC5-1-u4-X37","explanation":["달리기한 뒤를 떠올려요.","두근두근 빨라요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#3','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C28',1,'sa','auto','「심장의 박동이 목이나 팔목 등에서 느껴지는 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C28","difficulty":1,"kind":"sa","stem":"「심장의 박동이 목이나 팔목 등에서 느껴지는 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["맥박"],"explanation":["팔목을 짚어 봐요.","두 글자예요.","맥박이에요."],"mis":"SC5-1-u4-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#4','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',1,'mc','auto','착용형 장치가 몸속 기관의 기능에 생긴 문제를 발견하면 어떻게 하나요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C36","difficulty":1,"kind":"mc","stem":"착용형 장치가 몸속 기관의 기능에 생긴 문제를 발견하면 어떻게 하나요?","options":[{"t":"경고 신호를 울려 알려 준다","correct":true},{"t":"아무것도 하지 않는다","mis":"SC5-1-u4-X49"},{"t":"장치가 스스로 병을 고친다","mis":"SC5-1-u4-X48"},{"t":"장치가 꺼져 버린다","mis":"SC5-1-u4-X49"}],"explanation":["과학이 톡톡을 떠올려요.","신호가 울려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#5','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C26',1,'blank','auto','「큰창자를 지난 음식물 찌꺼기가 항문으로 나가는 것은 배설이 아니라 (    )입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C26","difficulty":1,"kind":"blank","stem":"「큰창자를 지난 음식물 찌꺼기가 항문으로 나가는 것은 배설이 아니라 (    )입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"배출","correct":true},{"t":"소화","mis":"SC5-1-u4-X30"},{"t":"순환","mis":"SC5-1-u4-X30"},{"t":"호흡","mis":"SC5-1-u4-X30"}],"explanation":["찌꺼기를 내보내요.","배설과 다른 말이에요.","배출이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#6','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C22',1,'mc','auto','튼튼반 일지 ④의 ( ? )에 들어갈 길로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X25','SC5-1-u4-X26']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C22","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ④의 ( ? )에 들어갈 길로 알맞은 것은 어느 것인가요?","options":[{"t":"폐 → 숨관가지 → 숨관 → 코","correct":true},{"t":"코 → 숨관 → 숨관가지 → 폐","mis":"SC5-1-u4-X25"},{"t":"폐 → 식도 → 입","mis":"SC5-1-u4-X26"},{"t":"코 → 숨관가지 → 숨관 → 폐","mis":"SC5-1-u4-X25"}],"explanation":["내쉴 때예요.","들이마실 때를 거꾸로 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#7','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C27',1,'mc','auto','식사할 때 함께 일하는 것끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C27","difficulty":1,"kind":"mc","stem":"식사할 때 함께 일하는 것끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"팔뼈와 팔 근육, 얼굴 근육, 소화기관","correct":true},{"t":"소화기관 하나만","mis":"SC5-1-u4-X35"},{"t":"얼굴 근육 하나만","mis":"SC5-1-u4-X35"},{"t":"모든 기관이 쉬고 입만 움직인다","mis":"SC5-1-u4-X35"}],"explanation":["포크로 넣고 씹어요.","여러 기관이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#8','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C34',1,'mc','auto','자료를 만들다가 스마트 기기에서 냄새가 나요. 어떻게 해야 하나요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C34","difficulty":1,"kind":"mc","stem":"자료를 만들다가 스마트 기기에서 냄새가 나요. 어떻게 해야 하나요?","options":[{"t":"즉시 사용을 멈추고 선생님께 알린다","correct":true},{"t":"자료를 다 만들 때까지 계속 쓴다","mis":"SC5-1-u4-X45"},{"t":"세게 흔들어 본다","mis":"SC5-1-u4-X45"},{"t":"물을 부어 식힌다","mis":"SC5-1-u4-X45"}],"explanation":["안전이 먼저예요.","멈추고 알려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#9','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C30',2,'mc','auto','튼튼반 일지 ⑥에서 운동 직후 맥박 수가 많아진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X17','SC5-1-u4-X37']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C30","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑥에서 운동 직후 맥박 수가 많아진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빠르게 뛰었기 때문에","correct":true},{"t":"단지 몸이 힘들었기 때문에","mis":"SC5-1-u4-X39"},{"t":"혈액을 더 많이 만들어 내려고","mis":"SC5-1-u4-X17"},{"t":"체온을 낮추려고","mis":"SC5-1-u4-X37"}],"explanation":["근육에 필요한 것을 떠올려요.","빠르게 날라요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#10','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C33',2,'sa','auto','「변비를 예방하려면 채소를 많이 먹고, □을 충분히 마시며, 운동을 합니다.」 □에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"sa","stem":"「변비를 예방하려면 채소를 많이 먹고, □을 충분히 마시며, 운동을 합니다.」 □에 알맞은 말을 쓰세요.","answer":["물"],"explanation":["마시는 것이에요.","한 글자예요.","물이에요."],"mis":"SC5-1-u4-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#11','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C27',2,'ox','auto','잠을 자는 동안에도 우리 몸은 호흡을 해요.',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C27","difficulty":2,"kind":"ox","stem":"잠을 자는 동안에도 우리 몸은 호흡을 해요.","answer":"O","reason_options":[{"t":"잠을 잘 때도 기관이 끊임없이 일하며 활동할 때보다 천천히 호흡하기 때문에","correct":true},{"t":"잠을 자면 호흡이 멈추었다가 깨면 다시 시작하기 때문에","mis":"SC5-1-u4-X35"}],"mis":"SC5-1-u4-X35","explanation":["자는 동안을 떠올려요.","천천히 숨을 쉬어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#12','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C33',2,'mc','auto','튼튼반 일지 ⑦에서 1모둠이 적은 변비의 예방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X44']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑦에서 1모둠이 적은 변비의 예방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"채소 먹기, 물 마시기, 운동하기","correct":true},{"t":"손 씻기만 하기","mis":"SC5-1-u4-X44"},{"t":"하루 종일 누워서 쉬기","mis":"SC5-1-u4-X44"},{"t":"단 음식을 자주 먹기","mis":"SC5-1-u4-X44"}],"explanation":["1모둠 줄을 읽어요.","세 가지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#13','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C25',2,'match','auto','콩팥을 지난 뒤의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"match","stem":"콩팥을 지난 뒤의 모습을 알맞게 이으세요.","pairs":[{"l":"노폐물이 많은 혈액","r":"혈관을 따라 콩팥으로 들어온다"},{"l":"노폐물이 걸러진 혈액","r":"다시 온몸을 순환한다"},{"l":"콩팥에서 만든 오줌","r":"오줌관과 방광을 거쳐 몸 밖으로 나간다"}],"mis":"SC5-1-u4-X33","explanation":["두 갈래를 떠올려요.","혈액과 오줌이에요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#14','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C28',2,'mc','auto','튼튼반 일지 ⑥처럼 체온과 맥박 수를 재는 세 번의 때로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C28","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑥처럼 체온과 맥박 수를 재는 세 번의 때로 알맞은 것은 어느 것인가요?","options":[{"t":"운동 전, 운동 직후, 5분 휴식 후","correct":true},{"t":"운동 전에만 세 번","mis":"SC5-1-u4-X41"},{"t":"운동 직후에만 세 번","mis":"SC5-1-u4-X41"},{"t":"운동 전, 하루 쉰 뒤, 다음 주","mis":"SC5-1-u4-X41"}],"explanation":["일지 세 줄이에요.","전, 직후, 휴식 후예요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#15','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',2,'error','auto','착용형 장치를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"error","stem":"착용형 장치를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「착용형 장치는 병원에서만 쓸 수 있어.」","correct":true,"mis_target":"SC5-1-u4-X49"},{"t":"리아 — 「손목시계나 반지 모양이라 차기 쉬워.」","mis":"SC5-1-u4-X49"},{"t":"강민 — 「장치가 알려 줘도 실천은 내가 해야 해.」","mis":"SC5-1-u4-X48"}],"explanation":["언제 어디서나 쓸 수 있나요?","몸에 차고 다녀요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#16','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C23',2,'mc','auto','호흡기관 모형에서 주름 빨대와 종이봉투 사이를 셀로판테이프로 잘 막는 까닭은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C23","difficulty":2,"kind":"mc","stem":"호흡기관 모형에서 주름 빨대와 종이봉투 사이를 셀로판테이프로 잘 막는 까닭은 어느 것인가요?","options":[{"t":"공기가 새지 않게 하려고","correct":true},{"t":"봉투를 더 무겁게 하려고","mis":"SC5-1-u4-X29"},{"t":"봉투가 부풀지 않게 하려고","mis":"SC5-1-u4-X29"},{"t":"빨대를 예쁘게 꾸미려고","mis":"SC5-1-u4-X29"}],"explanation":["불어 넣은 공기는요?","새면 안 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#17','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C30',3,'mc','auto','튼튼반 일지 ⑧에서 민호의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X37','SC5-1-u4-X17']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C30","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 민호의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빨리 뛰는 거야.」","correct":true},{"t":"「맞아, 그냥 힘들어서야.」","mis":"SC5-1-u4-X39"},{"t":"「운동하면 심장이 느려져.」","mis":"SC5-1-u4-X37"},{"t":"「혈액을 더 많이 만들려고 그래.」","mis":"SC5-1-u4-X17"}],"explanation":["근육에 필요한 것이에요.","빨리 날라야 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#18','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C18',3,'mc','auto','작은창자에서 흡수한 영양소가 다리 근육에 닿기까지를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X10','SC5-1-u4-X26','SC5-1-u4-X22']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C18","difficulty":3,"kind":"mc","stem":"작은창자에서 흡수한 영양소가 다리 근육에 닿기까지를 바르게 말한 것은 어느 것인가요?","options":[{"t":"혈액이 영양소를 싣고 혈관을 따라 다리 근육까지 운반한다","correct":true},{"t":"영양소가 식도를 거쳐 다시 올라갔다가 내려간다","mis":"SC5-1-u4-X10"},{"t":"영양소가 숨관을 따라 다리로 간다","mis":"SC5-1-u4-X26"},{"t":"영양소는 작은창자에만 머문다","mis":"SC5-1-u4-X22"}],"explanation":["운반하는 것이에요.","혈액과 혈관이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#19','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C29',3,'ox','auto','운동을 마치고 5분 휴식하면 체온과 맥박 수가 운동 직후보다 더 높아져요.',ARRAY['SC5-1-u4-X38']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C29","difficulty":3,"kind":"ox","stem":"운동을 마치고 5분 휴식하면 체온과 맥박 수가 운동 직후보다 더 높아져요.","answer":"X","reason_options":[{"t":"휴식하면 체온과 맥박 수가 차츰 운동 전으로 돌아가기 때문에","correct":true},{"t":"한번 오른 체온과 맥박 수는 계속 오르기 때문에","mis":"SC5-1-u4-X38"}],"mis":"SC5-1-u4-X38","explanation":["튼튼반 일지 ⑥을 떠올려요.","86회로 줄었어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#20','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C26',3,'mc','auto','튼튼반 일지 ⑤에서 친구가 「똥 누기」 카드를 배설 가지에서 뗀 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X34']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C26","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑤에서 친구가 「똥 누기」 카드를 배설 가지에서 뗀 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"똥을 누는 것은 음식물 찌꺼기를 내보내는 배출이기 때문에","correct":true},{"t":"똥 누기도 배설이지만 붙일 자리가 없었기 때문에","mis":"SC5-1-u4-X30"},{"t":"똥은 오줌관을 지나 나가기 때문에","mis":"SC5-1-u4-X34"},{"t":"똥은 콩팥에서 만들어지기 때문에","mis":"SC5-1-u4-X30"}],"explanation":["배설과 배출이에요.","똥은 배출이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#21','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C1',3,'mc','auto','몸속의 뼈가 여러 개로 이어져 있지 않고 커다란 하나라면 어떻게 될까요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C1","difficulty":3,"kind":"mc","stem":"몸속의 뼈가 여러 개로 이어져 있지 않고 커다란 하나라면 어떻게 될까요?","options":[{"t":"팔과 다리를 구부리는 등 다양한 몸동작을 하기 어렵다","correct":true},{"t":"지금보다 더 다양한 몸동작을 할 수 있다","mis":"SC5-1-u4-X01"},{"t":"근육이 없어도 몸이 움직인다","mis":"SC5-1-u4-X03"},{"t":"아무 차이가 없다","mis":"SC5-1-u4-X01"}],"explanation":["골격 모형을 떠올려요.","이은 곳이 접혔어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#22','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C28',3,'mc','auto','튼튼반 일지 ⑥의 값을 그래프로 나타낼 때 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C28","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑥의 값을 그래프로 나타낼 때 알맞은 것은 어느 것인가요?","options":[{"t":"운동 전, 운동 직후, 5분 휴식 후의 차례로 잰 값을 그대로 나타낸다","correct":true},{"t":"예상에 맞도록 값을 고쳐 나타낸다","mis":"SC5-1-u4-X41"},{"t":"운동 직후 값은 빼고 나타낸다","mis":"SC5-1-u4-X41"},{"t":"친구가 잰 값을 가져와 나타낸다","mis":"SC5-1-u4-X41"}],"explanation":["잰 차례대로예요.","고치지 않아요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#23','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',4,'mc','auto','밤사이 착용형 장치가 심장박동 수가 갑자기 달라졌다며 경고 신호를 보냈어요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C36","difficulty":4,"kind":"mc","stem":"밤사이 착용형 장치가 심장박동 수가 갑자기 달라졌다며 경고 신호를 보냈어요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"몸에 문제가 생겼을 수 있으니 어른께 알리고 몸 상태를 살핀다","correct":true},{"t":"신호를 무시하고 장치를 끈다","mis":"SC5-1-u4-X49"},{"t":"장치가 알아서 고쳐 줄 테니 그냥 둔다","mis":"SC5-1-u4-X48"},{"t":"장치를 더 예쁜 것으로 바꾼다","mis":"SC5-1-u4-X49"}],"explanation":["경고 신호의 뜻이에요.","문제가 생겼다는 신호예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#24','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C22',4,'essay','teacher','튼튼반 일지 ④의 ( ? )에 들어갈 길을 쓰고, 들이마실 때와 내쉴 때 폐가 하는 일을 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ④의 ( ? )에 들어갈 길을 쓰고, 들이마실 때와 내쉴 때 폐가 하는 일을 각각 쓰세요.","answer_guide":{"answer":"예: ( ? )에는 「폐 → 숨관가지 → 숨관 → 코」가 들어간다. 숨을 들이마시면 폐는 우리 몸에 필요한 산소를 받아들이고, 숨을 내쉬면 몸속에서 생긴 이산화 탄소를 포함한 공기를 몸 밖으로 내보낸다. 두 길은 같은 길이고 방향만 반대이다.","scoring_points":["내쉬는 길을 바르게 썼는가","들이마실 때 산소를 받아들인다고 썼는가","내쉴 때 이산화 탄소를 내보낸다고 썼는가"]},"explanation":["거꾸로 써요.","들이마실 때 폐는요?","내쉴 때 폐는요?"],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#25','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C31',4,'essay','teacher','「우리 몸의 구조와 기능」 단원에서 배운 것을 「뼈와 근육 → 소화·순환·호흡·배설기관 → 운동할 때 서로 영향을 주고받는 기관 → 질병과 건강한 생활」의 차례로 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"essay","stem":"「우리 몸의 구조와 기능」 단원에서 배운 것을 「뼈와 근육 → 소화·순환·호흡·배설기관 → 운동할 때 서로 영향을 주고받는 기관 → 질병과 건강한 생활」의 차례로 정리해 쓰세요.","answer_guide":{"answer":"예: 뼈는 몸의 형태를 만들고 지탱하며 몸속 기관을 보호하고, 근육이 줄어들거나 늘어나면서 뼈를 움직여 몸이 움직인다. 소화기관은 음식물을 잘게 쪼개 영양소를 흡수하고, 호흡기관은 산소를 받아들이며, 순환기관은 영양소와 산소를 온몸에 운반하고, 배설기관은 혈액 속의 노폐물을 걸러 몸 밖으로 내보낸다. 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 것처럼 각 기관은 서로 영향을 주고받으며 작용한다. 다양한 질병은 우리 몸의 기관과 관련이 있으며, 건강한 생활 방식을 꾸준히 실천하면 예방에 도움이 된다.","scoring_points":["뼈와 근육이 하는 일을 썼는가","네 기관이 하는 일을 바르게 썼는가","서로 영향을 주고받음과 질병 예방을 썼는가"]},"explanation":["뼈와 근육부터예요.","네 기관을 넣어요.","서로 영향과 건강으로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
